--
-- Name: pet_deworming_status; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pet_deworming_status AS
 SELECT DISTINCT ON (pet_id) pet_id,
    organization_id,
    id AS deworming_record_id,
    product,
    date_administered,
    next_due_date
   FROM public.deworming_records d
  WHERE (deleted_at IS NULL)
  ORDER BY pet_id, date_administered DESC, created_at DESC;


