COPY supabase_migrations.schema_migrations (version, statements, name) FROM stdin;
20260820000100	{"-- Phase 1 · Checkpoint 2 — core schema.\n--\n-- Tables: organizations, branches, roles, user_roles, users, doctors, staff,\n-- clients, audit_logs.\n--\n-- Row level security is ENABLED on every table here but no policies are\n-- created until migration 0002. Postgres denies all access to a table with RLS\n-- enabled and no matching policy, so the default state between these two\n-- migrations is deny-all rather than wide open.\n\ncreate extension if not exists \\"citext\\" with schema extensions","-- ---------------------------------------------------------------------------\n-- Shared helpers\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.set_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$","comment on function public.set_updated_at() is\n  'Maintains updated_at on row modification. Attached per table below.'","-- ---------------------------------------------------------------------------\n-- organizations\n-- ---------------------------------------------------------------------------\n\ncreate table public.organizations (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  slug text not null,\n  legal_name text,\n  -- Display timezone for the whole organization. All stored timestamps are\n  -- timestamptz (UTC); this is presentation only.\n  timezone text not null default 'Asia/Dhaka',\n  email extensions.citext,\n  phone text,\n  address text,\n  city text,\n  country text not null default 'Bangladesh',\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n  constraint organizations_name_not_blank check (length(btrim(name)) > 0),\n  constraint organizations_slug_format check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')\n)","create unique index organizations_slug_key\n  on public.organizations (slug)\n  where deleted_at is null","comment on table public.organizations is\n  'Top of the tenancy hierarchy: Organization -> Branch -> Doctor/Staff/Client -> Patient.'","-- ---------------------------------------------------------------------------\n-- branches\n-- ---------------------------------------------------------------------------\n\ncreate table public.branches (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  name text not null,\n  slug text not null,\n  is_primary boolean not null default false,\n  email extensions.citext,\n  phone text,\n  address text,\n  city text,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n  constraint branches_name_not_blank check (length(btrim(name)) > 0),\n  constraint branches_slug_format check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')\n)","create unique index branches_organization_id_slug_key\n  on public.branches (organization_id, slug)\n  where deleted_at is null","-- At most one primary branch per organization.\ncreate unique index branches_one_primary_per_organization\n  on public.branches (organization_id)\n  where is_primary and deleted_at is null","create index branches_organization_id_idx on public.branches (organization_id)","-- ---------------------------------------------------------------------------\n-- roles\n-- ---------------------------------------------------------------------------\n\ncreate table public.roles (\n  id uuid primary key default gen_random_uuid(),\n  slug text not null unique,\n  name text not null,\n  description text,\n  -- super_admin is architecture only for now and must not be offered in the UI.\n  is_assignable_in_ui boolean not null default true,\n  created_at timestamptz not null default now(),\n  constraint roles_slug_allowed check (slug in ('client', 'doctor', 'admin', 'super_admin'))\n)","comment on table public.roles is\n  'Reference data. Seeded below; not user-editable.'","-- ---------------------------------------------------------------------------\n-- users (profile, 1:1 with auth.users)\n-- ---------------------------------------------------------------------------\n\ncreate table public.users (\n  -- Same UUID as auth.users. restrict, not cascade: deleting a login must\n  -- never silently destroy records that clinical history hangs off.\n  id uuid primary key references auth.users (id) on delete restrict,\n  full_name text not null,\n  email extensions.citext not null,\n  phone text,\n  avatar_url text,\n  is_active boolean not null default true,\n  last_login_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n  constraint users_full_name_not_blank check (length(btrim(full_name)) > 0),\n  constraint users_phone_format check (phone is null or phone ~ '^\\\\+?[0-9][0-9 ()-]{5,19}$')\n)","create unique index users_email_key\n  on public.users (email)\n  where deleted_at is null","comment on table public.users is\n  'Application profile for an authenticated account. Auth credentials stay in auth.users.'","-- ---------------------------------------------------------------------------\n-- user_roles\n-- ---------------------------------------------------------------------------\n\ncreate table public.user_roles (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete restrict,\n  role_id uuid not null references public.roles (id) on delete restrict,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  -- null = the role applies across every branch of the organization.\n  branch_id uuid references public.branches (id) on delete restrict,\n  granted_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n  revoked_at timestamptz\n)","-- NULLS NOT DISTINCT so an organization-wide grant cannot be duplicated.\ncreate unique index user_roles_unique_grant\n  on public.user_roles (user_id, role_id, organization_id, branch_id)\n  nulls not distinct\n  where revoked_at is null","create index user_roles_user_id_idx on public.user_roles (user_id)","create index user_roles_organization_id_idx on public.user_roles (organization_id)","create index user_roles_branch_id_idx on public.user_roles (branch_id)","comment on table public.user_roles is\n  'A person can hold different roles in different branches or organizations without a schema change.'","-- ---------------------------------------------------------------------------\n-- doctors\n-- ---------------------------------------------------------------------------\n\ncreate table public.doctors (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete restrict,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  primary_branch_id uuid references public.branches (id) on delete restrict,\n  -- Bangladesh Veterinary Council registration number.\n  registration_number text,\n  specialization text,\n  qualifications text,\n  bio text,\n  signature_url text,\n  is_accepting_appointments boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create unique index doctors_user_id_key\n  on public.doctors (user_id)\n  where deleted_at is null","create unique index doctors_registration_number_key\n  on public.doctors (organization_id, registration_number)\n  where registration_number is not null and deleted_at is null","create index doctors_organization_id_idx on public.doctors (organization_id)","create index doctors_primary_branch_id_idx on public.doctors (primary_branch_id)","-- ---------------------------------------------------------------------------\n-- staff\n-- ---------------------------------------------------------------------------\n\ncreate table public.staff (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete restrict,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  branch_id uuid references public.branches (id) on delete restrict,\n  job_title text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz\n)","create unique index staff_user_id_key\n  on public.staff (user_id)\n  where deleted_at is null","create index staff_organization_id_idx on public.staff (organization_id)","create index staff_branch_id_idx on public.staff (branch_id)","-- ---------------------------------------------------------------------------\n-- clients\n-- ---------------------------------------------------------------------------\n\ncreate table public.clients (\n  id uuid primary key default gen_random_uuid(),\n  -- Nullable: reception can create a walk-in client record before that person\n  -- ever registers a login. Phase 2 extends this table.\n  user_id uuid references public.users (id) on delete restrict,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  preferred_branch_id uuid references public.branches (id) on delete restrict,\n  full_name text not null,\n  email extensions.citext,\n  phone text not null,\n  alternate_phone text,\n  address text,\n  city text,\n  notes text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n  constraint clients_full_name_not_blank check (length(btrim(full_name)) > 0),\n  constraint clients_phone_format check (phone ~ '^\\\\+?[0-9][0-9 ()-]{5,19}$'),\n  constraint clients_alternate_phone_format\n    check (alternate_phone is null or alternate_phone ~ '^\\\\+?[0-9][0-9 ()-]{5,19}$')\n)","create unique index clients_user_id_key\n  on public.clients (user_id)\n  where user_id is not null and deleted_at is null","create unique index clients_organization_id_phone_key\n  on public.clients (organization_id, phone)\n  where deleted_at is null","create index clients_organization_id_idx on public.clients (organization_id)","create index clients_preferred_branch_id_idx on public.clients (preferred_branch_id)","comment on table public.clients is\n  'Pet owner. user_id is null until the person has a login; contact details live here so walk-ins are first-class records.'","-- ---------------------------------------------------------------------------\n-- audit_logs\n-- ---------------------------------------------------------------------------\n\ncreate table public.audit_logs (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid references public.organizations (id) on delete restrict,\n  -- Nullable: system and unauthenticated events (e.g. a failed login) have no actor.\n  actor_user_id uuid references public.users (id) on delete restrict,\n  actor_role text,\n  action text not null,\n  entity_table text,\n  entity_id uuid,\n  metadata jsonb not null default '{}'::jsonb,\n  ip_address inet,\n  user_agent text,\n  created_at timestamptz not null default now(),\n  constraint audit_logs_action_not_blank check (length(btrim(action)) > 0)\n)","create index audit_logs_organization_id_created_at_idx\n  on public.audit_logs (organization_id, created_at desc)","create index audit_logs_entity_idx\n  on public.audit_logs (entity_table, entity_id)","create index audit_logs_actor_user_id_idx\n  on public.audit_logs (actor_user_id)","comment on table public.audit_logs is\n  'Append-only. Written by database triggers in migration 0002, never by application code.'","-- ---------------------------------------------------------------------------\n-- updated_at triggers\n-- ---------------------------------------------------------------------------\n\ncreate trigger organizations_set_updated_at\n  before update on public.organizations\n  for each row execute function public.set_updated_at()","create trigger branches_set_updated_at\n  before update on public.branches\n  for each row execute function public.set_updated_at()","create trigger users_set_updated_at\n  before update on public.users\n  for each row execute function public.set_updated_at()","create trigger doctors_set_updated_at\n  before update on public.doctors\n  for each row execute function public.set_updated_at()","create trigger staff_set_updated_at\n  before update on public.staff\n  for each row execute function public.set_updated_at()","create trigger clients_set_updated_at\n  before update on public.clients\n  for each row execute function public.set_updated_at()","-- ---------------------------------------------------------------------------\n-- Row level security: enabled everywhere, policies land in migration 0002.\n-- ---------------------------------------------------------------------------\n\nalter table public.organizations enable row level security","alter table public.branches enable row level security","alter table public.roles enable row level security","alter table public.users enable row level security","alter table public.user_roles enable row level security","alter table public.doctors enable row level security","alter table public.staff enable row level security","alter table public.clients enable row level security","alter table public.audit_logs enable row level security","-- ---------------------------------------------------------------------------\n-- Table privileges\n--\n-- This Postgres image grants no DML to the PostgREST roles by default, so\n-- privileges must be stated explicitly. GRANT is the coarse gate (which role\n-- may touch a table at all); the RLS policies in migration 0002 are the fine\n-- one (which rows). Both are required.\n--\n-- Every future migration that adds a table must add its grants here too,\n-- alongside its RLS policies.\n-- ---------------------------------------------------------------------------\n\n-- Signed-out callers get nothing. Registration and login go through the auth\n-- API, not through these tables.\nrevoke all on all tables in schema public from anon","-- DELETE and TRUNCATE are granted to nobody: clinical history is soft-deleted\n-- via deleted_at and must never be destroyed.\nrevoke delete, truncate on all tables in schema public from authenticated","grant select on public.roles to authenticated","grant select, insert, update on\n  public.organizations,\n  public.branches,\n  public.users,\n  public.user_roles,\n  public.doctors,\n  public.staff,\n  public.clients\nto authenticated","-- Append-only from the application's point of view: rows are written by the\n-- security-definer trigger in migration 0002, never by a client.\ngrant select on public.audit_logs to authenticated","-- Server-side only. Bypasses RLS entirely, so it is never used from a browser.\ngrant all on all tables in schema public to service_role","-- ---------------------------------------------------------------------------\n-- Reference data\n-- ---------------------------------------------------------------------------\n\ninsert into public.roles (slug, name, description, is_assignable_in_ui)\nvalues\n  ('client', 'Client', 'Pet owner. Own account, own pets, own records only.', true),\n  ('doctor', 'Doctor', 'Assigned or authorized patients. Clinical modules. No financial administration.', true),\n  ('admin', 'Admin', 'Full practice-management and operational data for the organization.', true),\n  ('super_admin', 'Super Admin', 'Multi-organization management. Architecture only — not exposed in the UI.', false)\non conflict (slug) do nothing","-- The first organization. Everything else in the system hangs off this row.\ninsert into public.organizations (name, slug, legal_name, email, city)\nvalues ('The Traveling Vet', 'the-traveling-vet', 'The Traveling Vet', null, 'Dhaka')\non conflict do nothing","insert into public.branches (organization_id, name, slug, is_primary, city)\nselect o.id, 'Main', 'main', true, 'Dhaka'\nfrom public.organizations o\nwhere o.slug = 'the-traveling-vet'\non conflict do nothing"}	core_schema
20260820000200	{"-- Phase 1 · Checkpoint 3 — row level security policies and audit triggers.\n--\n-- Three layers, all required:\n--   1. GRANT   — may this role touch this table/column at all? (migration 0001 + refinements below)\n--   2. POLICY  — which rows may it see or write? (this migration)\n--   3. TRIGGER — what gets recorded, and what is immutable? (this migration)\n\n-- ---------------------------------------------------------------------------\n-- Role helpers\n--\n-- All SECURITY DEFINER so they read user_roles without being subject to that\n-- table's own policies — otherwise a policy on user_roles that consults\n-- user_roles recurses infinitely. Owned by postgres, which has BYPASSRLS.\n--\n-- search_path is pinned to '' so a caller cannot shadow a table name with a\n-- temp table and change what these functions resolve to.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.has_role(p_slug text, p_organization_id uuid default null)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select exists (\n    select 1\n    from public.user_roles ur\n    join public.roles r on r.id = ur.role_id\n    where ur.user_id = (select auth.uid())\n      and ur.revoked_at is null\n      and r.slug = p_slug\n      and (p_organization_id is null or ur.organization_id = p_organization_id)\n  );\n$$","create or replace function public.is_super_admin()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.has_role('super_admin');\n$$","create or replace function public.is_admin(p_organization_id uuid default null)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.has_role('admin', p_organization_id) or public.has_role('super_admin');\n$$","comment on function public.is_admin(uuid) is\n  'Passing null asks \\"is this user an admin of any organization at all\\". Pass a\n   concrete organization_id in any policy guarding tenant-scoped rows.'","create or replace function public.is_doctor(p_organization_id uuid default null)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.has_role('doctor', p_organization_id);\n$$","create or replace function public.is_org_member(p_organization_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.is_super_admin() or exists (\n    select 1\n    from public.user_roles ur\n    where ur.user_id = (select auth.uid())\n      and ur.revoked_at is null\n      and ur.organization_id = p_organization_id\n  );\n$$","comment on function public.is_org_member(uuid) is\n  'True when the caller holds any active role in the organization.'","-- Is the caller an admin of some organization the target user belongs to?\ncreate or replace function public.is_admin_of_user(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select exists (\n    select 1\n    from public.user_roles ur\n    where ur.user_id = p_user_id\n      and ur.revoked_at is null\n      and public.is_admin(ur.organization_id)\n  );\n$$","-- Profile visibility. Deliberately narrow: a client sees themselves and the\n-- doctors of their organization, never another client.\ncreate or replace function public.can_view_user(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select\n    p_user_id = (select auth.uid())\n    or public.is_super_admin()\n    -- Clinic-side people see the people in their own organization.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and (\n          public.is_admin(ur.organization_id)\n          or public.is_doctor(ur.organization_id)\n        )\n    )\n    -- Anyone in the organization may see that organization's doctors, which\n    -- is what makes doctor selection possible at booking time.\n    or exists (\n      select 1\n      from public.user_roles ur\n      join public.roles r on r.id = ur.role_id\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and r.slug = 'doctor'\n        and public.is_org_member(ur.organization_id)\n    );\n$$","revoke all on function\n  public.has_role(text, uuid),\n  public.is_super_admin(),\n  public.is_admin(uuid),\n  public.is_doctor(uuid),\n  public.is_org_member(uuid),\n  public.is_admin_of_user(uuid),\n  public.can_view_user(uuid)\nfrom public, anon","grant execute on function\n  public.has_role(text, uuid),\n  public.is_super_admin(),\n  public.is_admin(uuid),\n  public.is_doctor(uuid),\n  public.is_org_member(uuid),\n  public.is_admin_of_user(uuid),\n  public.can_view_user(uuid)\nto authenticated, service_role","-- ---------------------------------------------------------------------------\n-- Column-level UPDATE privileges\n--\n-- Row policies decide *which rows*; these decide *which columns*. Together\n-- they remove organization_id and user_id from the reach of `authenticated`\n-- entirely, so no policy mistake can let someone re-parent their record into\n-- another organization or claim another person's client record.\n-- ---------------------------------------------------------------------------\n\nrevoke update on\n  public.organizations,\n  public.branches,\n  public.users,\n  public.user_roles,\n  public.doctors,\n  public.staff,\n  public.clients\nfrom authenticated","-- Profiles are created by the signup trigger, never by a client.\nrevoke insert on public.users from authenticated","grant update (name, legal_name, timezone, email, phone, address, city, country, is_active)\n  on public.organizations to authenticated","grant update (name, slug, is_primary, email, phone, address, city, is_active, deleted_at)\n  on public.branches to authenticated","grant update (full_name, phone, avatar_url)\n  on public.users to authenticated","-- Grants are revoked, not deleted.\ngrant update (revoked_at)\n  on public.user_roles to authenticated","grant update (primary_branch_id, registration_number, specialization, qualifications,\n              bio, signature_url, is_accepting_appointments, deleted_at)\n  on public.doctors to authenticated","grant update (branch_id, job_title, deleted_at)\n  on public.staff to authenticated","grant update (preferred_branch_id, full_name, email, phone, alternate_phone,\n              address, city, notes, deleted_at)\n  on public.clients to authenticated","-- ---------------------------------------------------------------------------\n-- Policies\n--\n-- Every policy targets `authenticated` explicitly. anon holds no privileges\n-- on these tables at all, so it never reaches a policy.\n-- ---------------------------------------------------------------------------\n\n-- organizations\ncreate policy organizations_select on public.organizations\n  for select to authenticated\n  using (public.is_org_member(id))","create policy organizations_insert on public.organizations\n  for insert to authenticated\n  with check (public.is_super_admin())","create policy organizations_update on public.organizations\n  for update to authenticated\n  using (public.is_admin(id))\n  with check (public.is_admin(id))","-- branches\ncreate policy branches_select on public.branches\n  for select to authenticated\n  using (public.is_org_member(organization_id))","create policy branches_insert on public.branches\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy branches_update on public.branches\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","-- roles: reference data, readable by any signed-in user.\ncreate policy roles_select on public.roles\n  for select to authenticated\n  using (true)","-- users\ncreate policy users_select on public.users\n  for select to authenticated\n  using (public.can_view_user(id))","create policy users_update on public.users\n  for update to authenticated\n  using (id = (select auth.uid()) or public.is_admin_of_user(id))\n  with check (id = (select auth.uid()) or public.is_admin_of_user(id))","-- user_roles\ncreate policy user_roles_select on public.user_roles\n  for select to authenticated\n  using (user_id = (select auth.uid()) or public.is_admin(organization_id))","create policy user_roles_insert on public.user_roles\n  for insert to authenticated\n  with check (\n    public.is_admin(organization_id)\n    -- Only a super admin can mint another super admin.\n    and (\n      public.is_super_admin()\n      or (select r.slug from public.roles r where r.id = role_id) <> 'super_admin'\n    )\n  )","create policy user_roles_update on public.user_roles\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","-- doctors\ncreate policy doctors_select on public.doctors\n  for select to authenticated\n  using (public.is_org_member(organization_id))","create policy doctors_insert on public.doctors\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy doctors_update on public.doctors\n  for update to authenticated\n  using (public.is_admin(organization_id) or user_id = (select auth.uid()))\n  with check (public.is_admin(organization_id) or user_id = (select auth.uid()))","-- staff\ncreate policy staff_select on public.staff\n  for select to authenticated\n  using (user_id = (select auth.uid()) or public.is_admin(organization_id))","create policy staff_insert on public.staff\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy staff_update on public.staff\n  for update to authenticated\n  using (public.is_admin(organization_id) or user_id = (select auth.uid()))\n  with check (public.is_admin(organization_id) or user_id = (select auth.uid()))","-- clients\n--\n-- A doctor sees the clients of their organization. The brief scopes doctors to\n-- \\"assigned or authorized\\" patients; assignment does not exist until\n-- appointments land in Phase 3, at which point this can be narrowed.\ncreate policy clients_select on public.clients\n  for select to authenticated\n  using (\n    user_id = (select auth.uid())\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy clients_insert on public.clients\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy clients_update on public.clients\n  for update to authenticated\n  using (user_id = (select auth.uid()) or public.is_admin(organization_id))\n  with check (user_id = (select auth.uid()) or public.is_admin(organization_id))","-- audit_logs: readable by admins of the organization, and by a user for their\n-- own actions. No write policy exists, because nothing may write here except\n-- the security-definer triggers below.\ncreate policy audit_logs_select on public.audit_logs\n  for select to authenticated\n  using (\n    -- organization_id is checked for null first: is_admin(null) means \\"admin\n    -- of any organization\\", which on this nullable column would show an admin\n    -- of one organization the audit trail of another.\n    (organization_id is not null and public.is_admin(organization_id))\n    or actor_user_id = (select auth.uid())\n    -- Rows about a profile carry no organization of their own, so they are\n    -- matched through the people that admin actually administers.\n    or (entity_table = 'users' and public.is_admin_of_user(entity_id))\n  )","-- ---------------------------------------------------------------------------\n-- Audit logging\n--\n-- In triggers, not application code: a write that bypasses the app still gets\n-- recorded, and the log cannot be forgotten at a call site.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.write_audit_log()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_new jsonb;\n  v_old jsonb;\n  v_actor uuid;\n  v_organization_id uuid;\n  v_changes jsonb := '{}'::jsonb;\n  -- Bookkeeping columns are not interesting on their own; a row whose only\n  -- change is one of these produces no log entry.\n  v_ignored text[] := array['updated_at', 'last_login_at'];\nbegin\n  v_new := to_jsonb(new);\n  v_old := case when tg_op = 'UPDATE' then to_jsonb(old) else null end;\n\n  if tg_op = 'UPDATE' then\n    select coalesce(\n             jsonb_object_agg(\n               e.key,\n               jsonb_build_object('from', v_old -> e.key, 'to', e.value)\n             ),\n             '{}'::jsonb\n           )\n      into v_changes\n      from jsonb_each(v_new) as e\n     where e.value is distinct from v_old -> e.key\n       and not (e.key = any (v_ignored));\n\n    if v_changes = '{}'::jsonb then\n      return null;\n    end if;\n  end if;\n\n  -- Resolved through public.users rather than taken raw from auth.uid(), so a\n  -- caller without a profile row cannot fail the foreign key and roll back the\n  -- business transaction that triggered this.\n  select u.id into v_actor\n    from public.users u\n   where u.id = (select auth.uid());\n\n  if v_new ? 'organization_id' then\n    v_organization_id := (v_new ->> 'organization_id')::uuid;\n  end if;\n\n  insert into public.audit_logs (\n    organization_id, actor_user_id, action, entity_table, entity_id, metadata\n  )\n  values (\n    v_organization_id,\n    v_actor,\n    tg_table_name || '.' || lower(tg_op),\n    tg_table_name,\n    (v_new ->> 'id')::uuid,\n    v_changes\n  );\n\n  return null;\nend;\n$$","create trigger organizations_audit\n  after insert or update on public.organizations\n  for each row execute function public.write_audit_log()","create trigger branches_audit\n  after insert or update on public.branches\n  for each row execute function public.write_audit_log()","create trigger users_audit\n  after insert or update on public.users\n  for each row execute function public.write_audit_log()","create trigger user_roles_audit\n  after insert or update on public.user_roles\n  for each row execute function public.write_audit_log()","create trigger doctors_audit\n  after insert or update on public.doctors\n  for each row execute function public.write_audit_log()","create trigger staff_audit\n  after insert or update on public.staff\n  for each row execute function public.write_audit_log()","create trigger clients_audit\n  after insert or update on public.clients\n  for each row execute function public.write_audit_log()","-- Login events. auth.sessions gets a row per successful sign-in, so this\n-- captures logins without the application having to remember to report them.\ncreate or replace function public.write_login_audit()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_organization_id uuid;\nbegin\n  select ur.organization_id\n    into v_organization_id\n    from public.user_roles ur\n   where ur.user_id = new.user_id\n     and ur.revoked_at is null\n   order by ur.created_at\n   limit 1;\n\n  insert into public.audit_logs (\n    organization_id, actor_user_id, action, entity_table, entity_id, metadata\n  )\n  select\n    v_organization_id,\n    u.id,\n    'auth.login',\n    'auth.sessions',\n    new.id,\n    jsonb_build_object('session_id', new.id)\n  from public.users u\n  where u.id = new.user_id;\n\n  update public.users\n     set last_login_at = now()\n   where id = new.user_id;\n\n  return null;\nend;\n$$","create trigger sessions_audit_login\n  after insert on auth.sessions\n  for each row execute function public.write_login_audit()","-- ---------------------------------------------------------------------------\n-- audit_logs is append-only\n--\n-- Enforced for every role including service_role, which otherwise holds ALL.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.reject_audit_log_mutation()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  raise exception 'audit_logs is append-only; % is not permitted', tg_op\n    using errcode = '42501';\nend;\n$$","create trigger audit_logs_no_update\n  before update or delete on public.audit_logs\n  for each row execute function public.reject_audit_log_mutation()","create trigger audit_logs_no_truncate\n  before truncate on public.audit_logs\n  for each statement execute function public.reject_audit_log_mutation()"}	rls_and_audit
20260820000300	{"-- Phase 1 · Checkpoint 4 — account provisioning on signup.\n--\n-- Runs as a trigger on auth.users so an account cannot exist without its\n-- profile. Doing this in application code would leave orphaned auth users\n-- behind whenever a request failed between the two writes.\n\n-- Which organization does a self-registering pet owner join? With a single\n-- organization this is unambiguous. Isolated in a function so the multi-tenant\n-- rule changes in one place rather than inside the signup path.\ncreate or replace function public.default_organization_id()\nreturns uuid\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select o.id\n  from public.organizations o\n  where o.deleted_at is null\n    and o.is_active\n  order by o.created_at\n  limit 1;\n$$","revoke all on function public.default_organization_id() from public, anon","grant execute on function public.default_organization_id() to authenticated, service_role","create or replace function public.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_full_name text;\n  v_phone text;\n  v_organization_id uuid;\n  v_role_id uuid;\nbegin\n  v_full_name := coalesce(\n    nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''),\n    split_part(new.email, '@', 1)\n  );\n  v_phone := nullif(btrim(new.raw_user_meta_data ->> 'phone'), '');\n\n  -- Every account gets a profile, however it was created.\n  insert into public.users (id, full_name, email, phone)\n  values (new.id, v_full_name, new.email, v_phone);\n\n  -- Only the public registration form provisions a pet owner. Doctors, staff\n  -- and admins are invited through an administrative flow that grants the\n  -- right role deliberately, so this must not fire for them.\n  if coalesce(new.raw_user_meta_data ->> 'signup_source', '') <> 'self_registration' then\n    return new;\n  end if;\n\n  if v_phone is null then\n    raise exception 'A phone number is required to register'\n      using errcode = '23514';\n  end if;\n\n  v_organization_id := public.default_organization_id();\n\n  if v_organization_id is null then\n    raise exception 'No active organization is available to register into'\n      using errcode = '23503';\n  end if;\n\n  select r.id into v_role_id from public.roles r where r.slug = 'client';\n\n  insert into public.user_roles (user_id, role_id, organization_id)\n  values (new.id, v_role_id, v_organization_id);\n\n  insert into public.clients (user_id, organization_id, full_name, phone)\n  values (new.id, v_organization_id, v_full_name, v_phone);\n\n  return new;\nend;\n$$","create trigger users_handle_new_user\n  after insert on auth.users\n  for each row execute function public.handle_new_user()"}	signup
20260820000400	{"-- Phase 2 · Checkpoint 1 — species, breeds and pets.\n--\n-- Grants and RLS policies are stated here, as migration 0001 requires of every\n-- migration that adds a table.\n\n-- ---------------------------------------------------------------------------\n-- species and breeds — controlled vocabulary\n--\n-- Reference data, seeded below and read from the database. Free text would let\n-- \\"Golden Retriever\\" and \\"golden retriver\\" become different breeds, which\n-- quietly breaks every report that groups by breed.\n-- ---------------------------------------------------------------------------\n\ncreate table public.species (\n  id uuid primary key default gen_random_uuid(),\n  slug text not null unique,\n  name text not null,\n  sort_order integer not null default 100,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  constraint species_slug_format check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')\n)","create table public.breeds (\n  id uuid primary key default gen_random_uuid(),\n  species_id uuid not null references public.species (id) on delete restrict,\n  name text not null,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  constraint breeds_name_not_blank check (length(btrim(name)) > 0)\n)","create unique index breeds_species_id_name_key on public.breeds (species_id, name)","create index breeds_species_id_idx on public.breeds (species_id)","-- Lets pets carry a composite foreign key, so a breed can never be attached to\n-- the wrong species.\ncreate unique index breeds_id_species_id_key on public.breeds (id, species_id)","-- Same trick for tenancy: a pet's organization must be its owner's.\ncreate unique index clients_id_organization_id_key on public.clients (id, organization_id)","-- ---------------------------------------------------------------------------\n-- pets\n-- ---------------------------------------------------------------------------\n\ncreate table public.pets (\n  id uuid primary key default gen_random_uuid(),\n  client_id uuid not null,\n  organization_id uuid not null,\n\n  name text not null,\n  species_id uuid not null references public.species (id) on delete restrict,\n  breed_id uuid,\n\n  sex text not null default 'unknown',\n  is_neutered boolean,\n\n  -- Rescues and strays routinely arrive with no known date of birth. Forcing a\n  -- value here makes staff invent one, which corrupts every derived age.\n  date_of_birth date,\n  is_date_of_birth_estimated boolean not null default false,\n\n  -- Grams, not kilograms, and an integer rather than a float. Phase 5 computes\n  -- weight × dose-per-kg; binary floating point cannot represent 0.1 exactly,\n  -- and a rounding error in a medication dose is not an acceptable risk.\n  weight_grams integer,\n  weight_recorded_at timestamptz,\n\n  colour text,\n  microchip_number text,\n  allergies text,\n  chronic_conditions text,\n  notes text,\n\n  -- Storage object path, not a URL. The bucket is private; links are signed at\n  -- read time. Populated in the next checkpoint.\n  photo_path text,\n\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint pets_name_not_blank check (length(btrim(name)) > 0),\n  constraint pets_sex_allowed check (sex in ('male', 'female', 'unknown')),\n  constraint pets_date_of_birth_not_future check (date_of_birth is null or date_of_birth <= current_date),\n  -- Upper bound covers large livestock; the point is to reject a decimal\n  -- entered where grams were expected.\n  constraint pets_weight_sane check (weight_grams is null or (weight_grams > 0 and weight_grams <= 2000000)),\n  -- A weight with no date cannot be judged current, and a date with no weight\n  -- means nothing.\n  constraint pets_weight_dated check ((weight_grams is null) = (weight_recorded_at is null)),\n\n  -- A pet belongs to the organization its owner belongs to. Enforced by the\n  -- database rather than trusted from the application.\n  constraint pets_client_fk\n    foreign key (client_id, organization_id)\n    references public.clients (id, organization_id)\n    on delete restrict,\n\n  -- A breed must belong to the species recorded. Not checked when breed_id is\n  -- null, which is the mixed or unknown case.\n  constraint pets_breed_fk\n    foreign key (breed_id, species_id)\n    references public.breeds (id, species_id)\n    on delete restrict\n)","create index pets_client_id_idx on public.pets (client_id)","create index pets_organization_id_idx on public.pets (organization_id)","create index pets_species_id_idx on public.pets (species_id)","create index pets_breed_id_idx on public.pets (breed_id)","create unique index pets_organization_id_microchip_key\n  on public.pets (organization_id, microchip_number)\n  where microchip_number is not null and deleted_at is null","comment on table public.pets is\n  'Patients. Age is derived from date_of_birth at read time and never stored.'","comment on column public.pets.weight_grams is\n  'Integer grams. Convert at the UI edge; never store kilograms as a float.'","create trigger pets_set_updated_at\n  before update on public.pets\n  for each row execute function public.set_updated_at()","create trigger pets_audit\n  after insert or update on public.pets\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- Row level security\n-- ---------------------------------------------------------------------------\n\nalter table public.species enable row level security","alter table public.breeds enable row level security","alter table public.pets enable row level security","-- Does the caller own this client record?\ncreate or replace function public.owns_client(p_client_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select exists (\n    select 1\n    from public.clients c\n    where c.id = p_client_id\n      and c.user_id = (select auth.uid())\n      and c.deleted_at is null\n  );\n$$","revoke all on function public.owns_client(uuid) from public, anon","grant execute on function public.owns_client(uuid) to authenticated, service_role","-- Reference data is readable by any signed-in user; it is not patient data.\ncreate policy species_select on public.species\n  for select to authenticated\n  using (true)","create policy breeds_select on public.breeds\n  for select to authenticated\n  using (true)","-- A client reaches their own pets and no others. Clinic staff are scoped to\n-- their organization, matching the clients policy in migration 0002.\ncreate policy pets_select on public.pets\n  for select to authenticated\n  using (\n    public.owns_client(client_id)\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy pets_insert on public.pets\n  for insert to authenticated\n  with check (\n    public.owns_client(client_id)\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy pets_update on public.pets\n  for update to authenticated\n  using (\n    public.owns_client(client_id)\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )\n  with check (\n    public.owns_client(client_id)\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","-- ---------------------------------------------------------------------------\n-- Privileges\n-- ---------------------------------------------------------------------------\n\nrevoke all on public.species, public.breeds, public.pets from anon","grant select on public.species to authenticated","grant select on public.breeds to authenticated","grant select, insert on public.pets to authenticated","-- client_id and organization_id are deliberately absent: no one may re-home a\n-- pet or move it between organizations through the table. That needs a\n-- deliberate administrative action, which a later phase provides.\ngrant update (\n  name,\n  species_id,\n  breed_id,\n  sex,\n  is_neutered,\n  date_of_birth,\n  is_date_of_birth_estimated,\n  weight_grams,\n  weight_recorded_at,\n  colour,\n  microchip_number,\n  allergies,\n  chronic_conditions,\n  notes,\n  photo_path,\n  deleted_at\n) on public.pets to authenticated","grant all on public.species, public.breeds, public.pets to service_role","-- ---------------------------------------------------------------------------\n-- Reference data\n--\n-- A starting vocabulary for a Bangladeshi practice. Administrators extend it\n-- later; nothing in the application hard-codes these values.\n-- ---------------------------------------------------------------------------\n\ninsert into public.species (slug, name, sort_order) values\n  ('dog', 'Dog', 10),\n  ('cat', 'Cat', 20),\n  ('rabbit', 'Rabbit', 30),\n  ('bird', 'Bird', 40),\n  ('cattle', 'Cattle', 50),\n  ('goat', 'Goat', 60),\n  ('sheep', 'Sheep', 70)\non conflict (slug) do nothing","insert into public.breeds (species_id, name)\nselect s.id, breed.name\nfrom public.species s\njoin (values\n  ('dog', 'Desi / Local'),\n  ('dog', 'Mixed breed'),\n  ('dog', 'Indian Spitz'),\n  ('dog', 'Labrador Retriever'),\n  ('dog', 'Golden Retriever'),\n  ('dog', 'German Shepherd'),\n  ('dog', 'Beagle'),\n  ('dog', 'Pug'),\n  ('dog', 'Dachshund'),\n  ('dog', 'Rottweiler'),\n  ('dog', 'Siberian Husky'),\n  ('dog', 'Shih Tzu'),\n  ('cat', 'Desi / Local'),\n  ('cat', 'Mixed breed'),\n  ('cat', 'Domestic Shorthair'),\n  ('cat', 'Persian'),\n  ('cat', 'Siamese'),\n  ('cat', 'Turkish Angora'),\n  ('cat', 'Ragdoll'),\n  ('rabbit', 'Local'),\n  ('rabbit', 'Dutch'),\n  ('rabbit', 'Lionhead'),\n  ('rabbit', 'Angora'),\n  ('bird', 'Budgerigar'),\n  ('bird', 'Cockatiel'),\n  ('bird', 'African Grey'),\n  ('bird', 'Java Sparrow'),\n  ('bird', 'Pigeon'),\n  ('cattle', 'Desi / Local'),\n  ('cattle', 'Sahiwal'),\n  ('cattle', 'Red Chittagong'),\n  ('cattle', 'Holstein Friesian cross'),\n  ('cattle', 'Jersey cross'),\n  ('goat', 'Black Bengal'),\n  ('goat', 'Jamunapari'),\n  ('goat', 'Crossbred'),\n  ('sheep', 'Local')\n) as breed(species_slug, name) on breed.species_slug = s.slug\non conflict (species_id, name) do nothing"}	pets
20260820000500	{"-- Phase 2 · Checkpoint 2 — documents and file storage.\n--\n-- Two private buckets. Nothing is ever served publicly: reads go through\n-- short-lived signed URLs minted server-side after the row policies have\n-- already decided the caller may see the record.\n\n-- Lets documents carry a composite foreign key onto its patient's tenant.\ncreate unique index pets_id_organization_id_key on public.pets (id, organization_id)","-- ---------------------------------------------------------------------------\n-- Pet access helper\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.can_access_pet(p_pet_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select exists (\n    select 1\n    from public.pets p\n    where p.id = p_pet_id\n      and p.deleted_at is null\n      and (\n        public.owns_client(p.client_id)\n        or public.is_admin(p.organization_id)\n        or public.is_doctor(p.organization_id)\n      )\n  );\n$$","comment on function public.can_access_pet(uuid) is\n  'True when the caller may reach this patient at all. Says nothing about\n   whether a particular document attached to it is shared with them.'","create or replace function public.owns_pet(p_pet_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select exists (\n    select 1\n    from public.pets p\n    where p.id = p_pet_id\n      and p.deleted_at is null\n      and public.owns_client(p.client_id)\n  );\n$$","revoke all on function public.can_access_pet(uuid), public.owns_pet(uuid) from public, anon","grant execute on function public.can_access_pet(uuid), public.owns_pet(uuid)\n  to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- documents\n-- ---------------------------------------------------------------------------\n\ncreate table public.documents (\n  id uuid primary key default gen_random_uuid(),\n  pet_id uuid not null,\n  organization_id uuid not null,\n\n  -- The name the person recognises, kept separate from where the bytes live.\n  file_name text not null,\n  storage_path text not null unique,\n  mime_type text not null,\n  size_bytes bigint not null,\n  description text,\n\n  -- Clients see only what has been explicitly shared with them. A client's own\n  -- upload is shared by default, enforced in the insert policy below.\n  is_client_visible boolean not null default false,\n\n  uploaded_by uuid not null references public.users (id) on delete restrict,\n\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint documents_file_name_not_blank check (length(btrim(file_name)) > 0),\n  constraint documents_size_sane check (size_bytes > 0 and size_bytes <= 20971520),\n\n  constraint documents_pet_fk\n    foreign key (pet_id, organization_id)\n    references public.pets (id, organization_id)\n    on delete restrict\n)","create index documents_pet_id_idx on public.documents (pet_id)","create index documents_organization_id_idx on public.documents (organization_id)","create index documents_uploaded_by_idx on public.documents (uploaded_by)","comment on table public.documents is\n  'Files attached to a patient. Phase 4 extends this for clinical uploads.'","create trigger documents_set_updated_at\n  before update on public.documents\n  for each row execute function public.set_updated_at()","create trigger documents_audit\n  after insert or update on public.documents\n  for each row execute function public.write_audit_log()","alter table public.documents enable row level security","-- A client sees a document only when it is marked visible to them. Clinic\n-- staff see everything for patients in their organization.\ncreate policy documents_select on public.documents\n  for select to authenticated\n  using (\n    (is_client_visible and public.owns_pet(pet_id))\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","-- The client branch requires is_client_visible, so a client physically cannot\n-- upload a file they would then be unable to see.\ncreate policy documents_insert on public.documents\n  for insert to authenticated\n  with check (\n    uploaded_by = (select auth.uid())\n    and (\n      (public.owns_pet(pet_id) and is_client_visible)\n      or public.is_admin(organization_id)\n      or public.is_doctor(organization_id)\n    )\n  )","-- A client may amend or withdraw only what they uploaded themselves; they can\n-- never reach a clinical document, let alone reveal one.\ncreate policy documents_update on public.documents\n  for update to authenticated\n  using (\n    (public.owns_pet(pet_id) and uploaded_by = (select auth.uid()))\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )\n  with check (\n    (public.owns_pet(pet_id) and uploaded_by = (select auth.uid()))\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","revoke all on public.documents from anon","grant select, insert on public.documents to authenticated","-- Neither pet_id nor organization_id can be rewritten, so a document cannot be\n-- moved onto another patient after the fact.\ngrant update (file_name, description, is_client_visible, deleted_at)\n  on public.documents to authenticated","grant all on public.documents to service_role","-- ---------------------------------------------------------------------------\n-- Buckets\n--\n-- Separate buckets rather than one: a pet photo is benign and always visible\n-- to the owner, while a document may be an X-ray the vet has not yet reviewed.\n-- Keeping them apart means one policy mistake cannot expose the other.\n-- ---------------------------------------------------------------------------\n\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues\n  ('pet-photos', 'pet-photos', false, 5242880,\n   array['image/jpeg', 'image/png', 'image/webp']),\n  ('pet-documents', 'pet-documents', false, 20971520,\n   array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])\non conflict (id) do nothing","-- ---------------------------------------------------------------------------\n-- Object policies\n--\n-- Both buckets store objects under a first folder equal to the patient's id,\n-- so access can be decided from the path.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.pet_id_from_object_path(p_name text)\nreturns uuid\nlanguage plpgsql\nimmutable\nas $$\nbegin\n  return (string_to_array(p_name, '/'))[1]::uuid;\nexception\n  -- A path that does not begin with a patient id is not addressable by anyone.\n  when others then return null;\nend;\n$$","revoke all on function public.pet_id_from_object_path(text) from public, anon","grant execute on function public.pet_id_from_object_path(text) to authenticated, service_role","create policy pet_photos_select on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = 'pet-photos'\n    and public.can_access_pet(public.pet_id_from_object_path(name))\n  )","create policy pet_photos_insert on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'pet-photos'\n    and public.can_access_pet(public.pet_id_from_object_path(name))\n  )","create policy pet_photos_update on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = 'pet-photos'\n    and public.can_access_pet(public.pet_id_from_object_path(name))\n  )\n  with check (\n    bucket_id = 'pet-photos'\n    and public.can_access_pet(public.pet_id_from_object_path(name))\n  )","-- Clinic staff reach any document for their patients. A client reaches an\n-- object only when the row describing it is marked visible to them, so the\n-- file and its record can never disagree about who may read it.\ncreate policy pet_documents_select on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = 'pet-documents'\n    and (\n      exists (\n        -- storage.objects.name must be qualified here: public.pets has a name\n        -- column of its own, and an unqualified reference silently resolves to\n        -- the pet's name instead of the object path.\n        select 1\n        from public.pets p\n        where p.id = public.pet_id_from_object_path(storage.objects.name)\n          and (public.is_admin(p.organization_id) or public.is_doctor(p.organization_id))\n      )\n      or exists (\n        select 1\n        from public.documents d\n        where d.storage_path = storage.objects.name\n          and d.deleted_at is null\n          and d.is_client_visible\n          and public.owns_pet(d.pet_id)\n      )\n    )\n  )","create policy pet_documents_insert on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'pet-documents'\n    and public.can_access_pet(public.pet_id_from_object_path(name))\n  )"}	documents
20260820000600	{"-- Phase 2 · Checkpoint 6 — doctors may record and correct client details.\n--\n-- Phase 1 restricted client writes to administrators, because at that point\n-- nothing described what a doctor would do with them. Phase 2 §2.2 is explicit:\n-- \\"Admin and doctor can create, view, edit and search clients.\\" A vet seeing a\n-- patient must be able to correct a wrong phone number without finding an\n-- administrator first.\n--\n-- Reading was already permitted, so this widens writing only.\n\ndrop policy clients_insert on public.clients","create policy clients_insert on public.clients\n  for insert to authenticated\n  with check (\n    public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","drop policy clients_update on public.clients","create policy clients_update on public.clients\n  for update to authenticated\n  using (\n    user_id = (select auth.uid())\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )\n  with check (\n    user_id = (select auth.uid())\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )"}	doctor_client_access
20260820000700	{"-- Phase 3 · Checkpoint 1 — scheduling.\n--\n-- The central guarantee of this phase is that two clients cannot book the same\n-- doctor at the same time. That is enforced by an exclusion constraint rather\n-- than by application code: a check-then-insert reads before it writes, and two\n-- requests can both pass the read before either writes. On a Saturday morning\n-- that is not an edge case.\n\ncreate extension if not exists \\"btree_gist\\" with schema extensions","-- Postgres ships range types for timestamptz, date and numeric kinds, but not\n-- for plain time — the doctor_availability exclusion constraint below needs\n-- one to detect two windows overlapping on the same weekday.\ncreate type public.timerange as range (subtype = time)","-- ---------------------------------------------------------------------------\n-- Clinic policy\n-- ---------------------------------------------------------------------------\n\nalter table public.organizations\n  add column cancellation_notice_hours integer not null default 12","comment on column public.organizations.cancellation_notice_hours is\n  'How long before an appointment a client may still change it themselves. A\n   business decision, so it is configuration rather than a constant in code.'","alter table public.organizations\n  add constraint organizations_cancellation_notice_sane\n  check (cancellation_notice_hours between 0 and 168)","-- Composite keys, so an appointment cannot assemble parts from different\n-- practices or attach a pet to someone who does not own it.\ncreate unique index doctors_id_organization_id_key on public.doctors (id, organization_id)","create unique index pets_id_client_id_key on public.pets (id, client_id)","-- ---------------------------------------------------------------------------\n-- appointment_statuses — §3.4\n--\n-- Seeded reference data. Colour lives here so the calendar's colour-coding is\n-- configuration rather than a list of statuses hard-coded in a component.\n-- ---------------------------------------------------------------------------\n\ncreate table public.appointment_statuses (\n  slug text primary key,\n  name text not null,\n  description text,\n  sort_order integer not null,\n  /* Semantic colour key; the design system maps it to tokens. */\n  colour text not null,\n  /* Whether an appointment in this state still occupies the doctor's time. */\n  occupies_slot boolean not null default true,\n  /* Whether the appointment is finished, one way or another. */\n  is_final boolean not null default false,\n  constraint appointment_statuses_slug_allowed check (\n    slug in (\n      'requested', 'confirmed', 'checked_in', 'in_consultation',\n      'completed', 'cancelled', 'no_show'\n    )\n  )\n)","insert into public.appointment_statuses\n  (slug, name, description, sort_order, colour, occupies_slot, is_final)\nvalues\n  ('requested', 'Requested', 'Booked by the client, not yet confirmed by the clinic.', 10, 'amber', true, false),\n  ('confirmed', 'Confirmed', 'Confirmed by the clinic.', 20, 'sage', true, false),\n  ('checked_in', 'Checked in', 'The patient has arrived.', 30, 'teal', true, false),\n  ('in_consultation', 'In consultation', 'With the vet now.', 40, 'blue', true, false),\n  ('completed', 'Completed', 'The visit is finished.', 50, 'slate', true, true),\n  ('cancelled', 'Cancelled', 'Cancelled by the client or the clinic.', 60, 'grey', false, true),\n  ('no_show', 'No show', 'The patient did not arrive.', 70, 'rose', false, true)","-- ---------------------------------------------------------------------------\n-- services — minimal; Phase 7 adds pricing and management\n-- ---------------------------------------------------------------------------\n\ncreate table public.services (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  name text not null,\n  description text,\n  /* How long the appointment actually occupies, distinct from how often slots\n     are offered: a vaccination is not a surgery. */\n  duration_minutes integer not null default 30,\n  sort_order integer not null default 100,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n  constraint services_name_not_blank check (length(btrim(name)) > 0),\n  constraint services_duration_sane check (duration_minutes between 5 and 480)\n)","create unique index services_organization_id_name_key\n  on public.services (organization_id, name)\n  where deleted_at is null","create index services_organization_id_idx on public.services (organization_id)","create unique index services_id_organization_id_key on public.services (id, organization_id)","-- ---------------------------------------------------------------------------\n-- doctor_availability — §3.5\n--\n-- Breaks are the gaps between windows: a doctor working 09:00–13:00 and\n-- 14:00–17:00 has a one o'clock break by construction. That needs no second\n-- table and cannot disagree with the working hours it sits inside.\n-- ---------------------------------------------------------------------------\n\ncreate table public.doctor_availability (\n  id uuid primary key default gen_random_uuid(),\n  doctor_id uuid not null,\n  organization_id uuid not null,\n  /* Null means the doctor is available at any branch in this window. */\n  branch_id uuid references public.branches (id) on delete restrict,\n\n  /* 0 = Sunday, matching Postgres date_part('dow'), and the Bangladeshi week. */\n  weekday smallint not null,\n  starts_at time not null,\n  ends_at time not null,\n\n  /* How often a start time is offered inside the window. */\n  slot_minutes integer not null default 30,\n\n  /* Null means this window serves every visit type; set it to run a\n     home-visit-only or surgery-only session. */\n  visit_type text,\n\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint doctor_availability_weekday_range check (weekday between 0 and 6),\n  constraint doctor_availability_window_ordered check (ends_at > starts_at),\n  constraint doctor_availability_slot_sane check (slot_minutes between 5 and 240),\n  constraint doctor_availability_visit_type_allowed check (\n    visit_type is null or visit_type in (\n      'clinic', 'home', 'follow_up', 'emergency', 'surgery', 'vaccination', 'other'\n    )\n  ),\n\n  constraint doctor_availability_doctor_fk\n    foreign key (doctor_id, organization_id)\n    references public.doctors (id, organization_id)\n    on delete restrict\n)","create index doctor_availability_doctor_id_idx on public.doctor_availability (doctor_id)","create index doctor_availability_organization_id_idx on public.doctor_availability (organization_id)","-- One doctor cannot hold two overlapping windows for the same weekday and\n-- visit type, which would offer the same start time twice.\nalter table public.doctor_availability\n  add constraint doctor_availability_no_overlap\n  exclude using gist (\n    doctor_id with =,\n    weekday with =,\n    coalesce(visit_type, '*') with =,\n    public.timerange(starts_at, ends_at, '[)') with &&\n  )\n  where (deleted_at is null and is_active)","-- ---------------------------------------------------------------------------\n-- appointments\n-- ---------------------------------------------------------------------------\n\ncreate table public.appointments (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  /* Null for a home visit, which happens at the client's address. */\n  branch_id uuid references public.branches (id) on delete restrict,\n\n  client_id uuid not null,\n  pet_id uuid not null,\n  doctor_id uuid not null,\n  service_id uuid not null,\n\n  visit_type text not null,\n  status text not null default 'requested'\n    references public.appointment_statuses (slug) on delete restrict,\n\n  starts_at timestamptz not null,\n  ends_at timestamptz not null,\n\n  reason text,\n  /* Where the visit happens; carries the address for a home visit. */\n  location text,\n  notes text,\n\n  created_by uuid references public.users (id) on delete restrict,\n  cancelled_at timestamptz,\n  cancelled_by uuid references public.users (id) on delete restrict,\n  cancellation_reason text,\n\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint appointments_ordered check (ends_at > starts_at),\n  constraint appointments_visit_type_allowed check (\n    visit_type in ('clinic', 'home', 'follow_up', 'emergency', 'surgery', 'vaccination', 'other')\n  ),\n  /* A home visit has no branch; anything else happens at one. */\n  constraint appointments_branch_matches_visit_type check (\n    (visit_type = 'home' and branch_id is null) or (visit_type <> 'home')\n  ),\n\n  constraint appointments_client_fk\n    foreign key (client_id, organization_id)\n    references public.clients (id, organization_id)\n    on delete restrict,\n  /* The animal must belong to the client being seen. */\n  constraint appointments_pet_fk\n    foreign key (pet_id, client_id)\n    references public.pets (id, client_id)\n    on delete restrict,\n  constraint appointments_doctor_fk\n    foreign key (doctor_id, organization_id)\n    references public.doctors (id, organization_id)\n    on delete restrict,\n  constraint appointments_service_fk\n    foreign key (service_id, organization_id)\n    references public.services (id, organization_id)\n    on delete restrict\n)","create index appointments_organization_id_starts_at_idx\n  on public.appointments (organization_id, starts_at)","create index appointments_doctor_id_starts_at_idx on public.appointments (doctor_id, starts_at)","create index appointments_client_id_idx on public.appointments (client_id)","create index appointments_pet_id_idx on public.appointments (pet_id)","create index appointments_status_idx on public.appointments (status)","-- The guarantee. Two overlapping appointments cannot both exist for one doctor\n-- unless one of them is cancelled or a no-show, which free the time again.\n-- The statuses are named literally rather than joined to occupies_slot: an\n-- exclusion predicate must be immutable, and changing which states hold a slot\n-- deserves a migration.\nalter table public.appointments\n  add constraint appointments_no_double_booking\n  exclude using gist (\n    doctor_id with =,\n    tstzrange(starts_at, ends_at, '[)') with &&\n  )\n  where (deleted_at is null and status not in ('cancelled', 'no_show'))","comment on constraint appointments_no_double_booking on public.appointments is\n  'Two clients cannot hold the same doctor at the same time. Enforced here\n   because an application check reads before it writes and races under load.'","-- ---------------------------------------------------------------------------\n-- Triggers\n-- ---------------------------------------------------------------------------\n\ncreate trigger services_set_updated_at\n  before update on public.services\n  for each row execute function public.set_updated_at()","create trigger doctor_availability_set_updated_at\n  before update on public.doctor_availability\n  for each row execute function public.set_updated_at()","create trigger appointments_set_updated_at\n  before update on public.appointments\n  for each row execute function public.set_updated_at()","create trigger services_audit\n  after insert or update on public.services\n  for each row execute function public.write_audit_log()","create trigger doctor_availability_audit\n  after insert or update on public.doctor_availability\n  for each row execute function public.write_audit_log()","create trigger appointments_audit\n  after insert or update on public.appointments\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- Helpers\n-- ---------------------------------------------------------------------------\n\n/* May the caller still change this appointment themselves? Clinic staff always\n   may; a client may until the practice's notice period. */\ncreate or replace function public.may_client_change_appointment(\n  p_starts_at timestamptz,\n  p_organization_id uuid\n)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select p_starts_at > now() + make_interval(\n    hours => coalesce(\n      (select o.cancellation_notice_hours\n         from public.organizations o\n        where o.id = p_organization_id),\n      12\n    )\n  );\n$$","revoke all on function public.may_client_change_appointment(timestamptz, uuid) from public, anon","grant execute on function public.may_client_change_appointment(timestamptz, uuid)\n  to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- Row level security\n-- ---------------------------------------------------------------------------\n\nalter table public.appointment_statuses enable row level security","alter table public.services enable row level security","alter table public.doctor_availability enable row level security","alter table public.appointments enable row level security","create policy appointment_statuses_select on public.appointment_statuses\n  for select to authenticated\n  using (true)","create policy services_select on public.services\n  for select to authenticated\n  using (public.is_org_member(organization_id))","create policy services_insert on public.services\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy services_update on public.services\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","-- Clients read availability so the booking form can offer times; only the\n-- practice decides what it is.\ncreate policy doctor_availability_select on public.doctor_availability\n  for select to authenticated\n  using (public.is_org_member(organization_id))","create policy doctor_availability_insert on public.doctor_availability\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy doctor_availability_update on public.doctor_availability\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","create policy appointments_select on public.appointments\n  for select to authenticated\n  using (\n    public.owns_client(client_id)\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy appointments_insert on public.appointments\n  for insert to authenticated\n  with check (\n    (public.owns_client(client_id) and public.owns_pet(pet_id))\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","-- A client may change their own booking until the practice's notice period;\n-- after that they are asked to telephone, and the clinic can still act.\ncreate policy appointments_update on public.appointments\n  for update to authenticated\n  using (\n    (\n      public.owns_client(client_id)\n      and public.may_client_change_appointment(starts_at, organization_id)\n    )\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )\n  with check (\n    public.owns_client(client_id)\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","-- ---------------------------------------------------------------------------\n-- Privileges\n-- ---------------------------------------------------------------------------\n\nrevoke all on\n  public.appointment_statuses,\n  public.services,\n  public.doctor_availability,\n  public.appointments\nfrom anon","grant select on public.appointment_statuses to authenticated","grant select on public.services to authenticated","grant select on public.doctor_availability to authenticated","grant select, insert on public.appointments to authenticated","grant insert, update (\n  name, description, duration_minutes, sort_order, is_active, deleted_at\n) on public.services to authenticated","grant insert, update (\n  branch_id, weekday, starts_at, ends_at, slot_minutes, visit_type, is_active, deleted_at\n) on public.doctor_availability to authenticated","-- Neither the organisation, the client, the pet nor who booked it can be\n-- rewritten: an appointment cannot be moved to another practice or another\n-- animal after the fact.\ngrant update (\n  branch_id, doctor_id, service_id, visit_type, status,\n  starts_at, ends_at, reason, location, notes,\n  cancelled_at, cancelled_by, cancellation_reason, deleted_at\n) on public.appointments to authenticated","grant all on\n  public.appointment_statuses,\n  public.services,\n  public.doctor_availability,\n  public.appointments\nto service_role","-- ---------------------------------------------------------------------------\n-- A starting service list for the seeded practice\n--\n-- Operational reference data, not prices and not clinical content. Phase 7\n-- gives administrators a screen to manage it; until then booking needs\n-- something to offer.\n-- ---------------------------------------------------------------------------\n\ninsert into public.services (organization_id, name, description, duration_minutes, sort_order)\nselect o.id, service.name, service.description, service.duration, service.sort_order\nfrom public.organizations o\njoin (values\n  ('General consultation', 'Routine examination and advice.', 30, 10),\n  ('Follow-up consultation', 'Review of an ongoing problem.', 20, 20),\n  ('Vaccination', 'Scheduled or catch-up vaccination.', 15, 30),\n  ('Deworming', 'Routine parasite treatment.', 15, 40),\n  ('Emergency consultation', 'Urgent, same-day assessment.', 45, 50),\n  ('Surgery', 'Planned surgical procedure.', 90, 60),\n  ('Home visit consultation', 'Examination at the client''s address.', 60, 70)\n) as service(name, description, duration, sort_order) on true\nwhere o.slug = 'the-traveling-vet'\non conflict do nothing"}	appointments
20260823000100	{"-- Phase 3 · Checkpoint 2 — closes a gap in appointments_update.\n--\n-- appointments_update lets a client UPDATE any granted column so long as they\n-- own the appointment and are inside the practice's notice window. That grant\n-- exists so a client can reschedule (starts_at/ends_at) and cancel\n-- (status/cancelled_*); as written it would equally let a client set\n-- status = 'completed' or move themselves to a different doctor directly.\n-- Row level security decides which *rows* a client may touch; this trigger is\n-- the same layer deciding which *changes* to those rows a client, specifically,\n-- may make. Staff are unaffected.\n\ncreate or replace function public.guard_client_appointment_update()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  -- Unlike row level security, a trigger is not automatically bypassed for\n  -- the service role — it fires for every actor alike. Row level security\n  -- already trusts the service role completely (it is how migrations, seed\n  -- scripts and background jobs operate), so this trigger extends it the same\n  -- trust rather than mistaking it for an unauthenticated client.\n  if (select auth.uid()) is null then\n    return new;\n  end if;\n\n  -- Staff may make any change the column grants already allow.\n  if public.is_admin(new.organization_id) or public.is_doctor(new.organization_id) then\n    return new;\n  end if;\n\n  -- Neither staff nor the owning client: row level security should already\n  -- have stopped this row from being reached, but this trigger does not lean\n  -- on that alone.\n  if not public.owns_client(old.client_id) then\n    raise exception 'You do not have access to this appointment.';\n  end if;\n\n  if old.status in ('completed', 'cancelled', 'no_show') then\n    raise exception 'This appointment can no longer be changed. Please contact the clinic.';\n  end if;\n\n  if new.doctor_id is distinct from old.doctor_id\n    or new.service_id is distinct from old.service_id\n    or new.branch_id is distinct from old.branch_id\n    or new.visit_type is distinct from old.visit_type\n  then\n    raise exception 'Please contact the clinic to change the doctor, service or visit type.';\n  end if;\n\n  if new.status is distinct from old.status and new.status <> 'cancelled' then\n    raise exception 'Please contact the clinic to change this appointment''s status.';\n  end if;\n\n  return new;\nend;\n$$","comment on function public.guard_client_appointment_update() is\n  'A client may reschedule (starts_at/ends_at) and cancel their own upcoming\n   appointment; only staff may change the doctor, service, visit type, or move\n   status anywhere other than cancelled.'","-- Alphabetically before appointments_set_updated_at, so this runs first among\n-- the BEFORE UPDATE triggers on this table — it only inspects NEW, never\n-- depends on updated_at having been touched yet.\ncreate trigger appointments_guard_client_update\n  before update on public.appointments\n  for each row execute function public.guard_client_appointment_update()"}	appointment_client_guard
20260824000100	{"-- Phase 4 · Checkpoint 1 — SOAP records, diagnoses, diagnostic tests.\n--\n-- The one genuinely new idea here is versioning. Nothing else in this schema\n-- keeps a prior version of an edited row: the audit trigger records diffs,\n-- not snapshots, and every other table is edit-in-place plus soft-delete.\n-- A clinical record is different — the brief is explicit that a finalized\n-- SOAP note must never be silently overwritten. So a SOAP record's version\n-- chain is a set of rows sharing one appointment_id (one appointment has\n-- exactly one SOAP note, versioned); at most one of them has\n-- superseded_at is null, which is \\"the current version\\". Editing a draft is\n-- a plain update. Editing a finalized record calls revise_soap_record(),\n-- which inserts a fresh draft row copied from the old one and marks the old\n-- row superseded — both statements run under the caller's own row level\n-- security, same as everything else here.\n\n-- ---------------------------------------------------------------------------\n-- Composite-FK support\n-- ---------------------------------------------------------------------------\n\ncreate unique index appointments_id_organization_id_key\n  on public.appointments (id, organization_id)","-- ---------------------------------------------------------------------------\n-- soap_records\n-- ---------------------------------------------------------------------------\n\ncreate table public.soap_records (\n  id uuid primary key default gen_random_uuid(),\n  appointment_id uuid not null,\n  pet_id uuid not null,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  doctor_id uuid not null,\n\n  version integer not null default 1,\n  status text not null default 'draft',\n  finalized_at timestamptz,\n  -- Null means this is the current version of this appointment's SOAP note.\n  superseded_at timestamptz,\n\n  -- SUBJECTIVE — §4.2\n  chief_complaint text,\n  history text,\n  duration text,\n  appetite text,\n  water_intake text,\n  urination text,\n  defecation text,\n  vomiting text,\n  diarrhea text,\n  coughing text,\n  sneezing text,\n  other_observations text,\n\n  -- OBJECTIVE — vitals, §4.3\n  temperature_celsius numeric(4, 1),\n  pulse_bpm integer,\n  respiratory_rate_bpm integer,\n  -- Grams, matching pets.weight_grams — see that table's own comment on why.\n  weight_grams integer,\n  body_condition_score integer,\n  mucous_membrane text,\n  capillary_refill_time text,\n  hydration_status text,\n\n  -- OBJECTIVE — physical examination, §4.3\n  general_appearance text,\n  exam_eyes text,\n  exam_ears text,\n  exam_nose text,\n  exam_oral_cavity text,\n  exam_cardiovascular text,\n  exam_respiratory text,\n  exam_gastrointestinal text,\n  exam_urinary text,\n  exam_reproductive text,\n  exam_musculoskeletal text,\n  exam_neurological text,\n  exam_skin text,\n  exam_lymph_nodes text,\n  exam_notes text,\n\n  -- ASSESSMENT — §4.4. Differential/final diagnoses are the separate\n  -- `diagnoses` table below, not free text here.\n  clinical_assessment text,\n  problem_list text,\n\n  -- PLAN — §4.5. Medication is free text this phase; Phase 5 wires it to\n  -- the prescription builder.\n  treatment text,\n  medication text,\n  diagnostics_plan text,\n  diet text,\n  hospitalization text,\n  follow_up_needed boolean not null default false,\n  follow_up_notes text,\n  -- Set once a follow-up appointment is actually booked from this record —\n  -- what the doctor dashboard's \\"Follow-ups due\\" card is really counting.\n  follow_up_scheduled_at timestamptz,\n  client_instructions text,\n\n  created_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n\n  constraint soap_records_status_allowed check (status in ('draft', 'finalized')),\n  constraint soap_records_version_positive check (version > 0),\n  constraint soap_records_temperature_sane\n    check (temperature_celsius is null or (temperature_celsius > 20 and temperature_celsius < 45)),\n  constraint soap_records_pulse_sane check (pulse_bpm is null or (pulse_bpm > 0 and pulse_bpm < 400)),\n  constraint soap_records_respiratory_rate_sane\n    check (respiratory_rate_bpm is null or (respiratory_rate_bpm > 0 and respiratory_rate_bpm < 150)),\n  constraint soap_records_weight_sane\n    check (weight_grams is null or (weight_grams > 0 and weight_grams <= 2000000)),\n  constraint soap_records_bcs_sane\n    check (body_condition_score is null or (body_condition_score between 1 and 9)),\n\n  constraint soap_records_appointment_fk\n    foreign key (appointment_id, organization_id)\n    references public.appointments (id, organization_id)\n    on delete restrict,\n  constraint soap_records_pet_fk\n    foreign key (pet_id, organization_id)\n    references public.pets (id, organization_id)\n    on delete restrict,\n  constraint soap_records_doctor_fk\n    foreign key (doctor_id, organization_id)\n    references public.doctors (id, organization_id)\n    on delete restrict\n)","-- Exactly one current version per appointment.\ncreate unique index soap_records_appointment_current_key\n  on public.soap_records (appointment_id)\n  where superseded_at is null","create index soap_records_pet_id_idx on public.soap_records (pet_id)","create index soap_records_doctor_id_idx on public.soap_records (doctor_id)","create index soap_records_organization_id_idx on public.soap_records (organization_id)","comment on table public.soap_records is\n  'One row per version of a visit''s SOAP note. All versions for one visit\n   share appointment_id; superseded_at is null only on the current version.\n   A finalized row''s clinical columns are immutable — see\n   guard_finalized_soap_update() — the only way to change one is\n   revise_soap_record(), which creates the next version.'","create trigger soap_records_set_updated_at\n  before update on public.soap_records\n  for each row execute function public.set_updated_at()","create trigger soap_records_audit\n  after insert or update on public.soap_records\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- Finalized records are immutable except for being superseded\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.guard_finalized_soap_update()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if old.status = 'finalized' then\n    if new.superseded_at is null\n      or old.superseded_at is not null\n      or to_jsonb(new) - 'superseded_at' - 'updated_at' is distinct from to_jsonb(old) - 'superseded_at' - 'updated_at'\n    then\n      raise exception 'A finalized SOAP record cannot be changed. Revise it to create a new version instead.';\n    end if;\n  end if;\n\n  return new;\nend;\n$$","comment on function public.guard_finalized_soap_update() is\n  'The only change ever permitted to a finalized SOAP record is\n   superseded_at moving from null to set, which is what\n   revise_soap_record() does on the old row once the new version exists.'","-- Alphabetically before soap_records_set_updated_at, so this sees updated_at\n-- still at its pre-update value — irrelevant here since it is excluded from\n-- the comparison either way, but kept consistent with the appointments guard.\ncreate trigger soap_records_guard_finalized_update\n  before update on public.soap_records\n  for each row execute function public.guard_finalized_soap_update()","-- ---------------------------------------------------------------------------\n-- Atomic revision: clone the finalized row as a new draft, supersede the old\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.revise_soap_record(p_soap_record_id uuid)\nreturns uuid\nlanguage plpgsql\nas $$\ndeclare\n  v_new_id uuid;\n  v_superseded_count integer;\nbegin\n  -- Supersede the old row first: the new row also has superseded_at null,\n  -- and the partial unique index allows only one such row per appointment —\n  -- inserting before this update would collide with the row it is replacing.\n  update public.soap_records\n     set superseded_at = now()\n   where id = p_soap_record_id\n     and status = 'finalized'\n     and superseded_at is null;\n  get diagnostics v_superseded_count = row_count;\n\n  if v_superseded_count = 0 then\n    raise exception 'Only the current finalized version of a SOAP record can be revised.';\n  end if;\n\n  insert into public.soap_records (\n    appointment_id, pet_id, organization_id, doctor_id, version, status,\n    chief_complaint, history, duration, appetite, water_intake, urination,\n    defecation, vomiting, diarrhea, coughing, sneezing, other_observations,\n    temperature_celsius, pulse_bpm, respiratory_rate_bpm, weight_grams,\n    body_condition_score, mucous_membrane, capillary_refill_time, hydration_status,\n    general_appearance, exam_eyes, exam_ears, exam_nose, exam_oral_cavity,\n    exam_cardiovascular, exam_respiratory, exam_gastrointestinal, exam_urinary,\n    exam_reproductive, exam_musculoskeletal, exam_neurological, exam_skin,\n    exam_lymph_nodes, exam_notes,\n    clinical_assessment, problem_list,\n    treatment, medication, diagnostics_plan, diet, hospitalization,\n    follow_up_needed, follow_up_notes, client_instructions,\n    created_by\n  )\n  select\n    appointment_id, pet_id, organization_id, doctor_id, version + 1, 'draft',\n    chief_complaint, history, duration, appetite, water_intake, urination,\n    defecation, vomiting, diarrhea, coughing, sneezing, other_observations,\n    temperature_celsius, pulse_bpm, respiratory_rate_bpm, weight_grams,\n    body_condition_score, mucous_membrane, capillary_refill_time, hydration_status,\n    general_appearance, exam_eyes, exam_ears, exam_nose, exam_oral_cavity,\n    exam_cardiovascular, exam_respiratory, exam_gastrointestinal, exam_urinary,\n    exam_reproductive, exam_musculoskeletal, exam_neurological, exam_skin,\n    exam_lymph_nodes, exam_notes,\n    clinical_assessment, problem_list,\n    treatment, medication, diagnostics_plan, diet, hospitalization,\n    follow_up_needed, follow_up_notes, client_instructions,\n    (select auth.uid())\n  from public.soap_records\n  where id = p_soap_record_id\n  returning id into v_new_id;\n\n  return v_new_id;\nend;\n$$","comment on function public.revise_soap_record(uuid) is\n  'Runs as the caller (no security definer): both the insert and the update\n   are subject to the normal soap_records RLS policies, so this only ever\n   succeeds for someone who could already do the equivalent writes by hand.'","revoke all on function public.revise_soap_record(uuid) from public, anon","grant execute on function public.revise_soap_record(uuid) to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- A finalized SOAP record exists for this appointment — gates client\n-- visibility of diagnoses and diagnostic tests the same way.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.has_finalized_soap(p_appointment_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select exists (\n    select 1 from public.soap_records sr\n    where sr.appointment_id = p_appointment_id\n      and sr.status = 'finalized'\n      and sr.superseded_at is null\n  );\n$$","revoke all on function public.has_finalized_soap(uuid) from public, anon","grant execute on function public.has_finalized_soap(uuid) to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- diagnoses — structured, not prose, so later phases can report on them\n-- without parsing text. Tied to the appointment (the visit), not to one\n-- specific SOAP version, so a record revision does not orphan them.\n-- ---------------------------------------------------------------------------\n\ncreate table public.diagnoses (\n  id uuid primary key default gen_random_uuid(),\n  appointment_id uuid not null,\n  pet_id uuid not null,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n\n  kind text not null,\n  -- The vet's own words. Never generated — see CLAUDE.md §11.\n  description text not null,\n\n  created_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint diagnoses_kind_allowed check (kind in ('differential', 'final')),\n  constraint diagnoses_description_not_blank check (length(btrim(description)) > 0),\n\n  constraint diagnoses_appointment_fk\n    foreign key (appointment_id, organization_id)\n    references public.appointments (id, organization_id)\n    on delete restrict,\n  constraint diagnoses_pet_fk\n    foreign key (pet_id, organization_id)\n    references public.pets (id, organization_id)\n    on delete restrict\n)","create index diagnoses_appointment_id_idx on public.diagnoses (appointment_id)","create index diagnoses_pet_id_idx on public.diagnoses (pet_id)","create trigger diagnoses_audit\n  after insert or update on public.diagnoses\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- diagnostics — ordered/tracked tests, §4.7. Also appointment-scoped.\n-- ---------------------------------------------------------------------------\n\ncreate table public.diagnostics (\n  id uuid primary key default gen_random_uuid(),\n  appointment_id uuid not null,\n  pet_id uuid not null,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n\n  test_name text not null,\n  test_type text,\n  status text not null default 'ordered',\n  ordered_at timestamptz not null default now(),\n  result_notes text,\n  document_id uuid references public.documents (id) on delete set null,\n\n  created_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint diagnostics_test_name_not_blank check (length(btrim(test_name)) > 0),\n  constraint diagnostics_status_allowed check (status in ('ordered', 'in_progress', 'completed')),\n\n  constraint diagnostics_appointment_fk\n    foreign key (appointment_id, organization_id)\n    references public.appointments (id, organization_id)\n    on delete restrict,\n  constraint diagnostics_pet_fk\n    foreign key (pet_id, organization_id)\n    references public.pets (id, organization_id)\n    on delete restrict\n)","create index diagnostics_appointment_id_idx on public.diagnostics (appointment_id)","create index diagnostics_pet_id_idx on public.diagnostics (pet_id)","create trigger diagnostics_set_updated_at\n  before update on public.diagnostics\n  for each row execute function public.set_updated_at()","create trigger diagnostics_audit\n  after insert or update on public.diagnostics\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- documents — extend with a clinical category, §4.7\n-- ---------------------------------------------------------------------------\n\nalter table public.documents\n  add column document_type text not null default 'other'","alter table public.documents\n  add constraint documents_document_type_allowed\n  check (document_type in ('lab_report', 'xray', 'ultrasound', 'blood_test', 'referral_letter', 'other'))","grant update (document_type) on public.documents to authenticated","-- ---------------------------------------------------------------------------\n-- Row level security\n--\n-- Clinical authorship is doctor-only throughout — see CLAUDE.md §11. Admin\n-- keeps read access for oversight, matching every other clinical table.\n-- ---------------------------------------------------------------------------\n\nalter table public.soap_records enable row level security","alter table public.diagnoses enable row level security","alter table public.diagnostics enable row level security","-- A client sees only the current, finalized version — never a draft, never\n-- a superseded one.\ncreate policy soap_records_select on public.soap_records\n  for select to authenticated\n  using (\n    (status = 'finalized' and superseded_at is null and public.owns_pet(pet_id))\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy soap_records_insert on public.soap_records\n  for insert to authenticated\n  with check (public.is_doctor(organization_id))","create policy soap_records_update on public.soap_records\n  for update to authenticated\n  using (public.is_doctor(organization_id))\n  with check (public.is_doctor(organization_id))","create policy diagnoses_select on public.diagnoses\n  for select to authenticated\n  using (\n    (public.owns_pet(pet_id) and public.has_finalized_soap(appointment_id))\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy diagnoses_insert on public.diagnoses\n  for insert to authenticated\n  with check (public.is_doctor(organization_id))","create policy diagnoses_update on public.diagnoses\n  for update to authenticated\n  using (public.is_doctor(organization_id))\n  with check (public.is_doctor(organization_id))","create policy diagnostics_select on public.diagnostics\n  for select to authenticated\n  using (\n    (public.owns_pet(pet_id) and public.has_finalized_soap(appointment_id))\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy diagnostics_insert on public.diagnostics\n  for insert to authenticated\n  with check (public.is_doctor(organization_id))","create policy diagnostics_update on public.diagnostics\n  for update to authenticated\n  using (public.is_doctor(organization_id))\n  with check (public.is_doctor(organization_id))","-- ---------------------------------------------------------------------------\n-- Privileges\n--\n-- No delete grant anywhere: clinical history is never destroyed, the same\n-- blanket rule already revoked in 20260820000100_core_schema.sql.\n-- ---------------------------------------------------------------------------\n\nrevoke all on public.soap_records, public.diagnoses, public.diagnostics from anon","grant select, insert on public.soap_records to authenticated","grant update (\n  doctor_id, status, finalized_at, superseded_at,\n  chief_complaint, history, duration, appetite, water_intake, urination,\n  defecation, vomiting, diarrhea, coughing, sneezing, other_observations,\n  temperature_celsius, pulse_bpm, respiratory_rate_bpm, weight_grams,\n  body_condition_score, mucous_membrane, capillary_refill_time, hydration_status,\n  general_appearance, exam_eyes, exam_ears, exam_nose, exam_oral_cavity,\n  exam_cardiovascular, exam_respiratory, exam_gastrointestinal, exam_urinary,\n  exam_reproductive, exam_musculoskeletal, exam_neurological, exam_skin,\n  exam_lymph_nodes, exam_notes,\n  clinical_assessment, problem_list,\n  treatment, medication, diagnostics_plan, diet, hospitalization,\n  follow_up_needed, follow_up_notes, follow_up_scheduled_at, client_instructions\n) on public.soap_records to authenticated","grant select, insert on public.diagnoses to authenticated","grant update (deleted_at) on public.diagnoses to authenticated","grant select, insert on public.diagnostics to authenticated","grant update (test_name, test_type, status, result_notes, document_id, deleted_at)\n  on public.diagnostics to authenticated","grant all on public.soap_records, public.diagnoses, public.diagnostics to service_role"}	soap_records
20260825000100	{"-- Phase 5 · Checkpoint 1 — prescriptions, dose calculation, PDF/signature storage.\n--\n-- Prescriptions are versioned exactly like soap_records (Phase 4): rows keyed\n-- by appointment_id, one current version (superseded_at is null), a guard\n-- trigger making a finalized row immutable except for superseded_at, and a\n-- revise_*() function that supersedes-then-inserts atomically — the ordering\n-- bug found and fixed in revise_soap_record() is avoided here by construction.\n\n-- ---------------------------------------------------------------------------\n-- medications — a global seeded catalog, not hard-coded in the app and not\n-- per-organization (drug names are not practice-specific the way services\n-- are). Full management is a later phase; this is what booking a visit's\n-- worth of drugs needs to exist today.\n-- ---------------------------------------------------------------------------\n\ncreate table public.medications (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  generic_name text,\n  common_strength text,\n  formulation text,\n  default_route text,\n  sort_order integer not null default 100,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint medications_name_not_blank check (length(btrim(name)) > 0)\n)","create unique index medications_name_key on public.medications (name) where deleted_at is null","create trigger medications_set_updated_at\n  before update on public.medications\n  for each row execute function public.set_updated_at()","alter table public.medications enable row level security","create policy medications_select on public.medications\n  for select to authenticated\n  using (true)","revoke all on public.medications from anon","grant select on public.medications to authenticated","grant all on public.medications to service_role","insert into public.medications (name, generic_name, common_strength, formulation, default_route, sort_order)\nvalues\n  ('Amoxicillin', 'Amoxicillin', '50 mg/mL', 'Oral suspension', 'PO', 10),\n  ('Meloxicam', 'Meloxicam', '1.5 mg/mL', 'Oral suspension', 'PO', 20),\n  ('Maropitant', 'Maropitant citrate', '10 mg', 'Tablet', 'PO', 30),\n  ('Metronidazole', 'Metronidazole', '250 mg', 'Tablet', 'PO', 40),\n  ('Cephalexin', 'Cephalexin', '250 mg', 'Capsule', 'PO', 50),\n  ('Dexamethasone', 'Dexamethasone', '2 mg/mL', 'Injectable', 'IM', 60),\n  ('Prednisolone', 'Prednisolone', '5 mg', 'Tablet', 'PO', 70),\n  ('Fenbendazole', 'Fenbendazole', '100 mg/mL', 'Oral suspension', 'PO', 80),\n  ('Ivermectin', 'Ivermectin', '10 mg/mL', 'Injectable', 'SC', 90),\n  ('Furosemide', 'Furosemide', '10 mg', 'Tablet', 'PO', 100)\non conflict do nothing","-- ---------------------------------------------------------------------------\n-- prescriptions\n-- ---------------------------------------------------------------------------\n\ncreate sequence public.prescription_number_seq","create table public.prescriptions (\n  id uuid primary key default gen_random_uuid(),\n  appointment_id uuid not null,\n  pet_id uuid not null,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  doctor_id uuid not null,\n\n  version integer not null default 1,\n  status text not null default 'draft',\n  finalized_at timestamptz,\n  -- Null means this is the current version of this appointment's prescription.\n  superseded_at timestamptz,\n\n  -- Stable across every version of one prescription: a correction is still\n  -- \\"the same document\\", the same way an invoice keeps its number when\n  -- amended. Generated once, copied forward by revise_prescription().\n  prescription_number text not null default ('RX-' || lpad(nextval('public.prescription_number_seq')::text, 6, '0')),\n\n  follow_up_date date,\n  instructions text,\n\n  -- Set only once finalized — a draft has nothing immutable to store yet.\n  pdf_path text,\n  signed_at timestamptz,\n\n  created_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n\n  constraint prescriptions_status_allowed check (status in ('draft', 'finalized')),\n  constraint prescriptions_version_positive check (version > 0),\n\n  constraint prescriptions_appointment_fk\n    foreign key (appointment_id, organization_id)\n    references public.appointments (id, organization_id)\n    on delete restrict,\n  constraint prescriptions_pet_fk\n    foreign key (pet_id, organization_id)\n    references public.pets (id, organization_id)\n    on delete restrict,\n  constraint prescriptions_doctor_fk\n    foreign key (doctor_id, organization_id)\n    references public.doctors (id, organization_id)\n    on delete restrict\n)","-- Partial, not a plain unique index: every version of one correction shares\n-- its prescription_number by design (see the comment on the column above),\n-- so uniqueness only needs to hold among current versions.\ncreate unique index prescriptions_number_current_key\n  on public.prescriptions (prescription_number)\n  where superseded_at is null","-- Exactly one current version per appointment.\ncreate unique index prescriptions_appointment_current_key\n  on public.prescriptions (appointment_id)\n  where superseded_at is null","create index prescriptions_pet_id_idx on public.prescriptions (pet_id)","create index prescriptions_doctor_id_idx on public.prescriptions (doctor_id)","create index prescriptions_organization_id_idx on public.prescriptions (organization_id)","comment on table public.prescriptions is\n  'One row per version of a visit''s prescription — same shape as\n   soap_records. A finalized row is immutable (guard_finalized_prescription_update);\n   revise_prescription() is the only way to correct one.'","create trigger prescriptions_set_updated_at\n  before update on public.prescriptions\n  for each row execute function public.set_updated_at()","create trigger prescriptions_audit\n  after insert or update on public.prescriptions\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- prescription_items\n-- ---------------------------------------------------------------------------\n\ncreate table public.prescription_items (\n  id uuid primary key default gen_random_uuid(),\n  prescription_id uuid not null references public.prescriptions (id) on delete restrict,\n  -- Reference only, for future reporting — never the source of truth for\n  -- what was actually prescribed. See drug_name/strength/formulation below.\n  medication_id uuid references public.medications (id) on delete set null,\n\n  -- Snapshotted at prescribing time. A prescription must keep saying exactly\n  -- what was prescribed even if the catalog entry is edited or retired later.\n  drug_name text not null,\n  strength text,\n  formulation text,\n\n  -- The calculator's inputs — both optional. A flat, non-weight-based dose\n  -- (e.g. \\"1 tablet BID\\") is an item where only computed_dose was typed.\n  dose_per_kg numeric,\n  dose_unit text,\n  computed_dose numeric,\n\n  route text,\n  frequency text,\n  duration text,\n  quantity text,\n  instructions text,\n\n  sort_order integer not null default 0,\n  created_at timestamptz not null default now(),\n\n  constraint prescription_items_drug_name_not_blank check (length(btrim(drug_name)) > 0),\n  constraint prescription_items_dose_per_kg_sane check (dose_per_kg is null or dose_per_kg > 0),\n  constraint prescription_items_computed_dose_sane check (computed_dose is null or computed_dose > 0)\n)","create index prescription_items_prescription_id_idx on public.prescription_items (prescription_id)","create trigger prescription_items_audit\n  after insert or update on public.prescription_items\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- A finalized prescription is immutable except for being superseded\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.guard_finalized_prescription_update()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if old.status = 'finalized' then\n    if new.superseded_at is null\n      or old.superseded_at is not null\n      or to_jsonb(new) - 'superseded_at' - 'updated_at' is distinct from to_jsonb(old) - 'superseded_at' - 'updated_at'\n    then\n      raise exception 'A finalized prescription cannot be changed. Revise it to create a new version instead.';\n    end if;\n  end if;\n\n  return new;\nend;\n$$","create trigger prescriptions_guard_finalized_update\n  before update on public.prescriptions\n  for each row execute function public.guard_finalized_prescription_update()","-- Once a prescription is finalized its items are part of the signed\n-- document too — immutable, full stop. Only a revision (a new prescription\n-- row with its own new items) may change what was prescribed.\ncreate or replace function public.guard_finalized_prescription_items()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_status text;\nbegin\n  select status into v_status from public.prescriptions where id = coalesce(new.prescription_id, old.prescription_id);\n\n  if v_status = 'finalized' then\n    raise exception 'Items on a finalized prescription cannot be changed. Revise the prescription instead.';\n  end if;\n\n  return coalesce(new, old);\nend;\n$$","create trigger prescription_items_guard_finalized\n  before insert or update or delete on public.prescription_items\n  for each row execute function public.guard_finalized_prescription_items()","-- ---------------------------------------------------------------------------\n-- Atomic revision: clone the finalized prescription and its items as a new\n-- draft version, supersede the old one — same shape as revise_soap_record(),\n-- superseding first so the new row never collides with the partial unique\n-- index on (appointment_id) where superseded_at is null.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.revise_prescription(p_prescription_id uuid)\nreturns uuid\nlanguage plpgsql\nas $$\ndeclare\n  v_new_id uuid;\n  v_updated integer;\nbegin\n  update public.prescriptions\n     set superseded_at = now()\n   where id = p_prescription_id\n     and status = 'finalized'\n     and superseded_at is null;\n  get diagnostics v_updated = row_count;\n\n  if v_updated = 0 then\n    raise exception 'Only the current finalized version of a prescription can be revised.';\n  end if;\n\n  insert into public.prescriptions (\n    appointment_id, pet_id, organization_id, doctor_id, version, status,\n    prescription_number, follow_up_date, instructions, created_by\n  )\n  select\n    appointment_id, pet_id, organization_id, doctor_id, version + 1, 'draft',\n    prescription_number, follow_up_date, instructions, (select auth.uid())\n  from public.prescriptions\n  where id = p_prescription_id\n  returning id into v_new_id;\n\n  insert into public.prescription_items (\n    prescription_id, medication_id, drug_name, strength, formulation,\n    dose_per_kg, dose_unit, computed_dose, route, frequency, duration, quantity, instructions, sort_order\n  )\n  select\n    v_new_id, medication_id, drug_name, strength, formulation,\n    dose_per_kg, dose_unit, computed_dose, route, frequency, duration, quantity, instructions, sort_order\n  from public.prescription_items\n  where prescription_id = p_prescription_id;\n\n  return v_new_id;\nend;\n$$","revoke all on function public.revise_prescription(uuid) from public, anon","grant execute on function public.revise_prescription(uuid) to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- Row level security — clinical authorship is doctor-only, admin reads,\n-- a client only ever reaches the current finalized version. Same shape as\n-- soap_records (Phase 4).\n-- ---------------------------------------------------------------------------\n\nalter table public.prescriptions enable row level security","alter table public.prescription_items enable row level security","create policy prescriptions_select on public.prescriptions\n  for select to authenticated\n  using (\n    (status = 'finalized' and superseded_at is null and public.owns_pet(pet_id))\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy prescriptions_insert on public.prescriptions\n  for insert to authenticated\n  with check (public.is_doctor(organization_id))","create policy prescriptions_update on public.prescriptions\n  for update to authenticated\n  using (public.is_doctor(organization_id))\n  with check (public.is_doctor(organization_id))","-- Items follow their prescription's own visibility — no separate pet_id/org\n-- columns to check, so the policy joins back to the parent row.\ncreate policy prescription_items_select on public.prescription_items\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.prescriptions rx\n      where rx.id = prescription_items.prescription_id\n        and (\n          (rx.status = 'finalized' and rx.superseded_at is null and public.owns_pet(rx.pet_id))\n          or public.is_admin(rx.organization_id)\n          or public.is_doctor(rx.organization_id)\n        )\n    )\n  )","create policy prescription_items_insert on public.prescription_items\n  for insert to authenticated\n  with check (\n    exists (\n      select 1 from public.prescriptions rx\n      where rx.id = prescription_items.prescription_id and public.is_doctor(rx.organization_id)\n    )\n  )","create policy prescription_items_update on public.prescription_items\n  for update to authenticated\n  using (\n    exists (\n      select 1 from public.prescriptions rx\n      where rx.id = prescription_items.prescription_id and public.is_doctor(rx.organization_id)\n    )\n  )\n  with check (\n    exists (\n      select 1 from public.prescriptions rx\n      where rx.id = prescription_items.prescription_id and public.is_doctor(rx.organization_id)\n    )\n  )","create policy prescription_items_delete on public.prescription_items\n  for delete to authenticated\n  using (\n    exists (\n      select 1 from public.prescriptions rx\n      where rx.id = prescription_items.prescription_id and public.is_doctor(rx.organization_id)\n    )\n  )","-- ---------------------------------------------------------------------------\n-- Privileges\n-- ---------------------------------------------------------------------------\n\nrevoke all on public.prescriptions, public.prescription_items from anon","grant select, insert on public.prescriptions to authenticated","grant update (\n  doctor_id, status, finalized_at, follow_up_date, instructions, pdf_path, signed_at, superseded_at\n) on public.prescriptions to authenticated","grant select, insert, delete on public.prescription_items to authenticated","grant update (\n  medication_id, drug_name, strength, formulation, dose_per_kg, dose_unit, computed_dose,\n  route, frequency, duration, quantity, instructions, sort_order\n) on public.prescription_items to authenticated","grant all on public.prescriptions, public.prescription_items to service_role","-- ---------------------------------------------------------------------------\n-- Storage — the finalized PDF and the doctor's signature image. Same\n-- private-bucket-plus-signed-URL shape as pet-photos/pet-documents.\n-- ---------------------------------------------------------------------------\n\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues\n  ('prescription-pdfs', 'prescription-pdfs', false, 5242880, array['application/pdf']),\n  ('doctor-signatures', 'doctor-signatures', false, 2097152, array['image/jpeg', 'image/png', 'image/webp'])\non conflict (id) do nothing","create policy prescription_pdfs_select on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = 'prescription-pdfs'\n    and (\n      exists (\n        select 1 from public.pets p\n        where p.id = public.pet_id_from_object_path(storage.objects.name)\n          and (public.is_admin(p.organization_id) or public.is_doctor(p.organization_id))\n      )\n      or exists (\n        select 1 from public.prescriptions rx\n        where rx.pdf_path = storage.objects.name\n          and rx.status = 'finalized'\n          and rx.superseded_at is null\n          and public.owns_pet(rx.pet_id)\n      )\n    )\n  )","create policy prescription_pdfs_insert on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'prescription-pdfs'\n    and exists (\n      select 1 from public.pets p\n      where p.id = public.pet_id_from_object_path(storage.objects.name)\n        and public.is_doctor(p.organization_id)\n    )\n  )","create policy prescription_pdfs_update on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = 'prescription-pdfs'\n    and exists (\n      select 1 from public.pets p\n      where p.id = public.pet_id_from_object_path(storage.objects.name)\n        and public.is_doctor(p.organization_id)\n    )\n  )\n  with check (\n    bucket_id = 'prescription-pdfs'\n    and exists (\n      select 1 from public.pets p\n      where p.id = public.pet_id_from_object_path(storage.objects.name)\n        and public.is_doctor(p.organization_id)\n    )\n  )","create or replace function public.doctor_id_from_object_path(p_name text)\nreturns uuid\nlanguage plpgsql\nimmutable\nas $$\nbegin\n  return (string_to_array(p_name, '/'))[1]::uuid;\nexception\n  when others then return null;\nend;\n$$","revoke all on function public.doctor_id_from_object_path(text) from public, anon","grant execute on function public.doctor_id_from_object_path(text) to authenticated, service_role","-- Staff only — a client never fetches a signature image directly, only the\n-- finished PDF a doctor's own session already generated it into.\ncreate policy doctor_signatures_select on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = 'doctor-signatures'\n    and exists (\n      select 1 from public.doctors d\n      where d.id = public.doctor_id_from_object_path(storage.objects.name)\n        and (public.is_admin(d.organization_id) or public.is_doctor(d.organization_id))\n    )\n  )","create policy doctor_signatures_insert on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'doctor-signatures'\n    and exists (\n      select 1 from public.doctors d\n      where d.id = public.doctor_id_from_object_path(storage.objects.name)\n        and (d.user_id = (select auth.uid()) or public.is_admin(d.organization_id))\n    )\n  )","create policy doctor_signatures_update on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = 'doctor-signatures'\n    and exists (\n      select 1 from public.doctors d\n      where d.id = public.doctor_id_from_object_path(storage.objects.name)\n        and (d.user_id = (select auth.uid()) or public.is_admin(d.organization_id))\n    )\n  )\n  with check (\n    bucket_id = 'doctor-signatures'\n    and exists (\n      select 1 from public.doctors d\n      where d.id = public.doctor_id_from_object_path(storage.objects.name)\n        and (d.user_id = (select auth.uid()) or public.is_admin(d.organization_id))\n    )\n  )"}	prescriptions
20260826000100	{"-- Phase 6 · Checkpoint 1 — vaccination schedules, vaccinations, deworming,\n-- and the reminder engine's notifications/notification_logs.\n--\n-- Two shapes reused verbatim from earlier phases: vaccinations and deworming\n-- records hang off an appointment exactly like diagnoses/diagnostics\n-- (Phase 4) — editable rows with soft delete, not versioned, since nothing in\n-- this phase's brief asks for immutability. vaccination_schedules is an\n-- admin-configurable catalog shaped like services (Phase 3), because §6.3 is\n-- explicit that schedules must never be hard-coded.\n\n-- ---------------------------------------------------------------------------\n-- vaccination_schedules — admin-configurable catalog, per organization\n-- ---------------------------------------------------------------------------\n\ncreate table public.vaccination_schedules (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  -- Null means \\"applies to any species\\".\n  species_id uuid references public.species (id) on delete restrict,\n\n  vaccine_name text not null,\n  interval_value integer not null,\n  interval_unit text not null,\n  description text,\n  sort_order integer not null default 100,\n  is_active boolean not null default true,\n\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint vaccination_schedules_name_not_blank check (length(btrim(vaccine_name)) > 0),\n  constraint vaccination_schedules_interval_value_positive check (interval_value > 0),\n  constraint vaccination_schedules_interval_unit_allowed\n    check (interval_unit in ('days', 'weeks', 'months', 'years'))\n)","create index vaccination_schedules_organization_id_idx on public.vaccination_schedules (organization_id)","create trigger vaccination_schedules_set_updated_at\n  before update on public.vaccination_schedules\n  for each row execute function public.set_updated_at()","create trigger vaccination_schedules_audit\n  after insert or update on public.vaccination_schedules\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- vaccinations — appointment-scoped, doctor-authored, editable, soft-deleted\n-- ---------------------------------------------------------------------------\n\ncreate table public.vaccinations (\n  id uuid primary key default gen_random_uuid(),\n  appointment_id uuid not null,\n  pet_id uuid not null,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  doctor_id uuid not null,\n  vaccination_schedule_id uuid references public.vaccination_schedules (id) on delete set null,\n\n  -- Snapshot, not a live join to vaccination_schedules — a later catalog edit\n  -- must never rewrite what was actually administered. Same pattern as\n  -- prescription_items' drug_name relative to medications (Phase 5).\n  vaccine_name text not null,\n  manufacturer text,\n  batch_number text,\n  lot_number text,\n  expiry_date date,\n  date_administered date not null,\n  dose text,\n  route text,\n  site text,\n  next_due_date date,\n  notes text,\n\n  created_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint vaccinations_vaccine_name_not_blank check (length(btrim(vaccine_name)) > 0),\n  constraint vaccinations_date_administered_not_future check (date_administered <= current_date),\n\n  constraint vaccinations_appointment_fk\n    foreign key (appointment_id, organization_id)\n    references public.appointments (id, organization_id)\n    on delete restrict,\n  constraint vaccinations_pet_fk\n    foreign key (pet_id, organization_id)\n    references public.pets (id, organization_id)\n    on delete restrict,\n  constraint vaccinations_doctor_fk\n    foreign key (doctor_id, organization_id)\n    references public.doctors (id, organization_id)\n    on delete restrict\n)","create index vaccinations_appointment_id_idx on public.vaccinations (appointment_id)","create index vaccinations_pet_id_idx on public.vaccinations (pet_id)","create index vaccinations_organization_id_idx on public.vaccinations (organization_id)","create trigger vaccinations_set_updated_at\n  before update on public.vaccinations\n  for each row execute function public.set_updated_at()","create trigger vaccinations_audit\n  after insert or update on public.vaccinations\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- deworming_records — same shape as vaccinations, no catalog table (§6.4\n-- only asks for a per-record interval choice, not an admin-managed list)\n-- ---------------------------------------------------------------------------\n\ncreate table public.deworming_records (\n  id uuid primary key default gen_random_uuid(),\n  appointment_id uuid not null,\n  pet_id uuid not null,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  doctor_id uuid not null,\n\n  product text not null,\n  active_ingredient text,\n  dose text,\n  route text,\n  -- Grams, matching pets.weight_grams/soap_records.weight_grams.\n  weight_grams integer,\n  date_administered date not null,\n  interval text not null,\n  custom_interval_days integer,\n  next_due_date date not null,\n  notes text,\n\n  created_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint deworming_records_product_not_blank check (length(btrim(product)) > 0),\n  constraint deworming_records_date_administered_not_future check (date_administered <= current_date),\n  constraint deworming_records_weight_sane\n    check (weight_grams is null or (weight_grams > 0 and weight_grams <= 2000000)),\n  constraint deworming_records_interval_allowed\n    check (interval in ('monthly', 'quarterly', 'semi_annual', 'custom')),\n  constraint deworming_records_custom_interval_days_required\n    check (\n      (interval = 'custom' and custom_interval_days is not null and custom_interval_days > 0)\n      or (interval <> 'custom' and custom_interval_days is null)\n    ),\n\n  constraint deworming_records_appointment_fk\n    foreign key (appointment_id, organization_id)\n    references public.appointments (id, organization_id)\n    on delete restrict,\n  constraint deworming_records_pet_fk\n    foreign key (pet_id, organization_id)\n    references public.pets (id, organization_id)\n    on delete restrict,\n  constraint deworming_records_doctor_fk\n    foreign key (doctor_id, organization_id)\n    references public.doctors (id, organization_id)\n    on delete restrict\n)","create index deworming_records_appointment_id_idx on public.deworming_records (appointment_id)","create index deworming_records_pet_id_idx on public.deworming_records (pet_id)","create index deworming_records_organization_id_idx on public.deworming_records (organization_id)","create trigger deworming_records_set_updated_at\n  before update on public.deworming_records\n  for each row execute function public.set_updated_at()","create trigger deworming_records_audit\n  after insert or update on public.deworming_records\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- Most recent record per pet — feeds PetCard, dashboards and due-worklists\n-- with one query instead of N+1s. Plain views (not security definer), so\n-- Postgres applies the underlying tables' row level security to whoever\n-- queries them — no extra policy needed.\n-- ---------------------------------------------------------------------------\n\ncreate view public.pet_vaccination_status as\nselect distinct on (v.pet_id)\n  v.pet_id,\n  v.organization_id,\n  v.id as vaccination_id,\n  v.vaccine_name,\n  v.date_administered,\n  v.next_due_date\nfrom public.vaccinations v\nwhere v.deleted_at is null\norder by v.pet_id, v.date_administered desc, v.created_at desc","create view public.pet_deworming_status as\nselect distinct on (d.pet_id)\n  d.pet_id,\n  d.organization_id,\n  d.id as deworming_record_id,\n  d.product,\n  d.date_administered,\n  d.next_due_date\nfrom public.deworming_records d\nwhere d.deleted_at is null\norder by d.pet_id, d.date_administered desc, d.created_at desc","grant select on public.pet_vaccination_status, public.pet_deworming_status to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- notifications / notification_logs — the reminder engine's own records.\n--\n-- This phase only ever creates vaccination_reminder/deworming_reminder rows,\n-- always channel = 'in_app', always left at status = 'scheduled' — actually\n-- dispatching anything (flipping to sent/delivered, or any external channel)\n-- is explicitly Phase 9 scope. The full type/channel/status vocabulary is\n-- defined now because the brief asks the architecture to be ready for it.\n-- ---------------------------------------------------------------------------\n\ncreate table public.notifications (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  recipient_user_id uuid not null references public.users (id) on delete restrict,\n\n  type text not null,\n  channel text not null default 'in_app',\n  status text not null default 'scheduled',\n\n  title text not null,\n  body text,\n  related_table text,\n  related_id uuid,\n\n  scheduled_for timestamptz,\n  sent_at timestamptz,\n  created_at timestamptz not null default now(),\n\n  constraint notifications_type_allowed check (\n    type in (\n      'appointment_reminder', 'vaccination_reminder', 'deworming_reminder',\n      'follow_up_reminder', 'invoice_reminder', 'payment_confirmation'\n    )\n  ),\n  constraint notifications_channel_allowed\n    check (channel in ('in_app', 'email', 'sms', 'whatsapp', 'push')),\n  constraint notifications_status_allowed\n    check (status in ('scheduled', 'sent', 'delivered', 'failed'))\n)","-- One scheduled reminder per source record per type — re-saving a due date\n-- updates the existing reminder instead of spawning a duplicate.\ncreate unique index notifications_related_scheduled_key\n  on public.notifications (related_table, related_id, type)\n  where status = 'scheduled'","create index notifications_recipient_id_idx on public.notifications (recipient_user_id)","create index notifications_organization_id_idx on public.notifications (organization_id)","create table public.notification_logs (\n  id uuid primary key default gen_random_uuid(),\n  notification_id uuid not null references public.notifications (id) on delete cascade,\n  event text not null,\n  detail text,\n  created_at timestamptz not null default now(),\n\n  constraint notification_logs_event_allowed\n    check (event in ('scheduled', 'sent', 'delivered', 'failed'))\n)","create index notification_logs_notification_id_idx on public.notification_logs (notification_id)","comment on table public.notifications is\n  'One row per reminder the engine has decided to send, in whatever state it\n   is currently in. This phase only ever creates vaccination_reminder and\n   deworming_reminder rows and never advances them past scheduled — actually\n   dispatching a channel is Phase 9.'","-- ---------------------------------------------------------------------------\n-- The reminder engine trigger: whenever a vaccination or deworming record's\n-- next_due_date is set, upsert one scheduled reminder for the pet's owner\n-- and log the transition.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.notify_due_reminder()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_recipient_user_id uuid;\n  v_notification_type text;\n  v_title text;\n  v_body text;\n  v_notification_id uuid;\nbegin\n  if new.next_due_date is null then\n    return new;\n  end if;\n\n  select c.user_id\n    into v_recipient_user_id\n  from public.pets p\n  join public.clients c on c.id = p.client_id\n  where p.id = new.pet_id;\n\n  -- A walk-in client with no login yet has nothing to notify.\n  if v_recipient_user_id is null then\n    return new;\n  end if;\n\n  if tg_table_name = 'vaccinations' then\n    v_notification_type := 'vaccination_reminder';\n    v_title := 'Vaccination due: ' || new.vaccine_name;\n    v_body := 'Next due ' || to_char(new.next_due_date, 'DD Mon YYYY') || '.';\n  else\n    v_notification_type := 'deworming_reminder';\n    v_title := 'Deworming due: ' || new.product;\n    v_body := 'Next due ' || to_char(new.next_due_date, 'DD Mon YYYY') || '.';\n  end if;\n\n  insert into public.notifications (\n    organization_id, recipient_user_id, type, channel, status,\n    title, body, related_table, related_id, scheduled_for\n  )\n  values (\n    new.organization_id, v_recipient_user_id, v_notification_type, 'in_app', 'scheduled',\n    v_title, v_body, tg_table_name, new.id, new.next_due_date - interval '7 days'\n  )\n  on conflict (related_table, related_id, type) where status = 'scheduled'\n  do update set\n    title = excluded.title,\n    body = excluded.body,\n    scheduled_for = excluded.scheduled_for\n  returning id into v_notification_id;\n\n  insert into public.notification_logs (notification_id, event, detail)\n  values (v_notification_id, 'scheduled', v_title);\n\n  return new;\nend;\n$$","revoke all on function public.notify_due_reminder() from public, anon","create trigger vaccinations_notify_due_reminder\n  after insert or update of next_due_date on public.vaccinations\n  for each row execute function public.notify_due_reminder()","create trigger deworming_records_notify_due_reminder\n  after insert or update of next_due_date on public.deworming_records\n  for each row execute function public.notify_due_reminder()","-- ---------------------------------------------------------------------------\n-- Row level security\n-- ---------------------------------------------------------------------------\n\nalter table public.vaccination_schedules enable row level security","alter table public.vaccinations enable row level security","alter table public.deworming_records enable row level security","alter table public.notifications enable row level security","alter table public.notification_logs enable row level security","create policy vaccination_schedules_select on public.vaccination_schedules\n  for select to authenticated\n  using (public.is_org_member(organization_id))","create policy vaccination_schedules_insert on public.vaccination_schedules\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy vaccination_schedules_update on public.vaccination_schedules\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","-- Clinical authorship stays doctor-only, matching soap_records/diagnoses/\n-- diagnostics/prescriptions. A client sees any record for a pet they own —\n-- unlike diagnoses/diagnostics, this is not gated behind a finalized SOAP: a\n-- vaccination is very often the entire point of the visit.\ncreate policy vaccinations_select on public.vaccinations\n  for select to authenticated\n  using (\n    public.owns_pet(pet_id)\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy vaccinations_insert on public.vaccinations\n  for insert to authenticated\n  with check (public.is_doctor(organization_id))","create policy vaccinations_update on public.vaccinations\n  for update to authenticated\n  using (public.is_doctor(organization_id))\n  with check (public.is_doctor(organization_id))","create policy deworming_records_select on public.deworming_records\n  for select to authenticated\n  using (\n    public.owns_pet(pet_id)\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy deworming_records_insert on public.deworming_records\n  for insert to authenticated\n  with check (public.is_doctor(organization_id))","create policy deworming_records_update on public.deworming_records\n  for update to authenticated\n  using (public.is_doctor(organization_id))\n  with check (public.is_doctor(organization_id))","-- notifications/notification_logs are written only by the trigger above\n-- (security definer, runs regardless of the writing doctor's own grants) —\n-- no authenticated insert/update policy exists for either table.\ncreate policy notifications_select on public.notifications\n  for select to authenticated\n  using (recipient_user_id = (select auth.uid()) or public.is_admin(organization_id))","create policy notification_logs_select on public.notification_logs\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.notifications n\n      where n.id = notification_logs.notification_id\n        and (n.recipient_user_id = (select auth.uid()) or public.is_admin(n.organization_id))\n    )\n  )","-- ---------------------------------------------------------------------------\n-- Privileges — no delete grant anywhere: clinical history is never\n-- destroyed, matching every table since 20260820000100_core_schema.sql.\n-- ---------------------------------------------------------------------------\n\nrevoke all on public.vaccination_schedules, public.vaccinations, public.deworming_records,\n  public.notifications, public.notification_logs\n  from anon","grant select, insert on public.vaccination_schedules to authenticated","grant update (\n  species_id, vaccine_name, interval_value, interval_unit, description, sort_order, is_active, deleted_at\n) on public.vaccination_schedules to authenticated","grant select, insert on public.vaccinations to authenticated","grant update (\n  vaccination_schedule_id, vaccine_name, manufacturer, batch_number, lot_number, expiry_date,\n  date_administered, dose, route, site, next_due_date, notes, deleted_at\n) on public.vaccinations to authenticated","grant select, insert on public.deworming_records to authenticated","grant update (\n  product, active_ingredient, dose, route, weight_grams, date_administered,\n  interval, custom_interval_days, next_due_date, notes, deleted_at\n) on public.deworming_records to authenticated","grant select on public.notifications, public.notification_logs to authenticated","grant all on public.vaccination_schedules, public.vaccinations, public.deworming_records,\n  public.notifications, public.notification_logs\n  to service_role","-- ---------------------------------------------------------------------------\n-- A starting vaccination schedule catalog for the seeded practice — the\n-- brief's own §6.3 display example (DHPP / Rabies / Bordetella), proving the\n-- table is real, admin-editable reference data rather than hard-coded UI copy.\n-- ---------------------------------------------------------------------------\n\ninsert into public.vaccination_schedules (organization_id, species_id, vaccine_name, interval_value, interval_unit, description, sort_order)\nselect o.id, s.id, schedule.vaccine_name, schedule.interval_value, schedule.interval_unit, schedule.description, schedule.sort_order\nfrom public.organizations o\njoin (values\n  ('DHPP', 'dog', 12, 'months', 'Distemper, hepatitis, parainfluenza, parvovirus.', 10),\n  ('Rabies', 'dog', 12, 'months', 'Required for licensing in most areas.', 20),\n  ('Bordetella', 'dog', 6, 'months', 'Kennel cough, recommended for boarding/grooming.', 30),\n  ('FVRCP', 'cat', 12, 'months', 'Feline viral rhinotracheitis, calicivirus, panleukopenia.', 40),\n  ('Rabies', 'cat', 12, 'months', 'Required for licensing in most areas.', 50)\n) as schedule(vaccine_name, species_slug, interval_value, interval_unit, description, sort_order)\n  on true\njoin public.species s on s.slug = schedule.species_slug\nwhere o.slug = 'the-traveling-vet'\non conflict do nothing"}	vaccination_deworming
20260827000100	{"-- Phase 7 · Checkpoint 1 — service catalog, invoices, payments, and the\n-- reminder engine's remaining two notification types.\n--\n-- The one genuinely new idea here: every other phase let a person freely\n-- override a suggestion (a dose, a due date). An invoice cannot work that\n-- way — \\"items - discount + tax = total\\" and \\"paid + balance = total\\" must\n-- hold, always, not just when someone remembered to check the arithmetic.\n-- recalculate_invoice_totals() below is a database trigger, not a\n-- suggestion: it recomputes every derived column from the source rows\n-- (invoice_items, payments) on every write, so the invariant holds by\n-- construction.\n\n-- ---------------------------------------------------------------------------\n-- service_categories — admin-configurable, never hard-coded, same shape as\n-- vaccination_schedules (Phase 6)\n-- ---------------------------------------------------------------------------\n\ncreate table public.service_categories (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  name text not null,\n  sort_order integer not null default 100,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint service_categories_name_not_blank check (length(btrim(name)) > 0)\n)","create unique index service_categories_organization_id_name_key\n  on public.service_categories (organization_id, name)\n  where deleted_at is null","create index service_categories_organization_id_idx on public.service_categories (organization_id)","create trigger service_categories_set_updated_at\n  before update on public.service_categories\n  for each row execute function public.set_updated_at()","create trigger service_categories_audit\n  after insert or update on public.service_categories\n  for each row execute function public.write_audit_log()","insert into public.service_categories (organization_id, name, sort_order)\nselect o.id, category.name, category.sort_order\nfrom public.organizations o\njoin (values\n  ('Consultation', 10),\n  ('Follow-up', 20),\n  ('Home visit', 30),\n  ('Vaccination', 40),\n  ('Deworming', 50),\n  ('Surgery', 60),\n  ('Diagnostic test', 70),\n  ('Procedure', 80),\n  ('Medicine', 90),\n  ('Other services', 100)\n) as category(name, sort_order) on true\nwhere o.slug = 'the-traveling-vet'\non conflict do nothing","-- ---------------------------------------------------------------------------\n-- services — extended in place. Phase 3 already seeded seven rows the\n-- booking flow depends on; nothing here changes what booking reads.\n-- ---------------------------------------------------------------------------\n\nalter table public.services\n  add column category_id uuid references public.service_categories (id) on delete set null,\n  add column price_paisa integer not null default 0,\n  add column tax_rate_percent numeric(5, 2) not null default 0,\n  add column is_home_visit_available boolean not null default false,\n  add column is_home_visit_fee boolean not null default false,\n  add column requires_doctor boolean not null default true","alter table public.services\n  add constraint services_price_sane check (price_paisa >= 0),\n  add constraint services_tax_rate_sane check (tax_rate_percent >= 0 and tax_rate_percent <= 100)","-- At most one home-visit fee row per organization.\ncreate unique index services_organization_id_home_visit_fee_key\n  on public.services (organization_id)\n  where is_home_visit_fee and deleted_at is null","-- Backfill categories for the services Phase 3 already seeded, by name —\n-- no data is invented, this only links rows that already exist.\nupdate public.services s\nset category_id = sc.id\nfrom public.service_categories sc\nwhere s.organization_id = sc.organization_id\n  and sc.name = (\n    case s.name\n      when 'General consultation' then 'Consultation'\n      when 'Follow-up consultation' then 'Follow-up'\n      when 'Vaccination' then 'Vaccination'\n      when 'Deworming' then 'Deworming'\n      when 'Emergency consultation' then 'Consultation'\n      when 'Surgery' then 'Surgery'\n      when 'Home visit consultation' then 'Home visit'\n    end\n  )\n  and s.category_id is null","update public.services\nset is_home_visit_available = true\nwhere name = 'Home visit consultation'","-- The privilege the original migration never granted — RLS already allowed\n-- an admin to write here, but the underlying column privilege did not exist.\ngrant insert on public.services to authenticated","grant update (\n  name, description, duration_minutes, sort_order, is_active,\n  category_id, price_paisa, tax_rate_percent, is_home_visit_available,\n  is_home_visit_fee, requires_doctor, deleted_at\n) on public.services to authenticated","-- services already has an audit trigger from Phase 3 — no need to add one.\n\n-- ---------------------------------------------------------------------------\n-- doctors — §7.8's permission flag, and organizations — payment information\n-- for the invoice PDF (§7.5).\n-- ---------------------------------------------------------------------------\n\nalter table public.doctors\n  add column can_manage_billing boolean not null default false","grant update (can_manage_billing) on public.doctors to authenticated","-- Column-level grants cannot stop a doctor from updating their own row\n-- (doctors_update's RLS policy already allows that, for their profile\n-- fields) — only a trigger can single out this one column.\ncreate or replace function public.guard_doctor_billing_permission_update()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if (select auth.uid()) is null then\n    return new; -- service role: test fixtures and admin scripts.\n  end if;\n\n  if new.can_manage_billing is distinct from old.can_manage_billing\n    and not public.is_admin(new.organization_id)\n  then\n    raise exception 'Only an administrator can change billing permission.';\n  end if;\n\n  return new;\nend;\n$$","create trigger doctors_guard_billing_permission_update\n  before update on public.doctors\n  for each row execute function public.guard_doctor_billing_permission_update()","alter table public.organizations\n  add column payment_instructions text","grant update (payment_instructions) on public.organizations to authenticated","create or replace function public.is_billing_manager(p_organization_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.is_admin(p_organization_id) or (\n    public.is_doctor(p_organization_id) and exists (\n      select 1 from public.doctors d\n      where d.user_id = (select auth.uid())\n        and d.organization_id = p_organization_id\n        and d.can_manage_billing\n        and d.deleted_at is null\n    )\n  );\n$$","revoke all on function public.is_billing_manager(uuid) from public, anon","grant execute on function public.is_billing_manager(uuid) to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- Composite-FK support\n-- ---------------------------------------------------------------------------\n\ncreate unique index service_categories_id_organization_id_key\n  on public.service_categories (id, organization_id)","-- ---------------------------------------------------------------------------\n-- invoices\n-- ---------------------------------------------------------------------------\n\ncreate sequence public.invoice_number_seq","create table public.invoices (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  client_id uuid not null,\n  pet_id uuid,\n  appointment_id uuid,\n\n  invoice_number text not null default ('INV-' || lpad(nextval('public.invoice_number_seq')::text, 6, '0')),\n  status text not null default 'draft',\n\n  -- Trigger-maintained from invoice_items/payments — see\n  -- recalculate_invoice_totals() below. discount_paisa is the one column\n  -- here a person actually types; every other total is derived.\n  subtotal_paisa integer not null default 0,\n  discount_paisa integer not null default 0,\n  tax_paisa integer not null default 0,\n  total_paisa integer not null default 0,\n  amount_paid_paisa integer not null default 0,\n  balance_paisa integer not null default 0,\n\n  issued_at timestamptz,\n  due_date date,\n  notes text,\n  cancelled_at timestamptz,\n  cancellation_reason text,\n  pdf_path text,\n\n  created_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  deleted_at timestamptz,\n\n  constraint invoices_status_allowed check (\n    status in ('draft', 'issued', 'partially_paid', 'paid', 'cancelled', 'refunded')\n  ),\n  constraint invoices_discount_sane check (discount_paisa >= 0),\n\n  constraint invoices_client_fk\n    foreign key (client_id, organization_id)\n    references public.clients (id, organization_id)\n    on delete restrict,\n  constraint invoices_pet_fk\n    foreign key (pet_id, organization_id)\n    references public.pets (id, organization_id)\n    on delete restrict,\n  constraint invoices_appointment_fk\n    foreign key (appointment_id, organization_id)\n    references public.appointments (id, organization_id)\n    on delete restrict\n)","create unique index invoices_invoice_number_key on public.invoices (invoice_number)","create index invoices_client_id_idx on public.invoices (client_id)","create index invoices_pet_id_idx on public.invoices (pet_id)","create index invoices_organization_id_idx on public.invoices (organization_id)","create index invoices_status_idx on public.invoices (status)","create unique index invoices_id_organization_id_key on public.invoices (id, organization_id)","comment on table public.invoices is\n  'subtotal_paisa, tax_paisa, total_paisa, amount_paid_paisa, balance_paisa and\n   status are maintained entirely by recalculate_invoice_totals() — never\n   written directly by the application. discount_paisa and everything else\n   here is a normal, directly-editable column.'","create trigger invoices_set_updated_at\n  before update on public.invoices\n  for each row execute function public.set_updated_at()","create trigger invoices_audit\n  after insert or update on public.invoices\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- invoice_items — snapshot pattern (service_id optional, description/price\n-- copied at add time), exactly like prescription_items relative to\n-- medications.\n-- ---------------------------------------------------------------------------\n\ncreate table public.invoice_items (\n  id uuid primary key default gen_random_uuid(),\n  invoice_id uuid not null references public.invoices (id) on delete restrict,\n  service_id uuid references public.services (id) on delete set null,\n\n  description text not null,\n  quantity integer not null default 1,\n  unit_price_paisa integer not null,\n  tax_rate_percent numeric(5, 2) not null default 0,\n  line_total_paisa integer not null,\n  sort_order integer not null default 100,\n\n  created_at timestamptz not null default now(),\n\n  constraint invoice_items_description_not_blank check (length(btrim(description)) > 0),\n  constraint invoice_items_quantity_positive check (quantity > 0),\n  constraint invoice_items_unit_price_sane check (unit_price_paisa >= 0),\n  constraint invoice_items_tax_rate_sane check (tax_rate_percent >= 0 and tax_rate_percent <= 100),\n  constraint invoice_items_line_total_reconciles check (line_total_paisa = quantity * unit_price_paisa)\n)","create index invoice_items_invoice_id_idx on public.invoice_items (invoice_id)","-- ---------------------------------------------------------------------------\n-- payments — insert-only ledger. gateway/status are architecture-ready for\n-- §7.6's future online gateway; every row this phase is\n-- gateway = 'manual', status = 'completed'.\n-- ---------------------------------------------------------------------------\n\ncreate table public.payments (\n  id uuid primary key default gen_random_uuid(),\n  invoice_id uuid not null references public.invoices (id) on delete restrict,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n\n  amount_paisa integer not null,\n  method text not null,\n  gateway text not null default 'manual',\n  status text not null default 'completed',\n  reference_number text,\n  paid_at timestamptz not null default now(),\n  notes text,\n\n  recorded_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n\n  constraint payments_amount_positive check (amount_paisa > 0),\n  constraint payments_method_allowed check (\n    method in ('cash', 'bank_transfer', 'bkash', 'nagad', 'card', 'other')\n  ),\n  constraint payments_status_allowed check (status in ('completed', 'pending', 'failed'))\n)","create index payments_invoice_id_idx on public.payments (invoice_id)","create index payments_organization_id_idx on public.payments (organization_id)","create trigger payments_audit\n  after insert on public.payments\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- The invariant: items - discount + tax = total, paid + balance = total,\n-- always. Recomputed from source rows on every relevant write, never\n-- trusted from the application.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.recalculate_invoice_totals()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_invoice_id uuid;\n  v_subtotal integer;\n  v_tax integer;\n  v_discount integer;\n  v_total integer;\n  v_paid integer;\nbegin\n  -- NEW/OLD are generic records here, so a field that does not exist on the\n  -- triggering table's row type cannot even be referenced, let alone\n  -- coalesced — invoices has no invoice_id column, only id.\n  if tg_table_name = 'invoices' then\n    v_invoice_id := coalesce(new.id, old.id);\n  else\n    v_invoice_id := coalesce(new.invoice_id, old.invoice_id);\n  end if;\n\n  select coalesce(sum(line_total_paisa), 0),\n         coalesce(sum(round(line_total_paisa * tax_rate_percent / 100.0)), 0)\n    into v_subtotal, v_tax\n    from public.invoice_items\n   where invoice_id = v_invoice_id;\n\n  select discount_paisa into v_discount from public.invoices where id = v_invoice_id;\n  v_total := v_subtotal - coalesce(v_discount, 0) + v_tax;\n\n  select coalesce(sum(amount_paisa), 0) into v_paid\n    from public.payments\n   where invoice_id = v_invoice_id and status = 'completed';\n\n  update public.invoices\n     set subtotal_paisa = v_subtotal,\n         tax_paisa = v_tax,\n         total_paisa = v_total,\n         amount_paid_paisa = v_paid,\n         balance_paisa = v_total - v_paid,\n         status = case\n           when status in ('cancelled', 'refunded') then status\n           when v_total > 0 and v_paid >= v_total then 'paid'\n           when v_paid > 0 and v_paid < v_total then 'partially_paid'\n           when status = 'partially_paid' and v_paid = 0 then 'issued'\n           else status\n         end\n   where id = v_invoice_id;\n\n  return coalesce(new, old);\nend;\n$$","create trigger invoice_items_recalculate_totals\n  after insert or update or delete on public.invoice_items\n  for each row execute function public.recalculate_invoice_totals()","create trigger payments_recalculate_totals\n  after insert on public.payments\n  for each row execute function public.recalculate_invoice_totals()","create trigger invoices_recalculate_totals_on_discount\n  after update of discount_paisa on public.invoices\n  for each row\n  when (old.discount_paisa is distinct from new.discount_paisa)\n  execute function public.recalculate_invoice_totals()","-- An issued invoice's line items are immutable — a correction cancels the\n-- invoice and issues a new one, the same reasoning every clinical\n-- guard_finalized_* trigger already uses for a document once it is final.\ncreate or replace function public.guard_issued_invoice_items()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_invoice_id uuid;\n  v_status text;\nbegin\n  if (select auth.uid()) is null then\n    return coalesce(new, old);\n  end if;\n\n  v_invoice_id := coalesce(new.invoice_id, old.invoice_id);\n  select status into v_status from public.invoices where id = v_invoice_id;\n\n  if v_status is distinct from 'draft' then\n    raise exception 'This invoice has been issued and its items can no longer be changed.';\n  end if;\n\n  return coalesce(new, old);\nend;\n$$","create trigger invoice_items_guard_issued\n  before insert or update or delete on public.invoice_items\n  for each row execute function public.guard_issued_invoice_items()","-- ---------------------------------------------------------------------------\n-- Reminder engine — the last two notification types from §6.5/§7.7.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.notify_invoice_issued()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_recipient_user_id uuid;\n  v_notification_id uuid;\nbegin\n  select c.user_id into v_recipient_user_id\n  from public.clients c where c.id = new.client_id;\n\n  if v_recipient_user_id is null then\n    return new;\n  end if;\n\n  insert into public.notifications (\n    organization_id, recipient_user_id, type, channel, status,\n    title, body, related_table, related_id, scheduled_for\n  )\n  values (\n    new.organization_id, v_recipient_user_id, 'invoice_reminder', 'in_app', 'scheduled',\n    'Invoice ' || new.invoice_number,\n    'Amount due: ' || (new.total_paisa / 100.0)::text || ' BDT.',\n    'invoices', new.id, coalesce(new.due_date::timestamptz, now())\n  )\n  on conflict (related_table, related_id, type) where status = 'scheduled'\n  do update set title = excluded.title, body = excluded.body, scheduled_for = excluded.scheduled_for\n  returning id into v_notification_id;\n\n  insert into public.notification_logs (notification_id, event, detail)\n  values (v_notification_id, 'scheduled', 'Invoice issued');\n\n  return new;\nend;\n$$","create trigger invoices_notify_issued\n  after update of status on public.invoices\n  for each row\n  when (old.status = 'draft' and new.status = 'issued')\n  execute function public.notify_invoice_issued()","create or replace function public.notify_payment_recorded()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_recipient_user_id uuid;\n  v_client_id uuid;\n  v_notification_id uuid;\nbegin\n  select client_id into v_client_id from public.invoices where id = new.invoice_id;\n  select c.user_id into v_recipient_user_id from public.clients c where c.id = v_client_id;\n\n  if v_recipient_user_id is null then\n    return new;\n  end if;\n\n  insert into public.notifications (\n    organization_id, recipient_user_id, type, channel, status,\n    title, body, related_table, related_id, scheduled_for\n  )\n  values (\n    new.organization_id, v_recipient_user_id, 'payment_confirmation', 'in_app', 'scheduled',\n    'Payment received',\n    'We received a payment of ' || (new.amount_paisa / 100.0)::text || ' BDT.',\n    'payments', new.id, now()\n  )\n  returning id into v_notification_id;\n\n  insert into public.notification_logs (notification_id, event, detail)\n  values (v_notification_id, 'scheduled', 'Payment recorded');\n\n  return new;\nend;\n$$","create trigger payments_notify_recorded\n  after insert on public.payments\n  for each row execute function public.notify_payment_recorded()","-- ---------------------------------------------------------------------------\n-- Row level security\n-- ---------------------------------------------------------------------------\n\nalter table public.service_categories enable row level security","alter table public.invoices enable row level security","alter table public.invoice_items enable row level security","alter table public.payments enable row level security","create policy service_categories_select on public.service_categories\n  for select to authenticated\n  using (public.is_org_member(organization_id))","create policy service_categories_insert on public.service_categories\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy service_categories_update on public.service_categories\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","-- A client sees their own non-draft invoices only; staff see everything in\n-- their organization. Read access is not gated by is_billing_manager — a\n-- doctor without the finance flag can still see what a patient owes, the\n-- same as every other clinical table; only writing is restricted.\ncreate policy invoices_select on public.invoices\n  for select to authenticated\n  using (\n    (public.owns_client(client_id) and status <> 'draft')\n    or public.is_admin(organization_id)\n    or public.is_doctor(organization_id)\n  )","create policy invoices_insert on public.invoices\n  for insert to authenticated\n  with check (public.is_billing_manager(organization_id))","create policy invoices_update on public.invoices\n  for update to authenticated\n  using (public.is_billing_manager(organization_id))\n  with check (public.is_billing_manager(organization_id))","create policy invoice_items_select on public.invoice_items\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.invoices i\n      where i.id = invoice_items.invoice_id\n        and (\n          (public.owns_client(i.client_id) and i.status <> 'draft')\n          or public.is_admin(i.organization_id)\n          or public.is_doctor(i.organization_id)\n        )\n    )\n  )","create policy invoice_items_insert on public.invoice_items\n  for insert to authenticated\n  with check (\n    exists (\n      select 1 from public.invoices i\n      where i.id = invoice_items.invoice_id and public.is_billing_manager(i.organization_id)\n    )\n  )","create policy invoice_items_update on public.invoice_items\n  for update to authenticated\n  using (\n    exists (\n      select 1 from public.invoices i\n      where i.id = invoice_items.invoice_id and public.is_billing_manager(i.organization_id)\n    )\n  )\n  with check (\n    exists (\n      select 1 from public.invoices i\n      where i.id = invoice_items.invoice_id and public.is_billing_manager(i.organization_id)\n    )\n  )","create policy invoice_items_delete on public.invoice_items\n  for delete to authenticated\n  using (\n    exists (\n      select 1 from public.invoices i\n      where i.id = invoice_items.invoice_id and public.is_billing_manager(i.organization_id)\n    )\n  )","create policy payments_select on public.payments\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.invoices i\n      where i.id = payments.invoice_id\n        and (\n          (public.owns_client(i.client_id) and i.status <> 'draft')\n          or public.is_admin(i.organization_id)\n          or public.is_doctor(i.organization_id)\n        )\n    )\n  )","create policy payments_insert on public.payments\n  for insert to authenticated\n  with check (public.is_billing_manager(organization_id))","-- ---------------------------------------------------------------------------\n-- Privileges — no delete grant anywhere except invoice_items (draft-only,\n-- guarded above); financial history is never destroyed otherwise.\n-- ---------------------------------------------------------------------------\n\nrevoke all on public.service_categories, public.invoices, public.invoice_items, public.payments from anon","grant select, insert on public.service_categories to authenticated","grant update (name, sort_order, is_active, deleted_at) on public.service_categories to authenticated","grant select, insert on public.invoices to authenticated","grant update (\n  pet_id, appointment_id, discount_paisa, notes, status, issued_at, due_date,\n  cancelled_at, cancellation_reason, pdf_path, deleted_at\n) on public.invoices to authenticated","grant select, insert, update, delete on public.invoice_items to authenticated","grant select, insert on public.payments to authenticated","grant all on public.service_categories, public.invoices, public.invoice_items, public.payments to service_role","-- ---------------------------------------------------------------------------\n-- Storage — the issued invoice PDF, same private-bucket-plus-signed-URL\n-- shape as prescription-pdfs.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.client_id_from_object_path(p_name text)\nreturns uuid\nlanguage plpgsql\nimmutable\nas $$\nbegin\n  return (string_to_array(p_name, '/'))[1]::uuid;\nexception\n  when others then return null;\nend;\n$$","revoke all on function public.client_id_from_object_path(text) from public, anon","grant execute on function public.client_id_from_object_path(text) to authenticated, service_role","insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues ('invoice-pdfs', 'invoice-pdfs', false, 5242880, array['application/pdf'])\non conflict (id) do nothing","create policy invoice_pdfs_select on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = 'invoice-pdfs'\n    and (\n      exists (\n        select 1 from public.clients c\n        where c.id = public.client_id_from_object_path(storage.objects.name)\n          and (public.is_admin(c.organization_id) or public.is_doctor(c.organization_id))\n      )\n      or exists (\n        select 1 from public.invoices i\n        where i.pdf_path = storage.objects.name\n          and i.status <> 'draft'\n          and public.owns_client(i.client_id)\n      )\n    )\n  )","create policy invoice_pdfs_insert on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'invoice-pdfs'\n    and exists (\n      select 1 from public.clients c\n      where c.id = public.client_id_from_object_path(storage.objects.name)\n        and public.is_billing_manager(c.organization_id)\n    )\n  )","create policy invoice_pdfs_update on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = 'invoice-pdfs'\n    and exists (\n      select 1 from public.clients c\n      where c.id = public.client_id_from_object_path(storage.objects.name)\n        and public.is_billing_manager(c.organization_id)\n    )\n  )\n  with check (\n    bucket_id = 'invoice-pdfs'\n    and exists (\n      select 1 from public.clients c\n      where c.id = public.client_id_from_object_path(storage.objects.name)\n        and public.is_billing_manager(c.organization_id)\n    )\n  )"}	billing
20260828000100	{"-- Phase 8 · Checkpoint 1 — reporting functions and the reports permission.\n--\n-- Nothing here is a new table of clinical or financial record — every\n-- report reads data seven earlier phases already created. The one real\n-- design problem is §8.6: a doctor already has org-wide select on\n-- payments/invoices/appointments/etc for legitimate per-record reasons (the\n-- vaccinations worklist, opening one patient's invoice), so leaving reports\n-- as plain queries against those tables would not actually stop a doctor\n-- aggregating the same rows themselves. Every report below is instead a\n-- security definer function that checks is_report_viewer() itself, before\n-- ever touching a row — a real boundary, independent of table RLS.\n\n-- ---------------------------------------------------------------------------\n-- doctors.can_view_reports — §8.6's permission flag, same shape as Phase 7's\n-- can_manage_billing. The existing single-purpose guard trigger is widened\n-- to cover both columns and renamed to say so.\n-- ---------------------------------------------------------------------------\n\nalter table public.doctors\n  add column can_view_reports boolean not null default false","grant update (can_view_reports) on public.doctors to authenticated","drop trigger doctors_guard_billing_permission_update on public.doctors","drop function public.guard_doctor_billing_permission_update()","create or replace function public.guard_doctor_permission_update()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if (select auth.uid()) is null then\n    return new; -- service role: test fixtures and admin scripts.\n  end if;\n\n  if (\n    new.can_manage_billing is distinct from old.can_manage_billing\n    or new.can_view_reports is distinct from old.can_view_reports\n  )\n    and not public.is_admin(new.organization_id)\n  then\n    raise exception 'Only an administrator can change staff permissions.';\n  end if;\n\n  return new;\nend;\n$$","create trigger doctors_guard_permission_update\n  before update on public.doctors\n  for each row execute function public.guard_doctor_permission_update()","create or replace function public.is_report_viewer(p_organization_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.is_admin(p_organization_id) or (\n    public.is_doctor(p_organization_id) and exists (\n      select 1 from public.doctors d\n      where d.user_id = (select auth.uid())\n        and d.organization_id = p_organization_id\n        and d.can_view_reports\n        and d.deleted_at is null\n    )\n  );\n$$","revoke all on function public.is_report_viewer(uuid) from public, anon","grant execute on function public.is_report_viewer(uuid) to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- §8.1 — financial reports. \\"Revenue\\" means cash actually collected\n-- (payments, by paid_at); \\"revenue by service/doctor\\" means billed revenue\n-- (invoice_items, by the invoice's issued_at) — collected and billed are\n-- both standard, distinct figures, and billed is the only one that is even\n-- well-defined per line item.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.report_revenue_series(\n  p_organization_id uuid, p_from date, p_to date, p_granularity text default 'day'\n)\nreturns table (period_start date, revenue_paisa bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  if p_granularity not in ('day', 'week', 'month') then\n    raise exception 'Invalid granularity.';\n  end if;\n\n  return query\n  select date_trunc(p_granularity, p.paid_at)::date as period_start,\n         coalesce(sum(p.amount_paisa), 0)::bigint as revenue_paisa\n  from public.payments p\n  where p.organization_id = p_organization_id\n    and p.status = 'completed'\n    and p.paid_at::date between p_from and p_to\n  group by 1\n  order by 1;\nend;\n$$","create or replace function public.report_revenue_totals(p_organization_id uuid, p_from date, p_to date)\nreturns table (outstanding_paisa bigint, outstanding_count bigint, paid_paisa bigint, paid_count bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select\n    coalesce(sum(balance_paisa) filter (where status in ('issued', 'partially_paid')), 0)::bigint,\n    count(*) filter (where status in ('issued', 'partially_paid'))::bigint,\n    coalesce(sum(total_paisa) filter (where status = 'paid'), 0)::bigint,\n    count(*) filter (where status = 'paid')::bigint\n  from public.invoices\n  where organization_id = p_organization_id\n    and deleted_at is null\n    and issued_at::date between p_from and p_to;\nend;\n$$","create or replace function public.report_revenue_by_service(p_organization_id uuid, p_from date, p_to date)\nreturns table (service_name text, revenue_paisa bigint, quantity bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select ii.description as service_name,\n         sum(ii.line_total_paisa)::bigint as revenue_paisa,\n         sum(ii.quantity)::bigint as quantity\n  from public.invoice_items ii\n  join public.invoices i on i.id = ii.invoice_id\n  where i.organization_id = p_organization_id\n    and i.status not in ('draft', 'cancelled')\n    and i.issued_at::date between p_from and p_to\n  group by ii.description\n  order by revenue_paisa desc;\nend;\n$$","create or replace function public.report_revenue_by_doctor(p_organization_id uuid, p_from date, p_to date)\nreturns table (doctor_name text, revenue_paisa bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select coalesce(u.full_name, 'Unassigned') as doctor_name,\n         sum(i.total_paisa)::bigint as revenue_paisa\n  from public.invoices i\n  left join public.appointments a on a.id = i.appointment_id\n  left join public.doctors d on d.id = a.doctor_id\n  left join public.users u on u.id = d.user_id\n  where i.organization_id = p_organization_id\n    and i.status not in ('draft', 'cancelled')\n    and i.issued_at::date between p_from and p_to\n  group by coalesce(u.full_name, 'Unassigned')\n  order by revenue_paisa desc;\nend;\n$$","-- ---------------------------------------------------------------------------\n-- §8.2 — clinical reports. \\"Most common diagnoses\\" groups by the diagnosis's\n-- exact free text — that column has never been anything but the vet's own\n-- words (see soap_records.sql's own comment on it), so there is no code to\n-- group by without inventing a taxonomy the brief never asked for.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.report_clinical_summary(p_organization_id uuid, p_from date, p_to date)\nreturns table (consultations bigint, vaccinations bigint, dewormings bigint, follow_ups bigint, emergencies bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select\n    (select count(*) from public.appointments\n      where organization_id = p_organization_id and status = 'completed'\n        and starts_at::date between p_from and p_to)::bigint,\n    (select count(*) from public.vaccinations\n      where organization_id = p_organization_id and deleted_at is null\n        and date_administered between p_from and p_to)::bigint,\n    (select count(*) from public.deworming_records\n      where organization_id = p_organization_id and deleted_at is null\n        and date_administered between p_from and p_to)::bigint,\n    (select count(*) from public.appointments\n      where organization_id = p_organization_id and visit_type = 'follow_up'\n        and starts_at::date between p_from and p_to)::bigint,\n    (select count(*) from public.appointments\n      where organization_id = p_organization_id and visit_type = 'emergency'\n        and starts_at::date between p_from and p_to)::bigint;\nend;\n$$","create or replace function public.report_common_diagnoses(\n  p_organization_id uuid, p_from date, p_to date, p_limit integer default 10\n)\nreturns table (description text, occurrences bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select d.description, count(*)::bigint as occurrences\n  from public.diagnoses d\n  where d.organization_id = p_organization_id\n    and d.deleted_at is null\n    and d.created_at::date between p_from and p_to\n  group by d.description\n  order by occurrences desc, d.description\n  limit p_limit;\nend;\n$$","-- ---------------------------------------------------------------------------\n-- §8.3 — client reports. \\"New\\" / \\"returning\\" needs each client's first-ever\n-- appointment date, not just clients.created_at (signing up is not the same\n-- as ever actually visiting).\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.report_client_summary(p_organization_id uuid, p_from date, p_to date)\nreturns table (new_clients bigint, returning_clients bigint, active_clients bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  with first_visit as (\n    select client_id, min(starts_at::date) as first_date\n    from public.appointments\n    where organization_id = p_organization_id\n    group by client_id\n  ),\n  in_range as (\n    select distinct client_id\n    from public.appointments\n    where organization_id = p_organization_id\n      and starts_at::date between p_from and p_to\n  )\n  select\n    (select count(*) from first_visit fv join in_range ir on ir.client_id = fv.client_id\n      where fv.first_date between p_from and p_to)::bigint,\n    (select count(*) from first_visit fv join in_range ir on ir.client_id = fv.client_id\n      where fv.first_date < p_from)::bigint,\n    (select count(*) from in_range)::bigint;\nend;\n$$","-- ---------------------------------------------------------------------------\n-- §8.4 — patient reports.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.report_patient_species_breakdown(p_organization_id uuid, p_from date, p_to date)\nreturns table (species_name text, count bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select s.name as species_name, count(*)::bigint\n  from public.pets p\n  join public.species s on s.id = p.species_id\n  where p.organization_id = p_organization_id\n    and p.deleted_at is null\n    and p.created_at::date between p_from and p_to\n  group by s.name\n  order by count(*) desc;\nend;\n$$","create or replace function public.report_frequent_patients(\n  p_organization_id uuid, p_from date, p_to date, p_limit integer default 10\n)\nreturns table (pet_id uuid, pet_name text, visit_count bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select p.id, p.name, count(a.id)::bigint as visit_count\n  from public.appointments a\n  join public.pets p on p.id = a.pet_id\n  where a.organization_id = p_organization_id\n    and a.starts_at::date between p_from and p_to\n  group by p.id, p.name\n  order by visit_count desc\n  limit p_limit;\nend;\n$$","-- ---------------------------------------------------------------------------\n-- Privileges\n-- ---------------------------------------------------------------------------\n\nrevoke all on function public.report_revenue_series(uuid, date, date, text) from public, anon","revoke all on function public.report_revenue_totals(uuid, date, date) from public, anon","revoke all on function public.report_revenue_by_service(uuid, date, date) from public, anon","revoke all on function public.report_revenue_by_doctor(uuid, date, date) from public, anon","revoke all on function public.report_clinical_summary(uuid, date, date) from public, anon","revoke all on function public.report_common_diagnoses(uuid, date, date, integer) from public, anon","revoke all on function public.report_client_summary(uuid, date, date) from public, anon","revoke all on function public.report_patient_species_breakdown(uuid, date, date) from public, anon","revoke all on function public.report_frequent_patients(uuid, date, date, integer) from public, anon","grant execute on function public.report_revenue_series(uuid, date, date, text) to authenticated, service_role","grant execute on function public.report_revenue_totals(uuid, date, date) to authenticated, service_role","grant execute on function public.report_revenue_by_service(uuid, date, date) to authenticated, service_role","grant execute on function public.report_revenue_by_doctor(uuid, date, date) to authenticated, service_role","grant execute on function public.report_clinical_summary(uuid, date, date) to authenticated, service_role","grant execute on function public.report_common_diagnoses(uuid, date, date, integer) to authenticated, service_role","grant execute on function public.report_client_summary(uuid, date, date) to authenticated, service_role","grant execute on function public.report_patient_species_breakdown(uuid, date, date) to authenticated, service_role","grant execute on function public.report_frequent_patients(uuid, date, date, integer) to authenticated, service_role"}	reporting
20260829000100	{"-- Phase 9 · Checkpoint 1 — real delivery channels for the notifications the\n-- reminder engine has been scheduling since Phase 6.\n--\n-- Two ideas carry the whole migration:\n--\n--   1. Fan-out-per-channel. Every notify_*() trigger so far has inserted one\n--      row hardcoded to channel = 'in_app'. enqueue_notification() replaces\n--      that single insert: it looks at the recipient's preferences\n--      (get_enabled_channels) and inserts one independently-retryable row\n--      per enabled channel. The old partial unique index assumed one row\n--      per event and is widened to include channel.\n--   2. A safe default is not a fake success. sms/whatsapp ship with no real\n--      provider account (this session's explicit scope decision) — the\n--      logging provider (application layer, not this migration) always\n--      fails honestly with 'no provider configured', which is exactly what\n--      makes an admin's failed-notifications view meaningful rather than a\n--      list of things that silently never happened.\n\n-- ---------------------------------------------------------------------------\n-- notifications / notification_logs — widen for real dispatch\n-- ---------------------------------------------------------------------------\n\nalter table public.notifications\n  add column retry_count integer not null default 0,\n  add column next_retry_at timestamptz,\n  add column provider_message_id text,\n  add column failure_reason text","alter table public.notifications\n  drop constraint notifications_type_allowed","alter table public.notifications\n  add constraint notifications_type_allowed check (\n    type in (\n      'appointment_reminder', 'vaccination_reminder', 'deworming_reminder',\n      'follow_up_reminder', 'invoice_reminder', 'payment_confirmation',\n      'appointment_confirmation', 'prescription_available', 'invoice_issued'\n    )\n  )","alter table public.notification_logs\n  add column provider_message_id text","alter table public.notification_logs\n  drop constraint notification_logs_event_allowed","alter table public.notification_logs\n  add constraint notification_logs_event_allowed\n    check (event in ('scheduled', 'sent', 'delivered', 'failed', 'retrying'))","-- Was (related_table, related_id, type) — assumed exactly one channel per\n-- event. Now one scheduled row per channel is legitimate; only a re-save of\n-- the same channel should collapse onto its existing row.\ndrop index public.notifications_related_scheduled_key","create unique index notifications_related_scheduled_key\n  on public.notifications (related_table, related_id, type, channel)\n  where status = 'scheduled'","-- ---------------------------------------------------------------------------\n-- notification_templates — admin-editable content per (org, type, channel).\n-- Optional: the dispatcher falls back to the notification's own title/body\n-- when no active template exists, so delivery never depends on an admin\n-- having filled every combination in first.\n-- ---------------------------------------------------------------------------\n\ncreate table public.notification_templates (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  type text not null,\n  channel text not null,\n  subject_template text,\n  body_template text not null,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n\n  constraint notification_templates_type_allowed check (\n    type in (\n      'appointment_reminder', 'vaccination_reminder', 'deworming_reminder',\n      'follow_up_reminder', 'invoice_reminder', 'payment_confirmation',\n      'appointment_confirmation', 'prescription_available', 'invoice_issued'\n    )\n  ),\n  constraint notification_templates_channel_allowed\n    check (channel in ('email', 'sms', 'whatsapp', 'push')),\n  constraint notification_templates_body_not_blank\n    check (length(btrim(body_template)) > 0)\n)","create unique index notification_templates_org_type_channel_key\n  on public.notification_templates (organization_id, type, channel)","create trigger notification_templates_set_updated_at\n  before update on public.notification_templates\n  for each row execute function public.set_updated_at()","create trigger notification_templates_audit\n  after insert or update on public.notification_templates\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- notification_preferences — opt-out per (user, type, channel). Absence of a\n-- row means enabled: a brand-new client starts subscribed to everything.\n-- ---------------------------------------------------------------------------\n\ncreate table public.notification_preferences (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  type text not null,\n  channel text not null,\n  enabled boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n\n  constraint notification_preferences_type_allowed check (\n    type in (\n      'appointment_reminder', 'vaccination_reminder', 'deworming_reminder',\n      'follow_up_reminder', 'invoice_reminder', 'payment_confirmation',\n      'appointment_confirmation', 'prescription_available', 'invoice_issued'\n    )\n  ),\n  constraint notification_preferences_channel_allowed\n    check (channel in ('email', 'sms', 'whatsapp', 'push'))\n)","create unique index notification_preferences_user_type_channel_key\n  on public.notification_preferences (user_id, type, channel)","create trigger notification_preferences_set_updated_at\n  before update on public.notification_preferences\n  for each row execute function public.set_updated_at()","-- ---------------------------------------------------------------------------\n-- push_subscriptions — one row per browser/device a user has enabled push\n-- notifications on.\n-- ---------------------------------------------------------------------------\n\ncreate table public.push_subscriptions (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  endpoint text not null,\n  p256dh text not null,\n  auth text not null,\n  created_at timestamptz not null default now()\n)","create unique index push_subscriptions_user_endpoint_key\n  on public.push_subscriptions (user_id, endpoint)","-- ---------------------------------------------------------------------------\n-- organizations — quiet hours (§9.4's \\"practice-level defaults\\"). Null on\n-- either end means quiet hours are not configured; email is never deferred\n-- by them, only sms/whatsapp/push.\n-- ---------------------------------------------------------------------------\n\nalter table public.organizations\n  add column quiet_hours_start time,\n  add column quiet_hours_end time","grant update (quiet_hours_start, quiet_hours_end) on public.organizations to authenticated","-- ---------------------------------------------------------------------------\n-- get_enabled_channels / enqueue_notification — the fan-out helper every\n-- notify_*() trigger now goes through instead of a single hardcoded insert.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.get_enabled_channels(p_user_id uuid, p_type text)\nreturns text[]\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  -- The unnest alias is deliberately c(channel), not a bare \\"channel\\":\n  -- notification_preferences has its own channel column, and an unqualified\n  -- reference below would resolve to that instead of this correlated value\n  -- (silently comparing np.channel to itself and excluding every channel\n  -- whenever any one of them was disabled).\n  select array(\n    select c.channel\n    from unnest(array['email', 'sms', 'whatsapp', 'push']) as c(channel)\n    where not exists (\n      select 1\n      from public.notification_preferences np\n      where np.user_id = p_user_id\n        and np.type = p_type\n        and np.channel = c.channel\n        and np.enabled = false\n    )\n  );\n$$","revoke all on function public.get_enabled_channels(uuid, text) from public, anon","create or replace function public.enqueue_notification(\n  p_organization_id uuid,\n  p_recipient_user_id uuid,\n  p_type text,\n  p_title text,\n  p_body text,\n  p_related_table text,\n  p_related_id uuid,\n  p_scheduled_for timestamptz\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_channel text;\n  v_notification_id uuid;\nbegin\n  foreach v_channel in array public.get_enabled_channels(p_recipient_user_id, p_type)\n  loop\n    insert into public.notifications (\n      organization_id, recipient_user_id, type, channel, status,\n      title, body, related_table, related_id, scheduled_for\n    )\n    values (\n      p_organization_id, p_recipient_user_id, p_type, v_channel, 'scheduled',\n      p_title, p_body, p_related_table, p_related_id, p_scheduled_for\n    )\n    on conflict (related_table, related_id, type, channel) where status = 'scheduled'\n    do update set\n      title = excluded.title,\n      body = excluded.body,\n      scheduled_for = excluded.scheduled_for\n    returning id into v_notification_id;\n\n    insert into public.notification_logs (notification_id, event, detail)\n    values (v_notification_id, 'scheduled', p_title);\n  end loop;\nend;\n$$","revoke all on function public.enqueue_notification(\n  uuid, uuid, text, text, text, text, uuid, timestamptz\n) from public, anon","-- ---------------------------------------------------------------------------\n-- Widen the three existing reminder triggers to fan out through\n-- enqueue_notification() instead of a single hardcoded in_app insert.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.notify_due_reminder()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_recipient_user_id uuid;\n  v_notification_type text;\n  v_title text;\n  v_body text;\nbegin\n  if new.next_due_date is null then\n    return new;\n  end if;\n\n  select c.user_id\n    into v_recipient_user_id\n  from public.pets p\n  join public.clients c on c.id = p.client_id\n  where p.id = new.pet_id;\n\n  -- A walk-in client with no login yet has nothing to notify.\n  if v_recipient_user_id is null then\n    return new;\n  end if;\n\n  if tg_table_name = 'vaccinations' then\n    v_notification_type := 'vaccination_reminder';\n    v_title := 'Vaccination due: ' || new.vaccine_name;\n    v_body := 'Next due ' || to_char(new.next_due_date, 'DD Mon YYYY') || '.';\n  else\n    v_notification_type := 'deworming_reminder';\n    v_title := 'Deworming due: ' || new.product;\n    v_body := 'Next due ' || to_char(new.next_due_date, 'DD Mon YYYY') || '.';\n  end if;\n\n  perform public.enqueue_notification(\n    new.organization_id, v_recipient_user_id, v_notification_type,\n    v_title, v_body, tg_table_name, new.id, new.next_due_date - interval '7 days'\n  );\n\n  return new;\nend;\n$$","create or replace function public.notify_invoice_issued()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_recipient_user_id uuid;\n  v_amount_text text;\nbegin\n  select c.user_id into v_recipient_user_id\n  from public.clients c where c.id = new.client_id;\n\n  if v_recipient_user_id is null then\n    return new;\n  end if;\n\n  v_amount_text := (new.total_paisa / 100.0)::text;\n\n  -- The due-date reminder, unchanged from Phase 7.\n  perform public.enqueue_notification(\n    new.organization_id, v_recipient_user_id, 'invoice_reminder',\n    'Invoice ' || new.invoice_number,\n    'Amount due: ' || v_amount_text || ' BDT.',\n    'invoices', new.id, coalesce(new.due_date::timestamptz, now())\n  );\n\n  -- The immediate transactional notification Phase 9 adds.\n  perform public.enqueue_notification(\n    new.organization_id, v_recipient_user_id, 'invoice_issued',\n    'Invoice ' || new.invoice_number || ' issued',\n    'Your invoice for ' || v_amount_text || ' BDT is ready.',\n    'invoices', new.id, now()\n  );\n\n  return new;\nend;\n$$","create or replace function public.notify_payment_recorded()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_recipient_user_id uuid;\n  v_client_id uuid;\n  v_organization_id uuid;\nbegin\n  select client_id, organization_id into v_client_id, v_organization_id\n    from public.invoices where id = new.invoice_id;\n  select c.user_id into v_recipient_user_id from public.clients c where c.id = v_client_id;\n\n  if v_recipient_user_id is null then\n    return new;\n  end if;\n\n  perform public.enqueue_notification(\n    v_organization_id, v_recipient_user_id, 'payment_confirmation',\n    'Payment received',\n    'We received a payment of ' || (new.amount_paisa / 100.0)::text || ' BDT.',\n    'payments', new.id, now()\n  );\n\n  return new;\nend;\n$$","-- ---------------------------------------------------------------------------\n-- Two new transactional triggers.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.notify_appointment_confirmed()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_recipient_user_id uuid;\n  v_pet_name text;\nbegin\n  select c.user_id, p.name\n    into v_recipient_user_id, v_pet_name\n  from public.pets p\n  join public.clients c on c.id = p.client_id\n  where p.id = new.pet_id;\n\n  if v_recipient_user_id is null then\n    return new;\n  end if;\n\n  perform public.enqueue_notification(\n    new.organization_id, v_recipient_user_id, 'appointment_confirmation',\n    'Appointment confirmed',\n    'Your appointment for ' || coalesce(v_pet_name, 'your pet') || ' on '\n      || to_char(new.starts_at, 'DD Mon YYYY HH24:MI') || ' is confirmed.',\n    'appointments', new.id, now()\n  );\n\n  return new;\nend;\n$$","create trigger appointments_notify_confirmed\n  after update of status on public.appointments\n  for each row\n  when (old.status is distinct from new.status and new.status = 'confirmed')\n  execute function public.notify_appointment_confirmed()","create or replace function public.notify_prescription_finalized()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_recipient_user_id uuid;\nbegin\n  select c.user_id\n    into v_recipient_user_id\n  from public.pets p\n  join public.clients c on c.id = p.client_id\n  where p.id = new.pet_id;\n\n  if v_recipient_user_id is null then\n    return new;\n  end if;\n\n  perform public.enqueue_notification(\n    new.organization_id, v_recipient_user_id, 'prescription_available',\n    'Prescription available',\n    'A new prescription is available in your records.',\n    'prescriptions', new.id, now()\n  );\n\n  return new;\nend;\n$$","create trigger prescriptions_notify_finalized\n  after update of status on public.prescriptions\n  for each row\n  when (old.status is distinct from new.status and new.status = 'finalized')\n  execute function public.notify_prescription_finalized()","-- ---------------------------------------------------------------------------\n-- Row level security\n-- ---------------------------------------------------------------------------\n\nalter table public.notification_templates enable row level security","alter table public.notification_preferences enable row level security","alter table public.push_subscriptions enable row level security","create policy notification_templates_select on public.notification_templates\n  for select to authenticated\n  using (public.is_admin(organization_id))","create policy notification_templates_insert on public.notification_templates\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy notification_templates_update on public.notification_templates\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","create policy notification_preferences_select on public.notification_preferences\n  for select to authenticated\n  using (user_id = (select auth.uid()))","create policy notification_preferences_insert on public.notification_preferences\n  for insert to authenticated\n  with check (user_id = (select auth.uid()))","create policy notification_preferences_update on public.notification_preferences\n  for update to authenticated\n  using (user_id = (select auth.uid()))\n  with check (user_id = (select auth.uid()))","create policy push_subscriptions_select on public.push_subscriptions\n  for select to authenticated\n  using (user_id = (select auth.uid()))","create policy push_subscriptions_insert on public.push_subscriptions\n  for insert to authenticated\n  with check (user_id = (select auth.uid()))","create policy push_subscriptions_delete on public.push_subscriptions\n  for delete to authenticated\n  using (user_id = (select auth.uid()))","-- Notifications themselves are still only ever inserted by\n-- enqueue_notification() (security definer) — but an admin can now retry a\n-- failed send, resetting the same four columns the dispatcher itself\n-- manages. Every other column (title, body, type, channel, scheduled_for,\n-- ...) has no update grant below, so a retry can never rewrite content.\ncreate policy notifications_admin_retry on public.notifications\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","grant update (status, retry_count, next_retry_at, failure_reason) on public.notifications to authenticated","-- ---------------------------------------------------------------------------\n-- Privileges\n-- ---------------------------------------------------------------------------\n\nrevoke all on public.notification_templates, public.notification_preferences,\n  public.push_subscriptions from anon","grant select, insert, update on public.notification_templates to authenticated","grant select, insert, update on public.notification_preferences to authenticated","grant select, insert, delete on public.push_subscriptions to authenticated","-- The dispatcher (src/features/notifications/process.ts) runs under the\n-- service role, reading/writing across every recipient rather than as one\n-- signed-in user, so it needs its own grant here — the same pattern every\n-- earlier phase's migration follows for its own new tables.\ngrant all on public.notification_templates, public.notification_preferences,\n  public.push_subscriptions to service_role"}	notifications
20260830000100	{"-- Phase 10 · Checkpoint 1 — a real bug the new doctor-management screen\n-- surfaced immediately: can_view_user() required every branch's\n-- user_roles grant to be un-revoked, including the \\"clinic-side people see\n-- their org\\" branch. Deactivating a doctor (this phase's own\n-- deactivateDoctorAction, revoking their user_roles grant) made that\n-- person invisible to can_view_user() for everyone, including the admin\n-- who deactivated them — so \\"show deactivated doctors\\" showed no name,\n-- email or phone for exactly the doctor it was built to show. An admin\n-- managing their own organization's people needs to keep seeing someone\n-- after revoking their access, not lose the ability to.\n\ncreate or replace function public.can_view_user(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select\n    p_user_id = (select auth.uid())\n    or public.is_super_admin()\n    -- Clinic-side people see the people in their own organization.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and (\n          public.is_admin(ur.organization_id)\n          or public.is_doctor(ur.organization_id)\n        )\n    )\n    -- Anyone in the organization may see that organization's doctors, which\n    -- is what makes doctor selection possible at booking time.\n    or exists (\n      select 1\n      from public.user_roles ur\n      join public.roles r on r.id = ur.role_id\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and r.slug = 'doctor'\n        and public.is_org_member(ur.organization_id)\n    )\n    -- An admin keeps seeing someone they manage even after revoking their\n    -- access — deactivating a person must not also make them unmanageable.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and public.is_admin(ur.organization_id)\n    );\n$$","-- §10.5 index review: every foreign key on every table has a leading index\n-- except this one — invoices.appointment_id is filtered on directly by\n-- createInvoiceFromAppointmentAction and the invoice queries that check\n-- for an existing invoice per appointment.\ncreate index invoices_appointment_id_idx on public.invoices (appointment_id)"}	polish
20260920000100	{"-- Deleting a service or a category was never possible: neither table had a\n-- delete grant or a delete policy, only the soft \\"is_active\\" toggle. That is\n-- right for a service the practice has stopped offering — it must stay on the\n-- appointments and invoices that already reference it — but leaves no way to\n-- remove one that was added by mistake.\n--\n-- Safe to allow here because the foreign keys already decide what may go:\n--\n--   appointments.service_id      ON DELETE RESTRICT  — a booked service cannot\n--                                                     be deleted, by the\n--                                                     database, whatever the UI\n--                                                     offers.\n--   invoice_items.service_id     ON DELETE SET NULL  — an invoice line keeps its\n--                                                     own copied description and\n--                                                     price, so billing history\n--                                                     survives (CLAUDE.md §6).\n--   services.category_id         ON DELETE SET NULL  — deleting a category\n--                                                     unassigns its services\n--                                                     rather than removing them.\n--\n-- Admin only, matching every other write on these tables. The application\n-- checks the appointment count first so an admin gets a sentence rather than a\n-- constraint violation, but the constraint remains the real guarantee.\n\ncreate policy services_delete on public.services\n  for delete to authenticated\n  using ((select public.is_super_admin()) or organization_id in (select public.my_org_ids(array['admin'])))","create policy service_categories_delete on public.service_categories\n  for delete to authenticated\n  using ((select public.is_super_admin()) or organization_id in (select public.my_org_ids(array['admin'])))","grant delete on public.services, public.service_categories to authenticated"}	service_delete
20260921000100	{"-- Refunds.\n--\n-- invoices.status has allowed 'refunded' since 20260827000100_billing.sql and\n-- recalculate_invoice_totals already treats it as terminal, but nothing could\n-- ever set it: there was no way to give money back.\n--\n-- A refund is a new row, never an edit to the payment it reverses. payments is\n-- append-only in spirit and by constraint — amount_paisa > 0, no 'refunded'\n-- status — and a financial record that can be rewritten is not a record\n-- (CLAUDE.md §6). So what was taken and what was given back are both kept, each\n-- with who did it and why.\n\ncreate table public.refunds (\n  id uuid primary key default gen_random_uuid(),\n  -- Against a specific payment, not just the invoice: a client who paid twice\n  -- by two methods is refunded the way they paid, and \\"which card did this go\n  -- back to\\" has an answer.\n  payment_id uuid not null references public.payments (id) on delete restrict,\n  invoice_id uuid not null references public.invoices (id) on delete restrict,\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n\n  amount_paisa integer not null,\n  -- Usually the method the payment came in on, but not always: a bKash payment\n  -- may be refunded in cash across the counter.\n  method text not null,\n  -- Required, unlike a payment's optional note. Money going back out is\n  -- something an auditor will ask about.\n  reason text not null,\n  reference_number text,\n  refunded_at timestamptz not null default now(),\n  recorded_by uuid references public.users (id) on delete restrict,\n  created_at timestamptz not null default now(),\n\n  constraint refunds_amount_positive check (amount_paisa > 0),\n  constraint refunds_reason_not_blank check (length(btrim(reason)) > 0),\n  constraint refunds_method_allowed\n    check (method in ('cash', 'bank_transfer', 'bkash', 'nagad', 'card', 'other'))\n)","create index refunds_payment_id_idx on public.refunds (payment_id)","create index refunds_invoice_id_idx on public.refunds (invoice_id)","create index refunds_organization_id_refunded_at_idx on public.refunds (organization_id, refunded_at desc)","-- ---------------------------------------------------------------------------\n-- A payment can never be refunded for more than it was.\n--\n-- Enforced in a trigger rather than a check constraint because it spans rows:\n-- three partial refunds of one payment must add up to no more than the\n-- payment. Also pins the invoice and organization to the payment's own, so a\n-- refund cannot be filed against the wrong invoice.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.guard_refund_amount()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_payment record;\n  v_already integer;\nbegin\n  select p.amount_paisa, p.invoice_id, p.organization_id, p.status\n    into v_payment\n    from public.payments p\n   where p.id = new.payment_id;\n\n  if not found then\n    raise exception 'That payment could not be found.';\n  end if;\n\n  if v_payment.status <> 'completed' then\n    raise exception 'Only a completed payment can be refunded.';\n  end if;\n\n  if new.invoice_id <> v_payment.invoice_id or new.organization_id <> v_payment.organization_id then\n    raise exception 'A refund must belong to the same invoice and practice as its payment.';\n  end if;\n\n  select coalesce(sum(r.amount_paisa), 0)\n    into v_already\n    from public.refunds r\n   where r.payment_id = new.payment_id\n     and r.id <> new.id;\n\n  if v_already + new.amount_paisa > v_payment.amount_paisa then\n    raise exception 'A payment cannot be refunded for more than it was taken for.';\n  end if;\n\n  return new;\nend;\n$$","create trigger refunds_guard_amount\n  before insert or update on public.refunds\n  for each row execute function public.guard_refund_amount()","create trigger refunds_write_audit\n  after insert or update on public.refunds\n  for each row execute function public.write_audit_log()","-- ---------------------------------------------------------------------------\n-- Invoice totals now net refunds off what was collected.\n--\n-- Body copied from 20260827000100_billing.sql, with the paid figure becoming\n-- payments minus refunds and one new status branch: an invoice whose payments\n-- have all been given back reads 'refunded', which is what the status list has\n-- been waiting for.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.recalculate_invoice_totals()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare\n  v_invoice_id uuid;\n  v_subtotal integer;\n  v_tax integer;\n  v_discount integer;\n  v_total integer;\n  v_paid integer;\n  v_refunded integer;\nbegin\n  if tg_table_name = 'invoices' then\n    v_invoice_id := coalesce(new.id, old.id);\n  else\n    v_invoice_id := coalesce(new.invoice_id, old.invoice_id);\n  end if;\n\n  select coalesce(sum(line_total_paisa), 0),\n         coalesce(sum(round(line_total_paisa * tax_rate_percent / 100.0)), 0)\n    into v_subtotal, v_tax\n    from public.invoice_items\n   where invoice_id = v_invoice_id;\n\n  select discount_paisa into v_discount from public.invoices where id = v_invoice_id;\n  v_total := v_subtotal - coalesce(v_discount, 0) + v_tax;\n\n  select coalesce(sum(amount_paisa), 0) into v_paid\n    from public.payments\n   where invoice_id = v_invoice_id and status = 'completed';\n\n  select coalesce(sum(amount_paisa), 0) into v_refunded\n    from public.refunds\n   where invoice_id = v_invoice_id;\n\n  v_paid := v_paid - v_refunded;\n\n  update public.invoices\n     set subtotal_paisa = v_subtotal,\n         tax_paisa = v_tax,\n         total_paisa = v_total,\n         amount_paid_paisa = v_paid,\n         balance_paisa = v_total - v_paid,\n         status = case\n           when status = 'cancelled' then status\n           -- Everything collected has gone back out again.\n           when v_refunded > 0 and v_paid <= 0 then 'refunded'\n           when status = 'refunded' then status\n           when v_total > 0 and v_paid >= v_total then 'paid'\n           when v_paid > 0 and v_paid < v_total then 'partially_paid'\n           when status = 'partially_paid' and v_paid = 0 then 'issued'\n           else status\n         end\n   where id = v_invoice_id;\n\n  return coalesce(new, old);\nend;\n$$","create trigger refunds_recalculate_totals\n  after insert or update or delete on public.refunds\n  for each row execute function public.recalculate_invoice_totals()","-- ---------------------------------------------------------------------------\n-- Row level security.\n--\n-- Same readers and writers as payments: whoever may take money may give it\n-- back. No update or delete policy and no grant for either — a refund is\n-- corrected by recording the offsetting payment, not by editing history.\n-- ---------------------------------------------------------------------------\n\nalter table public.refunds enable row level security","create policy refunds_select on public.refunds\n  for select to authenticated\n  using (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id\n      and (\n        (select public.is_super_admin())\n        or i.organization_id in (select public.my_org_ids(array['admin', 'doctor']))\n        or (public.owns_client(i.client_id) and i.status <> 'draft')\n      )\n  ))","create policy refunds_select_finance on public.refunds\n  for select to authenticated\n  using (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id\n      and i.organization_id in (select public.my_org_ids(array['finance_manager']))\n  ))","create policy refunds_insert on public.refunds\n  for insert to authenticated\n  with check (public.is_billing_manager(organization_id))","create policy refunds_insert_finance on public.refunds\n  for insert to authenticated\n  with check (organization_id in (select public.my_org_ids(array['finance_manager'])))","grant select, insert on public.refunds to authenticated","grant all on public.refunds to service_role","-- ---------------------------------------------------------------------------\n-- Collected revenue is money the practice kept.\n--\n-- report_revenue_series is the only report that measures cash in; the others\n-- report what was billed, which a refund does not change. Body otherwise as it\n-- was in 20260919000100_rls_org_scope_cache.sql.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.report_revenue_series(\n  p_organization_id uuid, p_from date, p_to date, p_granularity text default 'day'\n)\nreturns table (period_start date, revenue_paisa bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_financial_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  if p_granularity not in ('day', 'week', 'month') then\n    raise exception 'Invalid granularity.';\n  end if;\n\n  return query\n  select bucket::date as period_start, sum(amount)::bigint as revenue_paisa\n  from (\n    select date_trunc(p_granularity, p.paid_at) as bucket, p.amount_paisa as amount\n    from public.payments p\n    where p.organization_id = p_organization_id\n      and p.status = 'completed'\n      and p.paid_at::date between p_from and p_to\n    union all\n    select date_trunc(p_granularity, r.refunded_at), -r.amount_paisa\n    from public.refunds r\n    where r.organization_id = p_organization_id\n      and r.refunded_at::date between p_from and p_to\n  ) as movements(bucket, amount)\n  group by bucket\n  order by bucket;\nend;\n$$"}	refunds
20260831000100	{"-- Public site expansion — a real contact inbox and an admin-uploadable\n-- hero image for the (newly added) public front page.\n\n-- ---------------------------------------------------------------------------\n-- contact_messages — the one table in this schema anonymous visitors can\n-- write to. Deliberately narrow and single-purpose rather than reusing\n-- anything broader, so that exception stays contained. No captcha or rate\n-- limiting yet — a known, accepted gap for a first cut, not an oversight.\n-- ---------------------------------------------------------------------------\n\ncreate table public.contact_messages (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  name text not null,\n  email extensions.citext not null,\n  phone text,\n  message text not null,\n  status text not null default 'new',\n  created_at timestamptz not null default now(),\n\n  constraint contact_messages_name_not_blank check (length(btrim(name)) > 0),\n  constraint contact_messages_message_not_blank check (length(btrim(message)) > 0),\n  constraint contact_messages_message_length check (length(message) <= 4000),\n  constraint contact_messages_status_allowed check (status in ('new', 'read'))\n)","create index contact_messages_organization_id_idx on public.contact_messages (organization_id)","create index contact_messages_status_idx on public.contact_messages (status)","alter table public.contact_messages enable row level security","-- A visitor submitting the form has no session at all — this is the only\n-- anon-role write in the whole schema.\ncreate policy contact_messages_insert on public.contact_messages\n  for insert to anon, authenticated\n  with check (true)","create policy contact_messages_select on public.contact_messages\n  for select to authenticated\n  using (public.is_admin(organization_id))","create policy contact_messages_update on public.contact_messages\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","revoke all on public.contact_messages from anon","grant insert on public.contact_messages to anon","grant select, insert, update on public.contact_messages to authenticated","grant all on public.contact_messages to service_role","-- ---------------------------------------------------------------------------\n-- organizations.hero_image_path — the front page's hero image, admin-\n-- uploaded. Null renders the existing icon-driven hero, so a fresh\n-- install still looks intentional before anyone uploads one.\n-- ---------------------------------------------------------------------------\n\nalter table public.organizations add column hero_image_path text","grant update (hero_image_path) on public.organizations to authenticated","-- ---------------------------------------------------------------------------\n-- site-images — the first PUBLIC bucket in this schema. Every other bucket\n-- is private with an RLS-scoped signed-URL read because it holds clinical\n-- or financial content; a marketing hero image is meant for anonymous\n-- visitors, so public:true is the deliberate, correct exception here.\n-- Public buckets serve objects over a plain URL, bypassing RLS entirely —\n-- an insert/update policy is still needed so only an admin can change it.\n-- ---------------------------------------------------------------------------\n\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues ('site-images', 'site-images', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])\non conflict (id) do nothing","create policy site_images_insert on storage.objects\n  for insert to authenticated\n  with check (bucket_id = 'site-images' and public.is_admin(null))","create policy site_images_update on storage.objects\n  for update to authenticated\n  using (bucket_id = 'site-images' and public.is_admin(null))\n  with check (bucket_id = 'site-images' and public.is_admin(null))"}	public_site
20260901000100	{"-- Doctor profile photos, admin-uploaded from /admin/doctors — the same\n-- \\"public bucket, deterministic URL, admin-only write\\" shape as the front\n-- page's hero image (20260831000100_public_site.sql), because a doctor's\n-- photo is meant to be visible on the public Doctors page too, not just\n-- inside the authenticated app (unlike doctor-signatures, which is private\n-- and only ever used server-side to render a prescription PDF).\n\nalter table public.doctors add column photo_path text","grant update (photo_path) on public.doctors to authenticated","insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues ('doctor-photos', 'doctor-photos', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])\non conflict (id) do nothing","-- Admin-only write, same reasoning as site_images_insert/update — public\n-- buckets bypass RLS entirely on read, so the insert/update policy is the\n-- only real gate on who can change what's shown.\ncreate policy doctor_photos_insert on storage.objects\n  for insert to authenticated\n  with check (bucket_id = 'doctor-photos' and public.is_admin(null))","create policy doctor_photos_update on storage.objects\n  for update to authenticated\n  using (bucket_id = 'doctor-photos' and public.is_admin(null))\n  with check (bucket_id = 'doctor-photos' and public.is_admin(null))"}	doctor_photos
20260902000100	{"-- Two small, unrelated additions bundled in one migration:\n--   1. organizations.whatsapp_number — admin-editable, same shape as every\n--      other contact field on Settings, backing the public site's WhatsApp\n--      button. Never hardcoded into a component.\n--   2. doctors.is_lead_doctor — an admin-only toggle (same guard-trigger\n--      shape as can_manage_billing/can_view_reports) marking which real,\n--      already-invited doctor is featured as the practice's lead/senior\n--      consultant on the public site. A name only ever comes from a real\n--      invited doctors row — this just flags one of them for display.\n\nalter table public.organizations add column whatsapp_number text","grant update (whatsapp_number) on public.organizations to authenticated","alter table public.doctors add column is_lead_doctor boolean not null default false","-- Reuses the existing guard trigger (widened in 20260828000100_reporting.sql\n-- to cover can_manage_billing + can_view_reports) so a doctor can never\n-- self-grant this either — same function, one more guarded column. Exact\n-- existing shape preserved, including the service-role bypass for test\n-- fixtures and admin scripts.\ngrant update (is_lead_doctor) on public.doctors to authenticated","create or replace function public.guard_doctor_permission_update()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if (select auth.uid()) is null then\n    return new; -- service role: test fixtures and admin scripts.\n  end if;\n\n  if (\n    new.can_manage_billing is distinct from old.can_manage_billing\n    or new.can_view_reports is distinct from old.can_view_reports\n    or new.is_lead_doctor is distinct from old.is_lead_doctor\n  )\n    and not public.is_admin(new.organization_id)\n  then\n    raise exception 'Only an administrator can change staff permissions.';\n  end if;\n\n  return new;\nend;\n$$","-- At most one lead doctor per organization, so the featured section always\n-- has an unambiguous single doctor to show.\ncreate unique index doctors_organization_id_lead_key\n  on public.doctors (organization_id)\n  where is_lead_doctor and deleted_at is null"}	whatsapp_lead_doctor
20260903000100	{"-- Admin-editable copy for the public marketing pages (home, about, services,\n-- contact). A generic key/value table rather than one column per string: new\n-- editable fields are added in application code (the field registry) without\n-- another migration, and an unset key simply falls back to its built-in\n-- default — the pages never render blank while a practice's content is\n-- incomplete.\n\ncreate table public.site_content (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  key text not null,\n  value text not null,\n  updated_at timestamptz not null default now(),\n  constraint site_content_value_not_blank check (length(btrim(value)) > 0),\n  constraint site_content_org_key_key unique (organization_id, key)\n)","create trigger site_content_set_updated_at\n  before update on public.site_content\n  for each row execute function public.set_updated_at()","alter table public.site_content enable row level security","-- Public pages read through the service role (same shape as\n-- getPublicOrganizationInfo), so the only policies needed here are for the\n-- admin editor.\ncreate policy site_content_select on public.site_content\n  for select to authenticated\n  using (public.is_admin(organization_id))","create policy site_content_insert on public.site_content\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy site_content_update on public.site_content\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","create policy site_content_delete on public.site_content\n  for delete to authenticated\n  using (public.is_admin(organization_id))"}	site_content
20260903000200	{"-- Every new table needs its own grants — the blanket \\"all tables to\n-- service_role\\" in 20260820000100_core_schema.sql only covered tables that\n-- existed at that time. Missed in 20260903000100_site_content.sql.\n\ngrant select, insert, update, delete on public.site_content to authenticated","grant all on public.site_content to service_role"}	site_content_grants
20260904000100	{"-- Fixes hero-image and doctor-photo uploads failing with \\"new row violates\n-- row level security policy\\" even for an admin whose insert clearly passes\n-- is_admin(null).\n--\n-- Storage API's upload endpoint always runs the insert as\n-- `INSERT ... RETURNING *` under the caller's own authenticated role, never\n-- the service role. Postgres RLS requires a SELECT policy to return that row\n-- from RETURNING, or the whole statement fails — even though the INSERT's\n-- own WITH CHECK succeeded. \\"Public buckets bypass RLS entirely on read\\"\n-- (20260831000100_public_site.sql, 20260901000100_doctor_photos.sql) is true\n-- for the anonymous /object/public/... endpoint, but not for this\n-- authenticated RETURNING, so site-images and doctor-photos were left\n-- without any SELECT policy and every upload/replace 403'd.\n--\n-- Scoped to admin, matching each bucket's insert/update policy — this does\n-- not widen public read access; anonymous visitors still read through the\n-- public endpoint, which bypasses RLS regardless.\n\ncreate policy site_images_select on storage.objects\n  for select to authenticated\n  using (bucket_id = 'site-images' and public.is_admin(null))","create policy doctor_photos_select on storage.objects\n  for select to authenticated\n  using (bucket_id = 'doctor-photos' and public.is_admin(null))"}	public_bucket_select_policies
20260905000100	{"-- Lets an admin see a registered account that has no role yet.\n--\n-- can_view_user() (20260820000200_rls_and_audit.sql) only grants visibility\n-- through an ACTIVE user_roles row — exactly the thing a person waiting to be\n-- granted a role does not have. The seed data's demo.staff account\n-- (staff row, no role) is invisible to the admin who is supposed to grant it\n-- one. Extending this to staff-table membership, admin-scoped, is what the\n-- new /admin/settings \\"Team & roles\\" section needs to list them at all.\n\ncreate or replace function public.can_view_user(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select\n    p_user_id = (select auth.uid())\n    or public.is_super_admin()\n    -- Clinic-side people see the people in their own organization.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and (\n          public.is_admin(ur.organization_id)\n          or public.is_doctor(ur.organization_id)\n        )\n    )\n    -- An admin can also see someone registered into their practice as staff\n    -- but not yet granted any role.\n    or exists (\n      select 1\n      from public.staff s\n      where s.user_id = p_user_id\n        and s.deleted_at is null\n        and public.is_admin(s.organization_id)\n    );\n$$"}	admin_visibility_for_staff
20260906000100	{"-- A practice logo, separate from the front page's hero image — shown in the\n-- site header everywhere, not just the Home page. Same site-images bucket\n-- and admin-only insert/update/select policies as hero_image_path\n-- (20260831000100_public_site.sql, 20260904000100_public_bucket_select_policies.sql)\n-- already cover it bucket-wide; only the path prefix differs.\n\nalter table public.organizations add column logo_path text","-- Column-level, same shape as every other admin-editable organizations\n-- column (hero_image_path, payment_instructions, ...) — see the \\"Column-level\n-- UPDATE privileges\\" section of 20260820000200_rls_and_audit.sql. Without\n-- this, the RLS policy passing is not enough: the base GRANT layer still\n-- denies the update outright.\ngrant update (logo_path) on public.organizations to authenticated"}	organization_logo
20260907000100	{"-- getRemovedTeamMembers (deleteTeamMemberAction's undo list) needs an\n-- admin to see the profile of someone whose staff row now has deleted_at\n-- set — can_view_user()'s staff clause (20260905000100_admin_visibility_for_staff.sql)\n-- required `s.deleted_at is null`, so the moment deleteTeamMemberAction ran,\n-- the removed person's name and email vanished from the very list meant to\n-- show them for restoring. Visibility here is already gated on\n-- is_admin(s.organization_id), so dropping the deleted_at check only extends\n-- that same admin-only, same-org visibility to former staff too.\n\ncreate or replace function public.can_view_user(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select\n    p_user_id = (select auth.uid())\n    or public.is_super_admin()\n    -- Clinic-side people see the people in their own organization.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and (\n          public.is_admin(ur.organization_id)\n          or public.is_doctor(ur.organization_id)\n        )\n    )\n    -- An admin can also see someone registered into their practice as staff,\n    -- whether currently active or previously removed.\n    or exists (\n      select 1\n      from public.staff s\n      where s.user_id = p_user_id\n        and public.is_admin(s.organization_id)\n    );\n$$"}	admin_visibility_for_removed_staff
20260908000100	{"-- Admin-created public pages, built from an ordered list of typed content\n-- blocks — the \\"new page\\" option in /admin/website, alongside the four\n-- fixed pages site_content already covers. Same tier as site_content: none\n-- of this is clinical, so unlike almost everything else in this schema it\n-- is fine to really delete rather than soft-delete (see\n-- 20260903000100_site_content.sql, the precedent this follows).\n\ncreate table public.site_pages (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  title text not null,\n  slug text not null,\n  show_in_nav boolean not null default true,\n  is_published boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint site_pages_title_not_blank check (length(btrim(title)) > 0),\n  -- Lowercase, hyphenated, url-safe — matches how the fixed pages' own\n  -- routes look (/about, /services). Reserved-word collisions with real\n  -- app routes (admin, login, api, ...) are rejected in application code,\n  -- where the list of reserved routes actually lives.\n  constraint site_pages_slug_format check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),\n  constraint site_pages_org_slug_key unique (organization_id, slug)\n)","create trigger site_pages_set_updated_at\n  before update on public.site_pages\n  for each row execute function public.set_updated_at()","-- Blocks belong entirely to their page — cascade is correct here (contrast\n-- with every `on delete restrict` elsewhere in this schema, all guarding\n-- clinical or financial rows): deleting a page's last reference to a block\n-- should not orphan it.\ncreate table public.site_page_blocks (\n  id uuid primary key default gen_random_uuid(),\n  page_id uuid not null references public.site_pages (id) on delete cascade,\n  position integer not null default 0,\n  block_type text not null,\n  -- Shape depends on block_type — validated in application code (Zod), one\n  -- schema per type, same reasoning as site_content's key/value looseness:\n  -- new block types are a code change, not a migration.\n  --   text:    { heading?: string, body: string }\n  --   image:   { path: string, alt?: string, caption?: string }\n  --   section: { heading: string, body?: string }\n  --   columns: { items: { heading?: string, body?: string }[] }\n  content jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint site_page_blocks_type_allowed check (block_type in ('text', 'image', 'section', 'columns'))\n)","create index site_page_blocks_page_id_position_idx on public.site_page_blocks (page_id, position)","create trigger site_page_blocks_set_updated_at\n  before update on public.site_page_blocks\n  for each row execute function public.set_updated_at()","alter table public.site_pages enable row level security","alter table public.site_page_blocks enable row level security","-- Public pages read through the service role (same shape as\n-- getPublicOrganizationInfo/getPublicSiteContent), so the only policies\n-- needed here are for the admin editor.\ncreate policy site_pages_select on public.site_pages\n  for select to authenticated\n  using (public.is_admin(organization_id))","create policy site_pages_insert on public.site_pages\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy site_pages_update on public.site_pages\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","create policy site_pages_delete on public.site_pages\n  for delete to authenticated\n  using (public.is_admin(organization_id))","create policy site_page_blocks_select on public.site_page_blocks\n  for select to authenticated\n  using (exists (select 1 from public.site_pages p where p.id = page_id and public.is_admin(p.organization_id)))","create policy site_page_blocks_insert on public.site_page_blocks\n  for insert to authenticated\n  with check (exists (select 1 from public.site_pages p where p.id = page_id and public.is_admin(p.organization_id)))","create policy site_page_blocks_update on public.site_page_blocks\n  for update to authenticated\n  using (exists (select 1 from public.site_pages p where p.id = page_id and public.is_admin(p.organization_id)))\n  with check (exists (select 1 from public.site_pages p where p.id = page_id and public.is_admin(p.organization_id)))","create policy site_page_blocks_delete on public.site_page_blocks\n  for delete to authenticated\n  using (exists (select 1 from public.site_pages p where p.id = page_id and public.is_admin(p.organization_id)))","-- Grants in the same migration this time — 20260903000200_site_content_grants.sql\n-- exists only because this step was missed for site_content and needed a\n-- follow-up migration to fix.\ngrant select, insert, update, delete on public.site_pages, public.site_page_blocks to authenticated","grant all on public.site_pages, public.site_page_blocks to service_role"}	site_pages
20260909000100	{"-- Regression fix — can_view_user() has been rewritten from scratch three\n-- times (20260830000100_polish.sql, 20260905000100_admin_visibility_for_staff.sql,\n-- 20260907000100_admin_visibility_for_removed_staff.sql), each time adding\n-- one new visibility case. The last two rewrites were based on an earlier\n-- version of the function and silently dropped clauses a prior migration had\n-- already added, rather than extending the then-current definition:\n--\n--   * 20260905000100 based itself on the ORIGINAL (20260820000200) function,\n--     losing 20260830000100's \\"an admin keeps seeing someone after revoking\n--     their access\\" clause.\n--   * The same rewrite also dropped the original's \\"anyone in the\n--     organization may see that organization's doctors\\" clause — the thing\n--     tests/rls.test.ts's \\"can see the doctors of their organization, which\n--     booking depends on\\" checks, and what doctor selection at booking time\n--     depends on.\n--   * 20260907000100 built on top of 20260905000100, so it never restored\n--     either loss.\n--\n-- This redefinition is the union of every clause any prior migration has\n-- ever added, so a future addition should extend this one rather than\n-- reinvent it from an older copy.\ncreate or replace function public.can_view_user(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select\n    p_user_id = (select auth.uid())\n    or public.is_super_admin()\n    -- Clinic-side people see the people in their own organization.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and (\n          public.is_admin(ur.organization_id)\n          or public.is_doctor(ur.organization_id)\n        )\n    )\n    -- Anyone in the organization may see that organization's doctors, which\n    -- is what makes doctor selection possible at booking time.\n    or exists (\n      select 1\n      from public.user_roles ur\n      join public.roles r on r.id = ur.role_id\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and r.slug = 'doctor'\n        and public.is_org_member(ur.organization_id)\n    )\n    -- An admin keeps seeing someone they manage even after revoking their\n    -- access — deactivating a person must not also make them unmanageable.\n    -- Deliberately not filtered on ur.revoked_at.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and public.is_admin(ur.organization_id)\n    )\n    -- An admin can also see someone registered into their practice as staff,\n    -- whether currently active or previously removed.\n    or exists (\n      select 1\n      from public.staff s\n      where s.user_id = p_user_id\n        and public.is_admin(s.organization_id)\n    );\n$$"}	can_view_user_regression_fix
20260910000100	{"-- Personal account photo, self-service for every role (client, doctor,\n-- admin, staff) and settable by an admin on behalf of someone they\n-- administer — distinct from doctors.photo_path (20260901000100), which\n-- stays the admin-only, public-facing professional photo shown on the\n-- public Doctors page. This one is just \\"what shows next to your name\n-- inside the app\\".\n--\n-- users.avatar_url already exists (20260820000100_core_schema.sql) and is\n-- already authenticated-writable (20260820000200_rls_and_audit.sql grants\n-- update on full_name, phone, avatar_url; users_update's RLS lets a person\n-- write their own row, or an admin write someone they administer via\n-- is_admin_of_user). This migration only adds the bucket that column's\n-- value points into.\n--\n-- Same \\"public bucket, deterministic URL\\" shape as doctor-photos, but\n-- object-owner-scoped rather than admin-only: the first path segment is the\n-- target person's user id, and insert/update is allowed when the caller\n-- either owns that id or is an admin of it.\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues ('avatars', 'avatars', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])\non conflict (id) do nothing","create policy avatars_insert on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'avatars'\n    and (\n      (storage.foldername(name))[1] = (select auth.uid())::text\n      or public.is_admin_of_user(((storage.foldername(name))[1])::uuid)\n    )\n  )","create policy avatars_update on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = 'avatars'\n    and (\n      (storage.foldername(name))[1] = (select auth.uid())::text\n      or public.is_admin_of_user(((storage.foldername(name))[1])::uuid)\n    )\n  )\n  with check (\n    bucket_id = 'avatars'\n    and (\n      (storage.foldername(name))[1] = (select auth.uid())::text\n      or public.is_admin_of_user(((storage.foldername(name))[1])::uuid)\n    )\n  )","-- Required for the upload endpoint's own `INSERT ... RETURNING *` to succeed\n-- under the caller's authenticated role — see 20260904000100's comment for\n-- why a public bucket still needs this despite bypassing RLS on public read.\ncreate policy avatars_select on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = 'avatars'\n    and (\n      (storage.foldername(name))[1] = (select auth.uid())::text\n      or public.is_admin_of_user(((storage.foldername(name))[1])::uuid)\n    )\n  )"}	avatars
20260911000100	{"-- The front page hero renders as a carousel (HeroCarousel), but until now\n-- Settings only let an admin upload one image — the rest of the slides were\n-- always filled in from doctor photos. This gives the admin a proper,\n-- ordered gallery of their own to slide through instead.\n--\n-- organizations.hero_image_path (20260831000100_public_site.sql) is left in\n-- place, unread from here on — its existing value (if any) is copied below\n-- so no upload is lost, and the column itself is not dropped (rule: never\n-- destroy existing data on a schema change).\n\ncreate table public.organization_hero_images (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  -- Unique per upload (organizations/hero-images.ts derives it from a fresh\n  -- uuid), unlike hero_image_path's fixed, overwritten-in-place name — so,\n  -- unlike the logo and old single hero image, these never need a cache-\n  -- busting query param.\n  image_path text not null,\n  position integer not null default 0,\n  created_at timestamptz not null default now()\n)","create index organization_hero_images_org_position_idx\n  on public.organization_hero_images (organization_id, position)","insert into public.organization_hero_images (organization_id, image_path, position)\nselect id, hero_image_path, 0\nfrom public.organizations\nwhere hero_image_path is not null","alter table public.organization_hero_images enable row level security","create policy organization_hero_images_select on public.organization_hero_images\n  for select to authenticated\n  using (public.is_admin(organization_id))","create policy organization_hero_images_insert on public.organization_hero_images\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy organization_hero_images_delete on public.organization_hero_images\n  for delete to authenticated\n  using (public.is_admin(organization_id))","grant select, insert, delete on public.organization_hero_images to authenticated","grant all on public.organization_hero_images to service_role","-- ---------------------------------------------------------------------------\n-- site-images never needed a DELETE policy before this — every existing use\n-- (hero, logo, page-block images) is a fixed path, upsert-overwritten in\n-- place. A gallery an admin can remove entries from is the first thing in\n-- this bucket that actually deletes an object.\n-- ---------------------------------------------------------------------------\n\ncreate policy site_images_delete on storage.objects\n  for delete to authenticated\n  using (bucket_id = 'site-images' and public.is_admin(null))"}	hero_gallery
20260912000100	{"-- Each hero gallery slide (20260911000100_hero_gallery.sql) can now carry a\n-- short caption an admin writes for it — shown over the image in the public\n-- carousel. Nullable: a slide with no caption just shows the image, same as\n-- before this migration existed.\n\nalter table public.organization_hero_images add column caption text","alter table public.organization_hero_images\n  add constraint organization_hero_images_caption_length check (char_length(caption) <= 160)","-- The gallery only ever needed insert/delete until now (every prior edit\n-- replaced a whole row via upload); editing a caption in place is the first\n-- update to one of these rows.\ncreate policy organization_hero_images_update on public.organization_hero_images\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","grant update on public.organization_hero_images to authenticated"}	hero_image_captions
20260913000100	{"-- The public site's navigation (header, mobile menu, footer links) has been\n-- one hardcoded array (PUBLIC_NAV_LINKS) shared by all three, with no way\n-- for an admin to reorder it or add a dropdown. This gives it a real,\n-- admin-managed home: a two-level tree (top-level items, each optionally\n-- holding dropdown children) an admin builds by dragging.\n--\n-- Two levels only, enforced two ways: the admin UI never offers a third\n-- level, and the trigger below rejects one anyway, so a direct write (a\n-- script, a future bug) can't quietly create a menu the UI can't render.\n\ncreate table public.nav_menu_items (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  -- Children belong entirely to their parent — cascade here, same reasoning\n  -- as site_page_blocks -> site_pages, contrasted with organization_id's\n  -- on delete restrict (this is still a top-level organization-owned row).\n  parent_id uuid references public.nav_menu_items (id) on delete cascade,\n  label text not null,\n  -- A plain string, not a \\"target type\\" enum — \\"/about\\" (a fixed page),\n  -- \\"/our-clinic\\" (a published site_pages slug) and \\"https://wa.me/...\\"\n  -- (an external link) are all just hrefs. The admin UI offers known\n  -- internal targets as suggestions but always allows free text.\n  href text not null,\n  position integer not null default 0,\n  is_visible boolean not null default true,\n  opens_new_tab boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint nav_menu_items_label_not_blank check (length(btrim(label)) > 0),\n  constraint nav_menu_items_href_not_blank check (length(btrim(href)) > 0)\n)","create index nav_menu_items_org_parent_position_idx\n  on public.nav_menu_items (organization_id, parent_id, position)","create trigger nav_menu_items_set_updated_at\n  before update on public.nav_menu_items\n  for each row execute function public.set_updated_at()","create or replace function public.nav_menu_items_enforce_depth()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  parent_of_parent uuid;\nbegin\n  if new.parent_id is not null then\n    select parent_id into parent_of_parent from public.nav_menu_items where id = new.parent_id;\n    if parent_of_parent is not null then\n      raise exception 'nav_menu_items only supports two levels — % is already a child item', new.parent_id;\n    end if;\n  end if;\n  return new;\nend;\n$$","create trigger nav_menu_items_enforce_depth_trigger\n  before insert or update on public.nav_menu_items\n  for each row execute function public.nav_menu_items_enforce_depth()","alter table public.nav_menu_items enable row level security","create policy nav_menu_items_select on public.nav_menu_items\n  for select to authenticated\n  using (public.is_admin(organization_id))","create policy nav_menu_items_insert on public.nav_menu_items\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy nav_menu_items_update on public.nav_menu_items\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","create policy nav_menu_items_delete on public.nav_menu_items\n  for delete to authenticated\n  using (public.is_admin(organization_id))","grant select, insert, update, delete on public.nav_menu_items to authenticated","grant all on public.nav_menu_items to service_role","-- A drag settles as one full new arrangement, not one pairwise swap — this\n-- rewrites every row's parent_id/position from the submitted tree in one\n-- statement, so a request failing partway through can't leave the tree\n-- half-reparented (plain sequential .update() calls from the app would not\n-- be wrapped in one transaction). Not security definer: it checks\n-- is_admin() itself and runs as the calling (already-authenticated) user,\n-- the same trust boundary as every RLS policy above.\ncreate or replace function public.reorder_nav_menu_items(p_organization_id uuid, p_tree jsonb)\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n  top_item jsonb;\n  child_item jsonb;\n  top_position integer := 0;\n  child_position integer;\nbegin\n  if not public.is_admin(p_organization_id) then\n    raise exception 'not authorized';\n  end if;\n\n  for top_item in select * from jsonb_array_elements(p_tree)\n  loop\n    update public.nav_menu_items\n    set parent_id = null, position = top_position\n    where id = (top_item ->> 'id')::uuid and organization_id = p_organization_id;\n\n    child_position := 0;\n    for child_item in select * from jsonb_array_elements(coalesce(top_item -> 'children', '[]'::jsonb))\n    loop\n      update public.nav_menu_items\n      set parent_id = (top_item ->> 'id')::uuid, position = child_position\n      where id = (child_item ->> 'id')::uuid and organization_id = p_organization_id;\n\n      child_position := child_position + 1;\n    end loop;\n\n    top_position := top_position + 1;\n  end loop;\nend;\n$$","grant execute on function public.reorder_nav_menu_items(uuid, jsonb) to authenticated","-- Seed every existing organization with today's hardcoded PUBLIC_NAV_LINKS\n-- (src/components/marketing/nav-links.ts) as top-level items, so nothing\n-- changes visually until an admin edits the menu. No organization-creation\n-- flow exists yet (multi-org is architecture-only per CLAUDE.md), so this\n-- one-time seed covers every real deployment; a future signup/onboarding\n-- flow that creates organizations must seed this table too.\ninsert into public.nav_menu_items (organization_id, label, href, position)\nselect o.id, link.label, link.href, link.position\nfrom public.organizations o\ncross join (values\n  ('Home', '/', 0),\n  ('About Us', '/about', 1),\n  ('Services', '/services', 2),\n  ('Doctors', '/doctors', 3),\n  ('Contact Us', '/contact', 4)\n) as link(label, href, position)"}	nav_menu_items
20260914000100	{"-- The home page's \\"What we offer\\", \\"Why pet owners choose\\" and \\"How it\n-- works\\" sections were hardcoded icon+title+description rows in\n-- front-page.tsx. One admin-editable, drag-reorderable list per section —\n-- three separate lists, not one shared with the site_pages block editor:\n-- these are homogeneous \\"feature item\\" repeaters interleaved with live\n-- doctor data (lead doctor spotlight, team gallery) that stays code-\n-- rendered, not a freeform page of mixed block types like a custom page.\n\ncreate table public.home_section_items (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete restrict,\n  section text not null check (section in ('services', 'why', 'how_it_works')),\n  position integer not null default 0,\n  -- Null for how_it_works, which shows its position as a step number\n  -- instead — see src/lib/icons.ts for the allowed keys (a curated list,\n  -- not free text, so a typo can't silently render nothing).\n  icon text,\n  title text not null,\n  description text not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint home_section_items_title_not_blank check (length(btrim(title)) > 0),\n  constraint home_section_items_description_not_blank check (length(btrim(description)) > 0)\n)","create index home_section_items_org_section_position_idx\n  on public.home_section_items (organization_id, section, position)","create trigger home_section_items_set_updated_at\n  before update on public.home_section_items\n  for each row execute function public.set_updated_at()","alter table public.home_section_items enable row level security","create policy home_section_items_select on public.home_section_items\n  for select to authenticated\n  using (public.is_admin(organization_id))","create policy home_section_items_insert on public.home_section_items\n  for insert to authenticated\n  with check (public.is_admin(organization_id))","create policy home_section_items_update on public.home_section_items\n  for update to authenticated\n  using (public.is_admin(organization_id))\n  with check (public.is_admin(organization_id))","create policy home_section_items_delete on public.home_section_items\n  for delete to authenticated\n  using (public.is_admin(organization_id))","grant select, insert, update, delete on public.home_section_items to authenticated","grant all on public.home_section_items to service_role","-- Seed every existing organization with today's hardcoded SERVICES / WHY /\n-- STEPS arrays (src/components/marketing/front-page.tsx), so nothing\n-- changes visually until an admin edits. No organization-creation flow\n-- exists yet (see 20260913000100_nav_menu_items.sql's own seed comment for\n-- why a one-time seed is sufficient) — a future signup/onboarding flow that\n-- creates organizations must seed this table too.\ninsert into public.home_section_items (organization_id, section, position, icon, title, description)\nselect o.id, item.section, item.position, item.icon, item.title, item.description\nfrom public.organizations o\ncross join (values\n  ('services', 0, 'stethoscope', 'Clinic visits', 'Book a consultation at the practice with the doctor of your choice.'),\n  ('services', 1, 'home', 'Home visits', 'Prefer your pet stay comfortable at home? We come to you.'),\n  ('services', 2, 'syringe', 'Vaccinations & deworming', 'Every dose recorded, with the next one scheduled automatically.'),\n  ('services', 3, 'file-text', 'Digital prescriptions', 'Clear, dosed prescriptions you can find again whenever you need them.'),\n  ('why', 0, 'paw-print', 'One record, always up to date', 'Every visit, vaccination and prescription for your pet lives in one place, not a stack of paper.'),\n  ('why', 1, 'bell', 'Reminders that keep up', 'Vaccination and deworming due dates are tracked for you, and a reminder goes out before they''re due.'),\n  ('why', 2, 'receipt', 'Transparent billing', 'Itemized invoices with clear totals, and a record of every payment against them.'),\n  ('why', 3, 'shield-check', 'Built for your privacy', 'Role-based access means your pet''s records are visible only to you and your care team.'),\n  ('how_it_works', 0, null, 'Create an account', 'Sign up and add your pet''s basic details.'),\n  ('how_it_works', 1, null, 'Book an appointment', 'Choose a doctor, a time, and clinic or home visit.'),\n  ('how_it_works', 2, null, 'Get the full picture', 'SOAP notes, prescriptions and invoices, all in your account afterward.')\n) as item(section, position, icon, title, description)"}	home_section_items
20260915000100	{"-- The footer always rendered a hardcoded \\"TV\\" badge and hardcoded\n-- copyright line, even though the real logo (organizations.logo_path) was\n-- already available. One dedicated column for the one boolean setting the\n-- footer needs — same shape as logo_path itself (20260906000100_organization_logo.sql),\n-- a single admin-editable organization-level setting, not the site_content\n-- KV table's shape (that assumes every value is display text with a text\n-- default; a toggle doesn't fit it). Tagline and copyright-line overrides\n-- are plain text, so those are new src/features/site-content/fields.ts\n-- registry entries instead — no migration needed for those.\n\nalter table public.organizations add column footer_show_logo boolean not null default true","grant update (footer_show_logo) on public.organizations to authenticated"}	footer_content
20260916000100	{"-- Generalizes home_section_items into page_section_items: the same\n-- drag-reorderable \\"feature item\\" repeater the home page has, now available\n-- to the other fixed marketing pages (About, Services, Contact), and with an\n-- optional image per item alongside the icon.\n--\n-- Why widen the existing table rather than add a new one: the three home\n-- lists and the new ones are the same thing — a position-ordered list of\n-- title/description cards rendered into a code-owned slot on a page. What\n-- changes is only *which* slot, so `page` is a new dimension of the existing\n-- key, not a new entity. Custom /[slug] pages keep their own freeform block\n-- builder (site_page_blocks); this table is for the fixed pages' slots.\n--\n-- Rename, not drop-and-recreate: every existing row, and every admin edit\n-- made through /admin/website/home-sections so far, survives untouched.\n\nalter table public.home_section_items rename to page_section_items","-- Existing rows are all home-page rows by definition — the default backfills\n-- them before the column is made non-null.\nalter table public.page_section_items\n  add column page text not null default 'home'","alter table public.page_section_items\n  add constraint page_section_items_page_allowed\n  check (page in ('home', 'about', 'services', 'contact'))","-- Path into the shared site-images bucket, same as hero slides and page\n-- block images. Null means \\"no picture\\" — the card renders with its icon (or\n-- step number) alone, exactly as every existing row does today.\nalter table public.page_section_items\n  add column image_path text","-- Section keys are namespaced per page, so 'services' as a *home* slot (\\"What\n-- we offer\\") never collides with the Services page's own slot. Which keys are\n-- valid for which page is enforced in application code (the registry in\n-- src/features/page-sections/sections.ts), the same split site_page_blocks\n-- already uses for block content: the shape lives in Zod, the coarse allowlist\n-- lives here so a typo can never reach a row.\nalter table public.page_section_items\n  drop constraint home_section_items_section_check","alter table public.page_section_items\n  add constraint page_section_items_section_allowed\n  check (section in ('services', 'why', 'how_it_works', 'values', 'highlights', 'points'))","alter table public.page_section_items\n  rename constraint home_section_items_title_not_blank to page_section_items_title_not_blank","alter table public.page_section_items\n  rename constraint home_section_items_description_not_blank to page_section_items_description_not_blank","alter table public.page_section_items\n  rename constraint home_section_items_pkey to page_section_items_pkey","alter table public.page_section_items\n  rename constraint home_section_items_organization_id_fkey to page_section_items_organization_id_fkey","-- Every read is now scoped by page before section, so the old\n-- (organization_id, section, position) index no longer matches the lookup.\ndrop index public.home_section_items_org_section_position_idx","create index page_section_items_org_page_section_position_idx\n  on public.page_section_items (organization_id, page, section, position)","alter trigger home_section_items_set_updated_at on public.page_section_items\n  rename to page_section_items_set_updated_at","alter policy home_section_items_select on public.page_section_items rename to page_section_items_select","alter policy home_section_items_insert on public.page_section_items rename to page_section_items_insert","alter policy home_section_items_update on public.page_section_items rename to page_section_items_update","alter policy home_section_items_delete on public.page_section_items rename to page_section_items_delete","-- Grants follow the table through a rename, so nothing to re-issue here.\n\n-- Seed the About page's \\"What we stand for\\" cards with the three that were\n-- hardcoded in src/app/about/page.tsx, so the page looks identical until an\n-- admin edits it — same approach 20260914000100 took for the home page.\n--\n-- Services and Contact get no seed on purpose: nothing was hardcoded on those\n-- pages to preserve, and inventing marketing copy in a migration would put\n-- words the practice never wrote onto its public site. Their sections start\n-- empty and simply do not render until an admin adds an item.\ninsert into public.page_section_items (organization_id, page, section, position, icon, title, description)\nselect o.id, 'about', 'values', item.position, item.icon, item.title, item.description\nfrom public.organizations o\ncross join (values\n  (0, 'stethoscope', 'Veterinarian-led care', 'Every diagnosis, prescription and treatment plan is made by the attending veterinarian — never automated.'),\n  (1, 'map-pin', 'Wherever your pet is comfortable', 'A consultation at the practice, or a visit at home — the same doctors, the same standard of care.'),\n  (2, 'heart', 'A record that stays with you', 'Every visit, vaccination and prescription is kept in one place, so nothing is lost between appointments.')\n) as item(position, icon, title, description)","-- ---------------------------------------------------------------------------\n-- The custom-page block builder gains the same card repeater, so a new\n-- /[slug] page can build what the fixed pages' sections look like. Its items\n-- live in the block's jsonb (validated by Zod, like every other block type):\n--   cards: { items: { icon?: string, heading: string, body?: string, path?: string }[] }\nalter table public.site_page_blocks\n  drop constraint site_page_blocks_type_allowed","alter table public.site_page_blocks\n  add constraint site_page_blocks_type_allowed\n  check (block_type in ('text', 'image', 'section', 'columns', 'cards'))"}	page_sections
20260917000100	{"-- Three narrower clinic-side roles alongside admin: a finance manager who\n-- handles money, a lab user who handles tests and their results, and a\n-- receptionist who runs the front desk.\n--\n-- Additive by construction. Every existing policy is left exactly as it is —\n-- there are 142 is_admin(...) references across this migration set, and\n-- rewriting them to accommodate three new roles would put all of an admin's\n-- access at risk to add someone else's. Postgres OR's permissive policies for\n-- the same command together, so a *new* policy widens access to a table\n-- without touching what admins, doctors and clients can already do. Nothing\n-- below narrows anything.\n--\n-- These roles are deliberately not admins with a smaller menu: what each can\n-- reach is enforced here, in row level security, so hiding a nav item is only\n-- ever a convenience, never the boundary (see src/features/auth/session.ts).\n\nalter table public.roles\n  drop constraint roles_slug_allowed","alter table public.roles\n  add constraint roles_slug_allowed\n  check (slug in ('client', 'doctor', 'admin', 'super_admin', 'finance_manager', 'lab', 'receptionist'))","insert into public.roles (slug, name, description, is_assignable_in_ui)\nvalues\n  ('finance_manager', 'Finance Manager',\n   'Invoices, payments and financial reporting. No clinical records.', true),\n  ('lab', 'Lab',\n   'Diagnostic tests and their results. Reads the patient identity a test belongs to, nothing more.', true),\n  ('receptionist', 'Receptionist',\n   'Front desk: appointments, services, doctor information, vaccination schedules, notifications and messages.', true)\non conflict (slug) do nothing","-- ---------------------------------------------------------------------------\n-- Role predicates, matching the shape of is_admin / is_doctor in\n-- 20260820000200_rls_and_audit.sql: security definer, search_path pinned to ''\n-- so a caller cannot shadow a table name and change what they resolve to.\n--\n-- Unlike is_admin, none of these fall back to super_admin: super_admin already\n-- satisfies is_admin everywhere, so it reaches all of this through the\n-- existing policies and does not need a second door.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.is_finance_manager(p_organization_id uuid default null)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.has_role('finance_manager', p_organization_id);\n$$","create or replace function public.is_lab(p_organization_id uuid default null)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.has_role('lab', p_organization_id);\n$$","create or replace function public.is_receptionist(p_organization_id uuid default null)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.has_role('receptionist', p_organization_id);\n$$","-- True for any of the three, used only where all three legitimately need the\n-- same row — the patient and owner identity behind an invoice, a test or an\n-- appointment. Never used to grant a clinical or financial write.\ncreate or replace function public.is_support_staff(p_organization_id uuid default null)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select\n    public.has_role('finance_manager', p_organization_id)\n    or public.has_role('lab', p_organization_id)\n    or public.has_role('receptionist', p_organization_id);\n$$","revoke all on function public.is_finance_manager(uuid) from public, anon","revoke all on function public.is_lab(uuid) from public, anon","revoke all on function public.is_receptionist(uuid) from public, anon","revoke all on function public.is_support_staff(uuid) from public, anon","grant execute on function public.is_finance_manager(uuid) to authenticated, service_role","grant execute on function public.is_lab(uuid) to authenticated, service_role","grant execute on function public.is_receptionist(uuid) to authenticated, service_role","grant execute on function public.is_support_staff(uuid) to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- Shared context: who the patient and owner are.\n--\n-- All three roles need to know whose invoice, test or appointment they are\n-- looking at, or the screens show opaque identifiers. Read only, and only\n-- within their own organization — no role here can create or alter a client,\n-- a pet or a person's profile.\n-- ---------------------------------------------------------------------------\n\ncreate policy clients_select_support_staff on public.clients\n  for select to authenticated\n  using (public.is_support_staff(organization_id))","create policy pets_select_support_staff on public.pets\n  for select to authenticated\n  using (public.is_support_staff(organization_id))","create policy species_select_support_staff on public.species\n  for select to authenticated\n  using (public.is_support_staff())","create policy breeds_select_support_staff on public.breeds\n  for select to authenticated\n  using (public.is_support_staff())","-- ---------------------------------------------------------------------------\n-- Finance Manager — invoices, invoice lines, payments.\n--\n-- Write access to money, none to clinical records. Deleting is not granted to\n-- anyone in this schema and is not granted here either: a wrong invoice is\n-- corrected by a credit or a revision, never by erasing the history.\n-- ---------------------------------------------------------------------------\n\ncreate policy invoices_select_finance on public.invoices\n  for select to authenticated\n  using (public.is_finance_manager(organization_id))","create policy invoices_insert_finance on public.invoices\n  for insert to authenticated\n  with check (public.is_finance_manager(organization_id))","create policy invoices_update_finance on public.invoices\n  for update to authenticated\n  using (public.is_finance_manager(organization_id))\n  with check (public.is_finance_manager(organization_id))","create policy invoice_items_select_finance on public.invoice_items\n  for select to authenticated\n  using (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id and public.is_finance_manager(i.organization_id)\n  ))","create policy invoice_items_insert_finance on public.invoice_items\n  for insert to authenticated\n  with check (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id and public.is_finance_manager(i.organization_id)\n  ))","create policy invoice_items_update_finance on public.invoice_items\n  for update to authenticated\n  using (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id and public.is_finance_manager(i.organization_id)\n  ))\n  with check (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id and public.is_finance_manager(i.organization_id)\n  ))","create policy payments_select_finance on public.payments\n  for select to authenticated\n  using (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id and public.is_finance_manager(i.organization_id)\n  ))","create policy payments_insert_finance on public.payments\n  for insert to authenticated\n  with check (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id and public.is_finance_manager(i.organization_id)\n  ))","-- An invoice line names a service and an appointment; without these the\n-- finance screens cannot say what was billed for.\ncreate policy services_select_finance on public.services\n  for select to authenticated\n  using (public.is_finance_manager(organization_id))","create policy service_categories_select_finance on public.service_categories\n  for select to authenticated\n  using (public.is_finance_manager(organization_id))","create policy appointments_select_finance on public.appointments\n  for select to authenticated\n  using (public.is_finance_manager(organization_id))","-- ---------------------------------------------------------------------------\n-- Lab — diagnostic tests and their results.\n--\n-- May record a result on a test a doctor ordered (update), but may not order\n-- one: ordering a test is a clinical decision and stays with the doctor, in\n-- line with CLAUDE.md §11. No insert policy is added here for that reason.\n-- ---------------------------------------------------------------------------\n\ncreate policy diagnostics_select_lab on public.diagnostics\n  for select to authenticated\n  using (public.is_lab(organization_id))","create policy diagnostics_update_lab on public.diagnostics\n  for update to authenticated\n  using (public.is_lab(organization_id))\n  with check (public.is_lab(organization_id))","-- Result documents. Scoped through the pet's organization rather than a\n-- blanket grant, so a lab user reaches the files of their own practice only.\ncreate policy documents_select_lab on public.documents\n  for select to authenticated\n  using (exists (\n    select 1 from public.pets p\n    where p.id = pet_id and public.is_lab(p.organization_id)\n  ))","create policy documents_insert_lab on public.documents\n  for insert to authenticated\n  with check (exists (\n    select 1 from public.pets p\n    where p.id = pet_id and public.is_lab(p.organization_id)\n  ))","-- A test hangs off an appointment; the lab queue is unreadable without it.\ncreate policy appointments_select_lab on public.appointments\n  for select to authenticated\n  using (public.is_lab(organization_id))","-- ---------------------------------------------------------------------------\n-- Receptionist — the front desk.\n--\n-- Books and reschedules appointments, and reads the reference data the desk\n-- needs to answer a question at the counter. Everything clinical stays read\n-- only or out of reach entirely: no SOAP records, no prescriptions, and no\n-- ability to record a vaccination that was never given.\n-- ---------------------------------------------------------------------------\n\ncreate policy appointments_select_reception on public.appointments\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy appointments_insert_reception on public.appointments\n  for insert to authenticated\n  with check (public.is_receptionist(organization_id))","create policy appointments_update_reception on public.appointments\n  for update to authenticated\n  using (public.is_receptionist(organization_id))\n  with check (public.is_receptionist(organization_id))","create policy appointment_statuses_select_reception on public.appointment_statuses\n  for select to authenticated\n  using (public.is_receptionist() or public.is_support_staff())","create policy services_select_reception on public.services\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy service_categories_select_reception on public.service_categories\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy doctors_select_reception on public.doctors\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy doctor_availability_select_reception on public.doctor_availability\n  for select to authenticated\n  using (exists (\n    select 1 from public.doctors d\n    where d.id = doctor_id and public.is_receptionist(d.organization_id)\n  ))","-- Vaccination *schedule* information — what is due and when. Read only: a\n-- receptionist tells an owner their pet is due, they do not record the dose.\ncreate policy vaccinations_select_reception on public.vaccinations\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy vaccination_schedules_select_reception on public.vaccination_schedules\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy deworming_records_select_reception on public.deworming_records\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","-- Printing a lab report at the desk: read the test and its result document,\n-- never change either.\ncreate policy diagnostics_select_reception on public.diagnostics\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy documents_select_reception on public.documents\n  for select to authenticated\n  using (exists (\n    select 1 from public.pets p\n    where p.id = pet_id and public.is_receptionist(p.organization_id)\n  ))","-- Notifications and messages.\ncreate policy notifications_select_reception on public.notifications\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy notification_logs_select_reception on public.notification_logs\n  for select to authenticated\n  using (exists (\n    select 1 from public.notifications n\n    where n.id = notification_id and public.is_receptionist(n.organization_id)\n  ))","create policy notification_templates_select_reception on public.notification_templates\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy contact_messages_select_reception on public.contact_messages\n  for select to authenticated\n  using (public.is_receptionist(organization_id))","create policy contact_messages_update_reception on public.contact_messages\n  for update to authenticated\n  using (public.is_receptionist(organization_id))\n  with check (public.is_receptionist(organization_id))","-- ---------------------------------------------------------------------------\n-- Reports.\n--\n-- is_report_viewer() gates every report RPC uniformly — financial, clinical,\n-- client and patient alike. A finance manager needs the financial ones and\n-- must not reach the clinical ones, so widening is_report_viewer() itself\n-- would hand them consultation counts and diagnosis breakdowns. Instead, a\n-- second predicate covers only the financial reports, and only those four\n-- functions are redefined to use it. Their bodies are unchanged from\n-- 20260828000100_reporting.sql; the guard is the single edited line.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.is_financial_report_viewer(p_organization_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select public.is_report_viewer(p_organization_id) or public.is_finance_manager(p_organization_id);\n$$","revoke all on function public.is_financial_report_viewer(uuid) from public, anon","grant execute on function public.is_financial_report_viewer(uuid) to authenticated, service_role","create or replace function public.report_revenue_series(\n  p_organization_id uuid, p_from date, p_to date, p_granularity text default 'day'\n)\nreturns table (period_start date, revenue_paisa bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_financial_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  if p_granularity not in ('day', 'week', 'month') then\n    raise exception 'Invalid granularity.';\n  end if;\n\n  return query\n  select date_trunc(p_granularity, p.paid_at)::date as period_start,\n         coalesce(sum(p.amount_paisa), 0)::bigint as revenue_paisa\n  from public.payments p\n  where p.organization_id = p_organization_id\n    and p.status = 'completed'\n    and p.paid_at::date between p_from and p_to\n  group by 1\n  order by 1;\nend;\n$$","create or replace function public.report_revenue_totals(p_organization_id uuid, p_from date, p_to date)\nreturns table (outstanding_paisa bigint, outstanding_count bigint, paid_paisa bigint, paid_count bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_financial_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select\n    coalesce(sum(balance_paisa) filter (where status in ('issued', 'partially_paid')), 0)::bigint,\n    count(*) filter (where status in ('issued', 'partially_paid'))::bigint,\n    coalesce(sum(total_paisa) filter (where status = 'paid'), 0)::bigint,\n    count(*) filter (where status = 'paid')::bigint\n  from public.invoices\n  where organization_id = p_organization_id\n    and deleted_at is null\n    and issued_at::date between p_from and p_to;\nend;\n$$","create or replace function public.report_revenue_by_service(p_organization_id uuid, p_from date, p_to date)\nreturns table (service_name text, revenue_paisa bigint, quantity bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_financial_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select ii.description as service_name,\n         sum(ii.line_total_paisa)::bigint as revenue_paisa,\n         sum(ii.quantity)::bigint as quantity\n  from public.invoice_items ii\n  join public.invoices i on i.id = ii.invoice_id\n  where i.organization_id = p_organization_id\n    and i.status not in ('draft', 'cancelled')\n    and i.issued_at::date between p_from and p_to\n  group by ii.description\n  order by revenue_paisa desc;\nend;\n$$","create or replace function public.report_revenue_by_doctor(p_organization_id uuid, p_from date, p_to date)\nreturns table (doctor_name text, revenue_paisa bigint)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not public.is_financial_report_viewer(p_organization_id) then\n    raise exception 'You do not have access to reports.';\n  end if;\n\n  return query\n  select coalesce(u.full_name, 'Unassigned') as doctor_name,\n         sum(i.total_paisa)::bigint as revenue_paisa\n  from public.invoices i\n  left join public.appointments a on a.id = i.appointment_id\n  left join public.doctors d on d.id = a.doctor_id\n  left join public.users u on u.id = d.user_id\n  where i.organization_id = p_organization_id\n    and i.status not in ('draft', 'cancelled')\n    and i.issued_at::date between p_from and p_to\n  group by coalesce(u.full_name, 'Unassigned')\n  order by revenue_paisa desc;\nend;\n$$","-- ---------------------------------------------------------------------------\n-- Profile visibility.\n--\n-- 20260909000100_can_view_user_regression_fix.sql asks, in as many words, that\n-- a future addition EXTEND its definition rather than reinvent it from an\n-- older copy — three earlier rewrites each silently dropped clauses. What\n-- follows is that file's function verbatim, with one clause added: the three\n-- new roles see the people in their own organization, the same way an admin\n-- or a doctor already does. Without it a finance manager sees an invoice with\n-- no payer name and a receptionist an appointment with no owner.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.can_view_user(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select\n    p_user_id = (select auth.uid())\n    or public.is_super_admin()\n    -- Clinic-side people see the people in their own organization.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and (\n          public.is_admin(ur.organization_id)\n          or public.is_doctor(ur.organization_id)\n          or public.is_support_staff(ur.organization_id)\n        )\n    )\n    -- Anyone in the organization may see that organization's doctors, which\n    -- is what makes doctor selection possible at booking time.\n    or exists (\n      select 1\n      from public.user_roles ur\n      join public.roles r on r.id = ur.role_id\n      where ur.user_id = p_user_id\n        and ur.revoked_at is null\n        and r.slug = 'doctor'\n        and public.is_org_member(ur.organization_id)\n    )\n    -- An admin keeps seeing someone they manage even after revoking their\n    -- access — deactivating a person must not also make them unmanageable.\n    -- Deliberately not filtered on ur.revoked_at.\n    or exists (\n      select 1\n      from public.user_roles ur\n      where ur.user_id = p_user_id\n        and public.is_admin(ur.organization_id)\n    )\n    -- An admin can also see someone registered into their practice as staff,\n    -- whether currently active or previously removed.\n    or exists (\n      select 1\n      from public.staff s\n      where s.user_id = p_user_id\n        and public.is_admin(s.organization_id)\n    );\n$$"}	staff_roles
20260918000100	{"-- A new practice starts up empty, and every screen that reads reference data\n-- shows nothing: no services to book, no service categories to bill against,\n-- no vaccination schedules to track, no public menu and no page content.\n--\n-- Every seed in this migration set scoped itself to `where o.slug =\n-- 'the-traveling-vet'` (or cross-joined the organizations that happened to\n-- exist that day), and three of them say in as many words that a future\n-- organization-creation flow must seed the table too — see\n-- 20260913000100_nav_menu_items.sql and 20260914000100_home_section_items.sql.\n-- This is that flow's other half: whatever creates the row, the defaults\n-- follow.\n--\n-- A trigger rather than application code, because an organization can be\n-- created from a server action, a migration, a seed script or psql, and a\n-- practice missing its reference data is not a state worth being able to\n-- reach. CLAUDE.md §3 designs for Organization → Branch → … from the start;\n-- this makes the first half of that real.\n\ncreate or replace function public.provision_organization(p_organization_id uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  -- Billing categories. Ordered as they are offered in the invoice editor.\n  insert into public.service_categories (organization_id, name, sort_order)\n  select p_organization_id, category.name, category.sort_order\n  from (values\n    ('Consultation', 10),\n    ('Follow-up', 20),\n    ('Home visit', 30),\n    ('Vaccination', 40),\n    ('Deworming', 50),\n    ('Surgery', 60),\n    ('Diagnostic test', 70),\n    ('Procedure', 80),\n    ('Medicine', 90),\n    ('Other services', 100)\n  ) as category(name, sort_order)\n  where not exists (\n    select 1 from public.service_categories t where t.organization_id = p_organization_id\n  );\n\n  -- Bookable services. Priced at zero on purpose: a real price is the\n  -- practice's decision, and inventing one would put a number on a public\n  -- page that nobody at the clinic chose (CLAUDE.md §9, rule 4).\n  insert into public.services (organization_id, name, description, duration_minutes, sort_order)\n  select p_organization_id, service.name, service.description, service.duration, service.sort_order\n  from (values\n    ('General consultation', 'Routine examination and advice.', 30, 10),\n    ('Follow-up consultation', 'Review of an ongoing problem.', 20, 20),\n    ('Vaccination', 'Scheduled or catch-up vaccination.', 15, 30),\n    ('Deworming', 'Routine parasite treatment.', 15, 40),\n    ('Emergency consultation', 'Urgent, same-day assessment.', 45, 50),\n    ('Surgery', 'Planned surgical procedure.', 90, 60),\n    ('Home visit consultation', 'Examination at the client''s address.', 60, 70)\n  ) as service(name, description, duration, sort_order)\n  where not exists (\n    select 1 from public.services t where t.organization_id = p_organization_id\n  );\n\n  -- Vaccination schedules. Intervals only — what to give, and when it is due\n  -- again. No dose, and nothing that decides treatment for a patient\n  -- (CLAUDE.md §11); the attending veterinarian still records what was given.\n  insert into public.vaccination_schedules\n    (organization_id, species_id, vaccine_name, interval_value, interval_unit, description, sort_order)\n  select p_organization_id, s.id, schedule.vaccine_name, schedule.interval_value, schedule.interval_unit,\n         schedule.description, schedule.sort_order\n  from (values\n    ('DHPP', 'dog', 12, 'months', 'Distemper, hepatitis, parainfluenza, parvovirus.', 10),\n    ('Rabies', 'dog', 12, 'months', 'Required for licensing in most areas.', 20),\n    ('Bordetella', 'dog', 6, 'months', 'Kennel cough, recommended for boarding/grooming.', 30),\n    ('FVRCP', 'cat', 12, 'months', 'Feline viral rhinotracheitis, calicivirus, panleukopenia.', 40),\n    ('Rabies', 'cat', 12, 'months', 'Required for licensing in most areas.', 50)\n  ) as schedule(vaccine_name, species_slug, interval_value, interval_unit, description, sort_order)\n  join public.species s on s.slug = schedule.species_slug\n  where not exists (\n    select 1 from public.vaccination_schedules t where t.organization_id = p_organization_id\n  );\n\n  -- The public site's menu.\n  insert into public.nav_menu_items (organization_id, label, href, position)\n  select p_organization_id, link.label, link.href, link.position\n  from (values\n    ('Home', '/', 0),\n    ('About Us', '/about', 1),\n    ('Services', '/services', 2),\n    ('Doctors', '/doctors', 3),\n    ('Contact Us', '/contact', 4)\n  ) as link(label, href, position)\n  where not exists (\n    select 1 from public.nav_menu_items t where t.organization_id = p_organization_id\n  );\n\n  -- The home and about pages' card lists. Wording matches what the marketing\n  -- pages render by default, so a new practice's site reads as finished rather\n  -- than half-built, and every word is about how this system works — not a\n  -- claim about a clinic nobody has described yet.\n  insert into public.page_section_items (organization_id, page, section, position, icon, title, description)\n  select p_organization_id, item.page, item.section, item.position, item.icon, item.title, item.description\n  from (values\n    ('home', 'services', 0, 'stethoscope', 'Clinic visits', 'Book a consultation at the practice with the doctor of your choice.'),\n    ('home', 'services', 1, 'home', 'Home visits', 'Prefer your pet stay comfortable at home? We come to you.'),\n    ('home', 'services', 2, 'syringe', 'Vaccinations & deworming', 'Every dose recorded, with the next one scheduled automatically.'),\n    ('home', 'services', 3, 'file-text', 'Digital prescriptions', 'Clear, dosed prescriptions you can find again whenever you need them.'),\n    ('home', 'why', 0, 'paw-print', 'One record, always up to date', 'Every visit, vaccination and prescription for your pet lives in one place, not a stack of paper.'),\n    ('home', 'why', 1, 'bell', 'Reminders that keep up', 'Vaccination and deworming due dates are tracked for you, and a reminder goes out before they''re due.'),\n    ('home', 'why', 2, 'receipt', 'Transparent billing', 'Itemized invoices with clear totals, and a record of every payment against them.'),\n    ('home', 'why', 3, 'shield-check', 'Built for your privacy', 'Role-based access means your pet''s records are visible only to you and your care team.'),\n    ('home', 'how_it_works', 0, null, 'Create an account', 'Sign up and add your pet''s basic details.'),\n    ('home', 'how_it_works', 1, null, 'Book an appointment', 'Choose a doctor, a time, and clinic or home visit.'),\n    ('home', 'how_it_works', 2, null, 'Get the full picture', 'SOAP notes, prescriptions and invoices, all in your account afterward.'),\n    ('about', 'values', 0, 'stethoscope', 'Veterinarian-led care', 'Every diagnosis, prescription and treatment plan is made by the attending veterinarian — never automated.'),\n    ('about', 'values', 1, 'map-pin', 'Wherever your pet is comfortable', 'A consultation at the practice, or a visit at home — the same doctors, the same standard of care.'),\n    ('about', 'values', 2, 'heart', 'A record that stays with you', 'Every visit, vaccination and prescription is kept in one place, so nothing is lost between appointments.')\n  ) as item(page, section, position, icon, title, description)\n  where not exists (\n    select 1 from public.page_section_items t where t.organization_id = p_organization_id\n  );\n\nend;\n$$","comment on function public.provision_organization(uuid) is\n  'Gives a newly created practice the reference data every screen expects.\n   Add a new per-organization default here rather than as a one-off seed, or\n   the next practice created will be missing it.'","-- The trigger is a thin wrapper so the backfill below and every future insert\n-- run the exact same body, and cannot drift apart.\ncreate or replace function public.provision_organization_on_insert()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  perform public.provision_organization(new.id);\n  return new;\nend;\n$$","create trigger organizations_provision_defaults\n  after insert on public.organizations\n  for each row execute function public.provision_organization_on_insert()","revoke all on function public.provision_organization(uuid) from public, anon, authenticated","revoke all on function public.provision_organization_on_insert() from public, anon, authenticated","-- Backfill: every organization that already exists and missed one of the\n-- original seeds — the practices created by tests and by hand since, all of\n-- which have been running without services, categories or schedules.\n-- Idempotent by emptiness, not by ON CONFLICT: none of these tables has a\n-- natural unique key — only a uuid primary key — so ON CONFLICT would catch\n-- nothing and a second run would duplicate every default. Each insert instead\n-- runs only when that table is empty for the practice, which also means an\n-- admin who has deleted a default service does not get it handed back.\ndo $$\ndeclare\n  org record;\nbegin\n  for org in select id from public.organizations loop\n    perform public.provision_organization(org.id);\n  end loop;\nend;\n$$"}	provision_organization
20260918000200	{"-- Indexes for lookups the schema never had to serve before.\n--\n-- /admin/users now filters the roster by role and pages through it, which asks\n-- user_roles a question nothing asked previously: \\"this practice's grants of\n-- this one role, newest first\\". Measured on a practice with 1,273 grants, that\n-- planned as a sequential scan reading all 1,144 of its rows to return 25,\n-- then sorting them — user_roles had an index on organization_id alone, which\n-- cannot supply the ordering, so the planner ignored it.\ncreate index user_roles_org_role_created_idx\n  on public.user_roles (organization_id, role_id, created_at desc)\n  where revoked_at is null","-- Plain foreign-key indexes. Postgres does not create these automatically, and\n-- without them every delete of the parent row seq-scans the child table to\n-- check the constraint — medications, service categories and vaccination\n-- schedules are all admin-editable, so those deletes are real.\ncreate index if not exists user_roles_role_id_idx on public.user_roles (role_id)","create index if not exists services_category_id_idx on public.services (category_id)","create index if not exists invoice_items_service_id_idx on public.invoice_items (service_id)","create index if not exists prescription_items_medication_id_idx on public.prescription_items (medication_id)","create index if not exists vaccinations_schedule_id_idx on public.vaccinations (vaccination_schedule_id)","create index if not exists vaccination_schedules_species_id_idx on public.vaccination_schedules (species_id)","create index if not exists diagnostics_document_id_idx on public.diagnostics (document_id)"}	roster_indexes
20260919000100	{"-- Row level security was costing more than the queries it guarded.\n--\n-- Every org-scoped policy in this schema asks a question per row —\n-- is_admin(organization_id), is_doctor(organization_id),\n-- is_org_member(organization_id) — and each of those runs its own EXISTS over\n-- user_roles. Postgres does not memoize a stable function across rows, so\n-- counting a practice's clients ran that lookup once per client.\n--\n-- Measured on this database (543 visible clients):\n--   select count(*) from clients   226 ms\n-- and the three role predicates added in 20260917000100_staff_roles.sql made\n-- it worse, because a second permissive policy is a second per-row call:\n--   the same count                1128 ms\n--\n-- The fix is to ask once instead of per row. A set-returning function taking\n-- no per-row argument is evaluated a single time as an InitPlan, so\n-- `organization_id in (select public.my_org_ids(...))` reads the caller's\n-- grants once and then tests each row against an in-memory list.\n--\n-- Nothing here changes who can see what. Each policy below is the same\n-- predicate rewritten:\n--   is_admin(org)      ->  org in my 'admin' orgs, or super admin\n--   is_doctor(org)     ->  org in my 'doctor' orgs\n--   is_org_member(org) ->  super admin, or org in my orgs by any role\n-- The helper functions are left in place: they are still the right thing for\n-- a single-row check, and other policies still use them.\n--\n-- is_super_admin() is wrapped in `(select ...)` for the same reason. Bare, it\n-- takes no row value but Postgres still calls it once per row, which the plan\n-- shows plainly; as a scalar subquery it becomes an InitPlan evaluated once.\n\ncreate or replace function public.my_org_ids(p_slugs text[])\nreturns setof uuid\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select distinct ur.organization_id\n  from public.user_roles ur\n  join public.roles r on r.id = ur.role_id\n  where ur.user_id = (select auth.uid())\n    and ur.revoked_at is null\n    and r.slug = any (p_slugs);\n$$","comment on function public.my_org_ids(text[]) is\n  'The organizations the caller holds any of these roles in. Written for\n   `organization_id in (select public.my_org_ids(...))`, which Postgres runs\n   once per statement rather than once per row.'","create or replace function public.my_member_org_ids()\nreturns setof uuid\nlanguage sql\nstable\nsecurity definer\nset search_path = ''\nas $$\n  select distinct ur.organization_id\n  from public.user_roles ur\n  where ur.user_id = (select auth.uid())\n    and ur.revoked_at is null;\n$$","revoke all on function public.my_org_ids(text[]) from public, anon","revoke all on function public.my_member_org_ids() from public, anon","grant execute on function public.my_org_ids(text[]) to authenticated, service_role","grant execute on function public.my_member_org_ids() to authenticated, service_role","-- ---------------------------------------------------------------------------\n-- The three role predicates added in 20260917000100, on the tables big enough\n-- for the per-row cost to show. Same access, asked once.\n-- ---------------------------------------------------------------------------\n\ndrop policy clients_select_support_staff on public.clients","create policy clients_select_support_staff on public.clients\n  for select to authenticated\n  using (organization_id in (select public.my_org_ids(array['finance_manager', 'lab', 'receptionist'])))","drop policy pets_select_support_staff on public.pets","create policy pets_select_support_staff on public.pets\n  for select to authenticated\n  using (organization_id in (select public.my_org_ids(array['finance_manager', 'lab', 'receptionist'])))","drop policy invoices_select_finance on public.invoices","create policy invoices_select_finance on public.invoices\n  for select to authenticated\n  using (organization_id in (select public.my_org_ids(array['finance_manager'])))","drop policy payments_select_finance on public.payments","create policy payments_select_finance on public.payments\n  for select to authenticated\n  using (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id\n      and i.organization_id in (select public.my_org_ids(array['finance_manager']))\n  ))","drop policy doctors_select_reception on public.doctors","create policy doctors_select_reception on public.doctors\n  for select to authenticated\n  using (organization_id in (select public.my_org_ids(array['receptionist'])))","drop policy appointments_select_reception on public.appointments","create policy appointments_select_reception on public.appointments\n  for select to authenticated\n  using (organization_id in (select public.my_org_ids(array['receptionist'])))","drop policy appointments_select_finance on public.appointments","create policy appointments_select_finance on public.appointments\n  for select to authenticated\n  using (organization_id in (select public.my_org_ids(array['finance_manager'])))","drop policy appointments_select_lab on public.appointments","create policy appointments_select_lab on public.appointments\n  for select to authenticated\n  using (organization_id in (select public.my_org_ids(array['lab'])))","-- ---------------------------------------------------------------------------\n-- The original predicates on the same tables, which carried the other half of\n-- the cost long before the new roles existed.\n-- ---------------------------------------------------------------------------\n\ndrop policy clients_select on public.clients","create policy clients_select on public.clients\n  for select to authenticated\n  using (\n    user_id = (select auth.uid())\n    or (select public.is_super_admin())\n    or organization_id in (select public.my_org_ids(array['admin', 'doctor']))\n  )","drop policy pets_select on public.pets","create policy pets_select on public.pets\n  for select to authenticated\n  using (\n    public.owns_client(client_id)\n    or (select public.is_super_admin())\n    or organization_id in (select public.my_org_ids(array['admin', 'doctor']))\n  )","drop policy doctors_select on public.doctors","create policy doctors_select on public.doctors\n  for select to authenticated\n  using (\n    (select public.is_super_admin())\n    or organization_id in (select public.my_member_org_ids())\n  )","drop policy invoices_select on public.invoices","create policy invoices_select on public.invoices\n  for select to authenticated\n  using (\n    (select public.is_super_admin())\n    or organization_id in (select public.my_org_ids(array['admin', 'doctor']))\n    -- Last: the only clause that depends on the row, so the hoisted checks\n    -- above settle a clinic-side reader before it is ever reached.\n    or (public.owns_client(client_id) and status <> 'draft')\n  )","drop policy payments_select on public.payments","create policy payments_select on public.payments\n  for select to authenticated\n  using (exists (\n    select 1 from public.invoices i\n    where i.id = invoice_id\n      and (\n        (select public.is_super_admin())\n        or i.organization_id in (select public.my_org_ids(array['admin', 'doctor']))\n        or (public.owns_client(i.client_id) and i.status <> 'draft')\n      )\n  ))"}	rls_org_scope_cache
20260919000200	{"-- The same InitPlan rewrite as 20260919000100, applied to every remaining\n-- policy in the schema: 127 of them across 37 tables.\n--\n-- Same reasoning, same guarantee. A policy calling is_admin(organization_id)\n-- runs an EXISTS over user_roles once per row, because Postgres does not\n-- memoize a stable function across rows. Asking through a set-returning\n-- function that takes no per-row argument turns it into an InitPlan evaluated\n-- once per statement:\n--\n--   is_admin(org)      ->  (select is_super_admin()) or org in my 'admin' orgs\n--   is_doctor(org)     ->  org in my 'doctor' orgs\n--   is_org_member(org) ->  (select is_super_admin()) or org in my orgs\n--   is_support_staff / is_finance_manager / is_lab / is_receptionist likewise\n--   is_super_admin()   ->  (select is_super_admin())   -- hoisted, not per row\n--\n-- The no-argument forms (is_admin(), is_support_staff()) mean \\"in any\n-- organization at all\\" and only needed the scalar-subquery wrapper.\n-- Row-dependent predicates — owns_client, owns_pet, can_access_pet,\n-- can_view_user, has_finalized_soap — are untouched: they genuinely depend on\n-- the row, and rewriting them would change meaning rather than cost.\n--\n-- These statements were generated from pg_policies rather than retyped, so\n-- each predicate is the one that was there, with only the role clauses\n-- substituted. Verified two ways before landing:\n--\n--   * Visible-row counts for one user of each of the six roles against all 42\n--     policied tables — 252 measurements — identical before and after.\n--   * The full suite, 439 tests, including the rls, permission-matrix,\n--     client-portal and staff-roles boundary tests.\n--\n-- The helper functions stay: they remain correct for a single-row check, and\n-- application code still calls them.\n\ndrop policy appointment_statuses_select_reception on public.\\"appointment_statuses\\"","create policy appointment_statuses_select_reception on public.\\"appoi