\\"\n  for insert to authenticated\n  with check ((((select public.is_super_admin()) or (organization_id) in (select public.my_org_ids(array['admin']))) AND ((select public.is_super_admin()) OR (( SELECT r.slug\n   FROM roles r\n  WHERE (r.id = user_roles.role_id)) <> 'super_admin'::text))))","drop policy user_roles_select on public.\\"user_roles\\"","create policy user_roles_select on public.\\"user_roles\\"\n  for select to authenticated\n  using (((user_id = ( SELECT auth.uid() AS uid)) OR ((select public.is_super_admin()) or (organization_id) in (select public.my_org_ids(array['admin'])))))","drop policy user_roles_update on public.\\"user_roles\\"","create policy user_roles_update on public.\\"user_roles\\"\n  for update to authenticated\n  using (((select public.is_super_admin()) or (organization_id) in (select public.my_org_ids(array['admin']))))\n  with check (((select public.is_super_admin()) or (organization_id) in (select public.my_org_ids(array['admin']))))","drop policy vaccination_schedules_insert on public.\\"vaccination_schedules\\"","create policy vaccination_schedules_insert on public.\\"vaccination_schedules\\"\n  for insert to authenticated\n  with check (((select public.is_super_admin()) or (organization_id) in (select public.my_org_ids(array['admin']))))","drop policy vaccination_schedules_select on public.\\"vaccination_schedules\\"","create policy vaccination_schedules_select on public.\\"vaccination_schedules\\"\n  for select to authenticated\n  using (((select public.is_super_admin()) or (organization_id) in (select public.my_member_org_ids())))","drop policy vaccination_schedules_select_reception on public.\\"vaccination_schedules\\"","create policy vaccination_schedules_select_reception on public.\\"vaccination_schedules\\"\n  for select to authenticated\n  using (((organization_id) in (select public.my_org_ids(array['receptionist']))))","drop policy vaccination_schedules_update on public.\\"vaccination_schedules\\"","create policy vaccin