--

CREATE POLICY invoice_pdfs_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'invoice-pdfs'::text) AND (EXISTS ( SELECT 1
   FROM public.clients c
  WHERE ((c.id = public.client_id_from_object_path(objects.name)) AND public.is_billing_manager(c.organization_id))))));


--
-- Name: objects invoice_pdfs_select; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY invoice_pdfs_select ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = 'invoice-pdfs'::text) AND ((EXISTS ( SELECT 1
   FROM public.clients c
  WHERE ((c.id = public.client_id_from_object_path(objects.name)) AND (public.is_admin(c.organization_id) OR public.is_doctor(c.organization_id))))) OR (EXISTS ( SELECT 1
   FROM public.invoices i
  WHERE ((i.pdf_path = objects.name) AND (i.status <> 'draft'::text) AND public.owns_client(i.client_id)))))));


--
-- Name: objects invoice_pdfs_update; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY invoice_pdfs_update ON storage.objects FOR UPDATE TO authenticated USING (((bucket_id = 'invoice-pdfs'::text) AND (EXISTS ( SELECT 1
   FROM public.clients c
  WHERE ((c.id = public.client_id_from_object_path(objects.name)) AND public.is_billing_manager(c.organization_id)))))) WITH CHECK (((bucket_id = 'invoice-pdfs'::text) AND (EXISTS ( SELECT 1
   FROM public.clients c
  WHERE ((c.id = public.client_id_from_object_path(objects.name)) AND public.is_billing_manager(c.organization_id))))));


